window.NIGHTS.cases[5]={"nr":5,"id":"case05","title":"Der Kult des Gottkönigs","subtitle":"","level":"Mystische Ebene","from":113,"to":149,"mythen":[],"sections":[{"id":"titel-und-pitch","kind":"intro","title":"Titel und Pitch","page":113,"layer":null,"blocks":4},{"id":"ein-weg-zur-erleuchtung","kind":"place","title":"EIN WEG ZUR ERLEUCHTUNG","page":114,"layer":null,"blocks":5},{"id":"ausbeutung-des-heiligen","kind":"place","title":"AUSBEUTUNG DES HEILIGEN","page":114,"layer":null,"blocks":3},{"id":"von-suchenden-zu-juenger-in-nen","kind":"place","title":"VON SUCHENDEN ZU JÜNGER:IN- NEN","page":114,"layer":null,"blocks":41},{"id":"rissernte","kind":"place","title":"RISSERNTE","page":115,"layer":null,"blocks":8},{"id":"der-zirkel","kind":"place","title":"DER ZIRKEL","page":116,"layer":null,"blocks":55},{"id":"schicht-0-aufhaenger","kind":"layer","title":"SCHICHT 0: AUFHÄNGER","page":124,"layer":null,"blocks":19},{"id":"ariadne-und-magnum-opus","kind":"place","title":"ARIADNE UND MAGNUM OPUS","page":126,"layer":"schicht-0-aufhaenger","blocks":4},{"id":"ariadne-ins-spiel-bringen","kind":"place","title":"ARIADNE INS SPIEL BRINGEN","page":126,"layer":"schicht-0-aufhaenger","blocks":13},{"id":"schicht-1-eine-kerze-in-der-dunkelheit","kind":"layer","title":"SCHICHT 1: EINE KERZE IN DER DUNKELHEIT","page":127,"layer":null,"blocks":47},{"id":"1x1-der-alchemie","kind":"place","title":"1X1 DER ALCHEMIE","page":130,"layer":"schicht-1-eine-kerze-in-der-dunkelheit","blocks":26},{"id":"chinatown-festival","kind":"place","title":"CHINATOWN-FESTIVAL","page":131,"layer":"schicht-1-eine-kerze-in-der-dunkelheit","blocks":14},{"id":"mondgeist","kind":"place","title":"MONDGEIST","page":133,"layer":"schicht-1-eine-kerze-in-der-dunkelheit","blocks":15},{"id":"schicht-2-gefaehrliche-ausgrabungen","kind":"layer","title":"SCHICHT 2: GEFÄHRLICHE AUSGRABUNGEN","page":134,"layer":null,"blocks":1},{"id":"val-riens-kuriosa","kind":"place","title":"VALÉRIENS KURIOSA","page":134,"layer":"schicht-2-gefaehrliche-ausgrabungen","blocks":68},{"id":"schicht-3-schatten-der-wahrheit","kind":"layer","title":"SCHICHT 3: SCHATTEN DER WAHRHEIT","page":140,"layer":null,"blocks":1},{"id":"whirlers-kommune","kind":"place","title":"WHIRLERS KOMMUNE","page":140,"layer":"schicht-3-schatten-der-wahrheit","blocks":59},{"id":"alona-wainwright","kind":"place","title":"ALONA WAINWRIGHT","page":144,"layer":"schicht-3-schatten-der-wahrheit","blocks":19},{"id":"schicht-4-das-heilige-feuer","kind":"layer","title":"SCHICHT 4: DAS HEILIGE FEUER","page":146,"layer":null,"blocks":1},{"id":"die-katakomben","kind":"place","title":"DIE KATAKOMBEN","page":146,"layer":"schicht-4-das-heilige-feuer","blocks":58}],"pages":{"113":{"tab":"","blocks":[{"t":"sh","x":"<b>EIN MYSTERIÖSER FALL VOLLER DUNKLER GEHEIMNISSE</b>","sz":20,"box":[104.5,776.1,490.8,796.1],"p":113,"i":0,"sec":"titel-und-pitch"}],"size":[595.276,841.89]},"114":{"tab":"","blocks":[{"t":"p","x":"Man hört es über dem Kopfsteinpflaster der Altstadt, im Rauschen des Meeres an den Docks und als Hall tief unten in verlassenen U-Bahn-Tunneln. Es ist wie ein alter Bannspruch oder ein geflüstertes Rezept, ein Funke, der das schmelzende Feuer entzündet. Sie versammeln sich, sie sind erwacht, und nun müssen sie ihrem Meister dienen. Sucht ihr wie sie nach Erleuchtung oder unermesslicher Macht? Was seid ihr bereit, dem Gottkönig zu opfern?","sz":13,"box":[53.9,73.4,284.1,245.9],"p":114,"i":0,"sec":"titel-und-pitch"},{"t":"p","x":"<i>Der Kult des Gottkönigs</i> ist ein Psychothriller, der eine mystische Selbstfindung unter Anleitung eines zwielichtigen Kults beschreibt. Die Protagonist:innen können die Reise als spirituell Suchende antreten oder als Zyniker:innen versuchen, die wahren Motive der Kult zu entschlüsseln, bevor es zu spät ist. Je näher der Höhepunkt ihres Plans rückt und je mehr auf dem Spiel steht, desto mehr werden die Hauptfiguren zerbrechen, die Seiten wechseln, ein tieferes Verständnis der Stadt erlangen und ihre wahre Natur offenbaren.","sz":9.5,"box":[53.9,256.4,286.7,378.4],"p":114,"i":1,"sec":"titel-und-pitch"},{"t":"p","x":"Dieser Fall taucht kopfüber in die okkulten Kreise der Stadt ein, erforscht die zahllosen Überlieferungen der mittelalterlichen Alchemie als Weg zur spirituellen Entwicklung und kombiniert sie mit dem Geheimnis der Stadt und des Nebels. <b>Er spielt sich am besten, wenn mindestens ein SC dem Kult beitritt und bereit ist, alles zu tun, um Antworten zu finden.</b>","sz":9.5,"box":[53.9,387.1,281.2,471.7],"p":114,"i":2,"sec":"titel-und-pitch"},{"t":"h","x":"EIN WEG ZUR ERLEUCHTUNG","sz":16,"box":[53.9,523.6,242,539.6],"p":114,"i":3,"skip":true,"sec":"ein-weg-zur-erleuchtung"},{"t":"p","x":"Das große Werk der mittelalterlichen Alchemisten, das <b>Magnum Opus</b>, drehte sich um die Erschaffung des Steins der Weisen, der unedle Metalle in Gold verwandeln und ewiges Leben gewähren konnte. Das Geheimnis dieses begehrten Rezepts ist, dass es eine Allegorie darstellt. Obschon es die Umwandlung von Metallen beschreibt, besteht sein wahrer Nutzen darin, die <b>Seele</b> von einem verlorenen und blinden Zustand (Schläfer:in) in einen erwachten (Riss) und schließlich in einen Zustand der Verschmelzung mit der gesamten Existenz <b>zu überführen</b>, wodurch das Individuum sein ultimatives Potenzial erreicht: die Wiedervereinigung mit der Quelle.","sz":9.5,"box":[53.9,543.5,285.9,703],"p":114,"i":4,"sec":"ein-weg-zur-erleuchtung"},{"t":"p","x":"Nach dem Magnum Opus sind vier Phasen zur Erreichung dieses Wandels notwendig:","sz":9.5,"box":[309,73.2,529.5,95.2],"p":114,"i":5,"sec":"ein-weg-zur-erleuchtung"},{"t":"p","x":"• <b>Fäulnis oder Schwärzung</b>: Auseinandersetzung mit der eigenen dunklen Seite und Nichtigkeit • <b>Läuterung oder Weißung:</b> Aufgabe weltlicher Bestrebungen • <b>Erwachen oder Gilbung:</b> Erkenntnis der eigenen wahren Natur • <b>Transformation oder Rötung:</b> Ultimative Umwandlung, Vereinigung mit der Quelle","sz":9.5,"box":[309,101.1,540.5,198.1],"p":114,"i":6,"sec":"ein-weg-zur-erleuchtung"},{"t":"p","x":"In der Stadt meint „die Quelle“ das, was jenseits des Nebels existiert, vielleicht sogar jenseits des Reiches der Mythen. Das ultimative Ziel dieses Prozesses ist es, die Ketten des Nebels zu sprengen und die höchste Bewusstseinsebene zu erreichen.","sz":9.5,"box":[309,203.9,536.2,263.4],"p":114,"i":7,"sec":"ein-weg-zur-erleuchtung"},{"t":"h","x":"AUSBEUTUNG DES HEILIGEN","sz":16,"box":[309,279.1,493.8,295.1],"p":114,"i":8,"skip":true,"sec":"ausbeutung-des-heiligen"},{"t":"p","x":"Es könnte ein Weg zur Erleuchtung sein, doch der Kult, der sich selbst „Magnum Opus“ nennt, hat ihn entweiht und nutzt ihn für seine eigenen dunklen Ziele: die <b>rituelle Erweckung und Ernte von Rissen</b>. Unter dem Deckmantel der Selbstfindung führt der Kult Menschen durch die ersten drei Stufen und <b>verwandelt sie in Risse</b>, mit gleichzeitiger Gehirnwäsche, damit sie ihr Idol, <b>den Gottkönig</b> (eine Galionsfigur, die die schwer fassbare „Quelle“ ersetzt), anbeten.","sz":9.5,"box":[309,299,540.7,408.5],"p":114,"i":9,"sec":"ausbeutung-des-heiligen"},{"t":"p","x":"Auf der vierten Stufe <b>beraubt der Kult die unterwürfigen Risse jedoch ihrer Kräfte,</b> entsorgt sie und nutzt ihre Mythos-Kräfte, um den Einfluss der gierigen Kultführer:innen, des Rates des <b>Zirkels</b>, zu mehren (und um Armand Kais Angst vor dem Tod zu schüren und nach dem Lebenselixier suchen zu lassen, wenn du den Metaplot spielst.)","sz":9.5,"box":[309,417.2,541.3,501.7],"p":114,"i":10,"sec":"ausbeutung-des-heiligen"},{"t":"h","x":"VON SUCHENDEN ZU JÜNGER:IN- NEN","sz":16,"box":[309,517.4,525.1,550.4],"p":114,"i":11,"skip":true,"sec":"von-suchenden-zu-juenger-in-nen"},{"t":"p","x":"Die Diener:innen des Gottkönigs sind in Ränge eingeteilt, die sich nach der Stufe richten, die sie im Magnum-Opus-Prozess erreicht haben (s. S. Tabelle). Auf dem Weg nach oben müssen Mitglieder sich einem Weiheritual für die jeweils nächste Stufe unterziehen.","sz":9.5,"box":[309,554.3,539.6,613.8],"p":114,"i":12,"sec":"von-suchenden-zu-juenger-in-nen"},{"t":"p","x":"Aufgrund ihres Wesens und ihrer Wünsche unterteilen sich die Kultist:innen in zwei Gruppen:","sz":9.5,"box":[309,622.4,538.5,644.4],"p":114,"i":13,"sec":"von-suchenden-zu-juenger-in-nen"},{"t":"p","x":"• <b>Lämmer</b>, Kandidat:innen, die nach Erleuchtung streben und dazu bestimmt sind, als Riss erweckt zu werden, damit der Kult ihren Mythos ernten kann.","sz":9.5,"box":[309,655.9,536.7,690.4],"p":114,"i":14,"sec":"von-suchenden-zu-juenger-in-nen"}],"size":[595.276,841.89]},"115":{"tab":"","blocks":[{"t":"p","x":"<b>I</b>","sz":10,"box":[200.1,67.8,202.3,77.8],"p":115,"i":0,"sec":"von-suchenden-zu-juenger-in-nen"},{"t":"p","x":"<b>II</b>","sz":10,"box":[295,67.8,299.6,77.8],"p":115,"i":1,"sec":"von-suchenden-zu-juenger-in-nen"},{"t":"p","x":"<b>Stufe</b> Schwärzung Weißung","sz":8,"box":[95.5,81,312.9,89],"p":115,"i":2,"sec":"von-suchenden-zu-juenger-in-nen"},{"t":"p","x":"<b>Alchemistische</b> Fäulnis Läuterung","sz":8,"box":[77.3,94.1,315.3,102.1],"p":115,"i":3,"sec":"von-suchenden-zu-juenger-in-nen"},{"t":"p","x":"<b>Bedeutung</b>","sz":8,"box":[85.6,106.1,124.6,114.1],"p":115,"i":4,"sec":"von-suchenden-zu-juenger-in-nen"},{"t":"sh","x":"<b>III</b>","sz":10,"box":[389.9,67.8,396.8,77.8],"p":115,"i":5,"sec":"von-suchenden-zu-juenger-in-nen"},{"t":"p","x":"<b>IV</b>","sz":10,"box":[486.3,67.8,492.7,77.8],"p":115,"i":6,"sec":"von-suchenden-zu-juenger-in-nen"},{"t":"p","x":"Gilbung Rötung","sz":8,"box":[379.8,81,502.2,89],"p":115,"i":7,"sec":"von-suchenden-zu-juenger-in-nen"},{"t":"p","x":"Erwachen Transformation","sz":8,"box":[375.9,94.1,516.9,102.1],"p":115,"i":8,"sec":"von-suchenden-zu-juenger-in-nen"},{"t":"p","x":"<b>Mystische Bedeutung</b> Seine dunklen Seite Aufgabe weltlicher","sz":8,"box":[66.1,119.2,330.3,127.2],"p":115,"i":9,"sec":"von-suchenden-zu-juenger-in-nen"},{"t":"p","x":"verstehen Bestrebungen","sz":8,"box":[183.8,131.2,321.9,139.2],"p":115,"i":10,"sec":"von-suchenden-zu-juenger-in-nen"},{"t":"p","x":"<b>Rang</b> Suchende Anhänger:innen","sz":8,"box":[95.9,144.3,325.1,152.3],"p":115,"i":11,"sec":"von-suchenden-zu-juenger-in-nen"},{"t":"p","x":"Selbsterkenntnis Erleuchtung und","sz":8,"box":[363.8,119.2,518.3,127.2],"p":115,"i":12,"sec":"von-suchenden-zu-juenger-in-nen"},{"t":"p","x":"ultimative Macht","sz":8,"box":[459.8,131.2,519.2,139.2],"p":115,"i":13,"sec":"von-suchenden-zu-juenger-in-nen"},{"t":"p","x":"Initiant:innen Jünger:innen","sz":8,"box":[370.5,144.3,512.5,152.3],"p":115,"i":14,"sec":"von-suchenden-zu-juenger-in-nen"},{"t":"p","x":"<b>Lehrer:innen</b> <u>Prof. Clay</u> Whirler (in <u>Whirlers</u>","sz":8,"box":[82.4,157.4,330.9,165.4],"p":115,"i":15,"sec":"von-suchenden-zu-juenger-in-nen"},{"t":"p","x":"<u>Kommune)</u>","sz":8,"box":[277.6,169.4,317,177.4],"p":115,"i":16,"sec":"von-suchenden-zu-juenger-in-nen"},{"t":"p","x":"<b>Graduierungsritual</b> <u>Die Silo-Prüfung Das Narrenfest</u>","sz":8,"box":[71.5,182.5,324,190.5],"p":115,"i":17,"sec":"von-suchenden-zu-juenger-in-nen"},{"t":"p","x":"Jünger:innen für Wölf:innen: der","sz":8,"box":[370.4,157.4,521.9,165.4],"p":115,"i":18,"sec":"von-suchenden-zu-juenger-in-nen"},{"t":"p","x":"Zirkel oder Armand Kai","sz":8,"box":[448.9,169.4,530,177.4],"p":115,"i":19,"sec":"von-suchenden-zu-juenger-in-nen"},{"t":"p","x":"Salbung in den Athanor/Canseliet","sz":8,"box":[367.2,182.5,521.8,190.5],"p":115,"i":20,"sec":"von-suchenden-zu-juenger-in-nen"},{"t":"p","x":"<u>Katakomben</u> Manor","sz":8,"box":[370.8,194.5,501,202.5],"p":115,"i":21,"sec":"von-suchenden-zu-juenger-in-nen"},{"t":"p","x":"<b>Wölf:innen</b> Skrupellosigkeit dem früheren Leben","sz":8,"box":[85.8,207.6,332.9,215.6],"p":115,"i":22,"sec":"von-suchenden-zu-juenger-in-nen"},{"t":"p","x":"beweisen abschwören","sz":8,"box":[184.3,219.6,319,227.6],"p":115,"i":23,"sec":"von-suchenden-zu-juenger-in-nen"},{"t":"p","x":"Transmutationen neue Transmutation und","sz":8,"box":[363.1,207.6,532.5,215.6],"p":115,"i":24,"sec":"von-suchenden-zu-juenger-in-nen"},{"t":"p","x":"erhalten Tinkturen erhalten","sz":8,"box":[378.9,219.6,521.7,227.6],"p":115,"i":25,"sec":"von-suchenden-zu-juenger-in-nen"},{"t":"p","x":"<b>Lämmer</b> Unschuld beweisen dem früheren Leben","sz":8,"box":[90.2,232.6,332.9,240.6],"p":115,"i":26,"sec":"von-suchenden-zu-juenger-in-nen"},{"t":"p","x":"abschwören","sz":8,"box":[275.6,244.6,319,252.6],"p":115,"i":27,"sec":"von-suchenden-zu-juenger-in-nen"},{"t":"p","x":"• <b>Wölfe</b>, Anwärter:innen, die nach Macht über Andere streben und dazu bestimmt sind, die Führer:innen der Kult zu werden und die von den Lämmern gewonnene Macht zu kontrollieren.","sz":9.5,"box":[53.9,296.3,284.1,343.3],"p":115,"i":28,"sec":"von-suchenden-zu-juenger-in-nen"},{"t":"sh","x":"<b>DIE SCHWÄRZUNG</b>","sz":10,"box":[54.3,354.1,155.1,364.1],"p":115,"i":29,"sec":"von-suchenden-zu-juenger-in-nen"},{"t":"p","x":"Der Kult rekrutiert <b>Suchende</b> aus der ganzen Stadt, die Interesse am Okkulten oder spiritueller Entwicklung zeigen. Der wichtigste Rekrutierer ist einer der ranghöchsten Jünger, der charismatische <u>Prof. Clay,</u> ein Philosophieprofessor an der Altstadt-Uni. Er ist für den ersten Schritt auf der Reise der Kandidat:innen verantwortlich: Er konfrontiert die Neulinge mit ihren Schwächen und fordert sie auf, sich des Geheimwissens, das er besitzt, würdig zu erweisen. Außerdem erstellt er ein psychologisches Profil, das sie als Lämmer oder Wölf:innen einteilt. Am Ende der Schwärzung unterziehen sich beide Gruppen der <u>Silo-Prüfung,</u> um Prof. Clay ihren Wert zu beweisen.","sz":9.5,"box":[53.9,369.7,284,529.2],"p":115,"i":30,"sec":"von-suchenden-zu-juenger-in-nen"},{"t":"sh","x":"<b>DIE WEISSUNG</b>","sz":10,"box":[54.3,542.8,135.1,552.8],"p":115,"i":31,"sec":"von-suchenden-zu-juenger-in-nen"},{"t":"p","x":"Die nun <b>Anhänger:innen</b> bezeichneten Prüflinge ziehen zu <b>Whirler</b> (Tinktur Krishnas), und leben mit ihr auf der Straße, bis sie lernen, ihr früheres Leben und erlernte gesellschaftliche Normen abzulegen. Whirler weiht die Anhänger:innen in einer Feier, dem <u>Narrenfest,</u> auf dessen Höhepunkt sie ihr Leben als Kultist:innen im Dienste des Gottkönigs beginnen.","sz":9.5,"box":[53.9,558.4,285.2,642.9],"p":115,"i":32,"sec":"von-suchenden-zu-juenger-in-nen"},{"t":"sh","x":"<b>DIE GILBUNG</b>","sz":10,"box":[54.3,656.5,126.2,666.5],"p":115,"i":33,"sec":"von-suchenden-zu-juenger-in-nen"},{"t":"p","x":"Die neuen <b>Initiant:innen</b> werden zu Agent:innen des Kults. Man bringt sie in die <u>Katakomben,</u> die Operationsbasis des Kults, die in verlassenen U-Bahn-Tunneln versteckt liegt und unter der Leitung der gläubigsten","sz":9.5,"box":[53.9,672,285.1,719],"p":115,"i":34,"sec":"von-suchenden-zu-juenger-in-nen"},{"t":"p","x":"als Risse erwachen geerntet werden","sz":8,"box":[359.2,232.6,518.3,240.6],"p":115,"i":35,"sec":"von-suchenden-zu-juenger-in-nen"},{"t":"p","x":"Jünger:innen steht. Dort bereiten sie sich auf ihre <b>Salbung</b> vor, das Erweckungsritual. Während die Lämmer auf ihre Erweckung warten, nehmen Wolfs-Initiant:innen an geheimen Aktivitäten teil, um dem Willen des Gottkönigs zu dienen: Sie schüchtern Personen ein, die eine Bedrohung sein könnten, verletzen, stehlen Relikte, dienen als Wachen usw. Diese Phase gipfelt in einem Ritual, das Lämmer zu <b>Rissen</b> erweckt und Wölf:innen mit alchemistischen Symbolen brandmarkt, was ihnen die Macht der <b>Transmutation</b> verleiht und sie zu vollwertigen <b>Jünger:innen</b> macht.","sz":9.5,"box":[309,296.3,539,431],"p":115,"i":36,"sec":"von-suchenden-zu-juenger-in-nen"},{"t":"h","x":"RISSERNTE","sz":16,"box":[309,446.5,383.8,462.5],"p":115,"i":37,"skip":true,"sec":"rissernte"},{"t":"p","x":"In der vierten und letzten Phase, der <b>Rötung</b>, werden die zuvor erweckten Lämmer ihrer Mythos-Kräfte beraubt. Da sie von Beginn an einer Gehirnwäsche unterzogen wurden, fügen sich die meisten ohne Protest.","sz":9.5,"box":[309,466.4,539.6,513.4],"p":115,"i":38,"sec":"rissernte"},{"t":"p","x":"Sobald die Mythos-Kräfte der Lämmer extrahiert und dem „Gottkönig“ übergeben sind, erhalten die Wölf:innen, die damit ihre sogenannte heilige Pflicht erfüllen, Zugang zu alchemistischen Transmutationen und können Anwärter:innen für den Rat des Zirkels werden. Angeblich beschenkt der Gottkönig den Zirkel manchmal mit einer Tinktur, gewonnen aus dem Ichor des geernteten Risses. Die seelenlose Hülle, die einst ein Lamm war, kehrt als mythoslose Schläfer:in in die Stadt zurück, ohne Hoffnung, je wieder zu erwachen.","sz":9.5,"box":[309,522.1,538.6,644.1],"p":115,"i":39,"sec":"rissernte"}],"size":[595.276,841.89]},"116":{"tab":"","blocks":[{"t":"h","x":"ALCHEMISTISCHE KRÄFTE","sz":14,"box":[65.2,96.4,188.5,110.4],"p":116,"i":0,"sec":"rissernte"},{"t":"p","x":"Wie in der Einleitung dieser Ebene erläutert (s. S. 86) verfügen die Anhänger:innen und Verbündeten von Armands Kult über zwei Formen der alchemistischen Magie: <b>Tinkturen</b> und <b>Transmutationen</b>.","sz":9,"box":[65.2,122.9,270.4,167.9],"p":116,"i":1,"sec":"rissernte"},{"t":"p","x":"Tinkturen sind Relikte, die der Anführer des Kultes (Armand) aus Mythos-Essenz herstellt. Es sind Fläschchen, die die flüssige Essenz eines Mythos enthalten. Im Gegensatz zu den meisten Relikten wählen sie ihren Träger nicht aus, sondern verleihen dem, der sie besitzt, die Macht eines Mythos.","sz":9,"box":[65.2,176.6,270.8,245.6],"p":116,"i":2,"sec":"rissernte"},{"t":"p","x":"Transmutationen sind alchemistische Formeln, die es Jünger:innen gestatten, die alchemistischen Elemente zu kontrollieren und zu manipulieren. Nur Wölf:innen im Rang von Jünger:innen lernen Transmutationen und sind damit von Armands Mythos berührt.","sz":9,"box":[65.2,254.3,268.1,323.3],"p":116,"i":3,"sec":"rissernte"},{"t":"p","x":"Wenn du den Metaplot spielst, findet die Ernte im alten Ofen der Aurora-Glashütte statt (s. S. <i>Athanor</i>, S. 105) oder, wenn der Kult den Ofen nicht mehr kontrolliert, in <u>Canseliet Manor</u> durch Armand Kai selbst (s. S. <i>Der Alchemist</i>, S. 155). Wenn du diesen Fall als losgelöstes Abenteuer spielst, führt der Zirkel das Ernteritual in einem Teil der <u>Katakomben</u> durch.","sz":9.5,"box":[53.9,370,283.9,454.5],"p":116,"i":4,"sec":"rissernte"},{"t":"h","x":"DER ZIRKEL","sz":16,"box":[53.9,470.2,129.6,486.2],"p":116,"i":5,"skip":true,"sec":"der-zirkel"},{"t":"p","x":"Die Mitglieder des Zirkels wählen loyale, erfahrene Jünger:innen aus, um dem Zirkel beizutreten. Sie haben große Macht, sowohl in magischer (dank der Mythos-Tinkturen) als politisch über ihr Berufs- und Privatleben. Alle Mitglieder des Zirkels tragen einen Teil der Tinktur der biblischen Heiligen Drei Könige (der drei Weisen, die dem Stern der Geburt Jesu folgten), was ihnen die Macht der <b>astrologischen Weissagung</b> verleiht, um mögliche Störungen ihrer Aktivitäten vorherzusehen.","sz":9.5,"box":[53.9,490.1,281.8,612.1],"p":116,"i":6,"sec":"der-zirkel"},{"t":"p","x":"<b>Alona Wainwright</b>, eine Geschäftsfrau und Kunstsammlerin, die den Kult mitfinanziert und ihre Anwält:innen einsetzt, um ihn von unerwünschter Aufmerksamkeit zu bewahren, ist das prominenteste Mitglied des Zirkels. Sie hat Söldner:innen angeheuert und mit Mythos-Tinkturen ausgestattet, um den Kult zu schützen. Zusätzlich nutzt Wainwright ihre Verbindungen zu Kunstsammler:innen, um <b>Relikte für die Ernte zu bekommen</b> und so weitere Mythos-Tinkturen zu gewinnen.","sz":9.5,"box":[53.9,620.8,283.3,742.8],"p":116,"i":7,"sec":"der-zirkel"},{"t":"card","x":"EIN ECHTER KULT-KLASSIKER Hier sind einige filmische Tropen über Kulte, die du berücksichtigen solltest, wenn du das Magnum Opus spielerisch umsetzt: • <b>Der Kult ist undurchsichtig.</b> Nur Eingeweihte verstehen Innenleben und Motive. • <b>Der Kult ist überall.</b> Jeder könnte ein heimliches Mitglied sein. • <b>Der Kult ist dem Team immer einen Schritt voraus.</b> Durch überlegte Taktik und die astrologischen Wahrsagungen des Zirkels scheint Magnum Opus eine Lösung für jede Einmischung des Teams zu haben, so dass es fast abschätzig wirkt. • <b>Der Kult ist rücksichtslos, wie es nur Fanatiker sein können.</b> Lämmer oder Wölf:innen, die nach absoluter Wahrheit und Macht streben, scheren sich nicht um das Leben von Schläfer:innen oder die Moral von verblendeten Rissen. Die Kultist:innen sind bereit, jeden auszulöschen, der sich ihnen auf dem Weg zur Erleuchtung in den Weg stellt, manche mit Bedauern, andere mit Eifer. • <b>Der Kult ist allmächtig.</b> Aus Sicht des Teams scheint der Kult über unbegrenzten Einfluss und noch nie dagewesene Formen der Magie zu verfügen, die Mythos-Kraft rauben kann (Armands Alchemie), was eine Macht ist, die zu stark scheint, um sie zu bekämpfen. • <b>Nenn es nicht „Kult“:</b> Anhänger:innen des Magnum Opus bezeichnen diesen nicht als Kult und sich nicht als Kultist:innen. Andere NSC wissen nicht genug darüber. Vermeide es, durch den Begriffs „Kult“ zu viel zu verraten, bis die SC aufgrund ihrer Nachforschungen dieses Wort selbst einführen.","sz":null,"k":"yellow","box":[305.3,81.8,539.1,623.8],"p":116,"i":8,"sec":"der-zirkel"}],"size":[595.276,841.89]},"117":{"tab":"","blocks":[{"t":"h","x":"SCHADENSBEGREN- ZUNG DES ZIRKELS","sz":23,"box":[90.7,553.8,280.2,604.8],"p":117,"i":0,"sec":"der-zirkel"},{"t":"p","x":"Der innere Zirkel des Magnum Opus verfügt über erstklassige Informationen. Die Mitglieder des Rates tragen die Tinktur der Heiligen Drei Könige, die ihnen <b>astrologische Hellsicht</b> verleiht. Ihre weltlichen Verbindungen reichen von der Regierung über die kriminelle Unterwelt bis zu esoterischen Kreisen.","sz":9.5,"box":[53.9,613.2,280.9,685.2],"p":117,"i":1,"sec":"der-zirkel"},{"t":"p","x":"Cineastisch gesehen solltest du während des gesamten Falles regelmäßig <b>Ihnen etwas verweigern, das sie wollen</b> und <b>Die Dinge richtig kompliziert machen</b> einsetzen, um dem Team das Gefühl zu geben, der Kult sei immer einen Schritt voraus und durchkreuze Pläne auf Schritt und Tritt, indem du z. B:","sz":9.5,"box":[53.9,693.9,284.7,765.9],"p":117,"i":2,"sec":"der-zirkel"},{"t":"p","x":"• eine Spur, die das Team hat, obsolet machst (z. B. weiß der Kult bereits, dass die SC kommen, und ist an einen anderen Ort gezogen) • dem Team eine Drohung schicken lässt • eine vom Team gefangene Kultist:in Selbstmord begehen oder einem Mord zum Opfer fallen lässt • den Kult dem Team auflauern lässt • den Kult die Angehörige oder Lieblingsorte des Teams angreifen lässt.","sz":9.5,"box":[309,550.3,536.4,659.8],"p":117,"i":3,"sec":"der-zirkel"},{"t":"p","x":"Du kannst harte Aktionen rechtfertigen, indem du <b>eine faire Warnung</b> in Form des Gefühls gibst, dass jemand es beobachtet oder folgt. Achte darauf, die Rückschläge nicht zu übertreiben, sondern mit Erfolgen auszubalancieren, damit die Spieler:innen gewogen bleiben.","sz":9.5,"box":[309,665.7,532.7,737.7],"p":117,"i":4,"sec":"der-zirkel"}],"size":[595.276,841.89]},"118":{"tab":"","blocks":[{"t":"sh","x":"<b>NACHFORSCHUNGEN ÜBER DAS LECK</b>","sz":10,"box":[54.3,62.8,258.2,72.8],"p":118,"i":0,"sec":"der-zirkel"},{"t":"p","x":"Wann immer du den Kult die Pläne des Teams durchkreuzen lässt, lasse Hinweise fallen, damit sich die Spieler:innen fragen, wie das möglich war, oder frag, was die Charaktere darüber denken. Wenn sie <b>Nachforschungen</b> anstellen, kommt Folgendes heraus:","sz":9.5,"box":[53.9,78.3,277.4,138],"p":118,"i":1,"sec":"der-zirkel"},{"t":"card","x":"<b>Der Kult spioniert das Team weder technisch aus, noch beschattet er es.</b> Es scheint keinen Informanten aus dem Kreis des Teams zu geben, der Informationen weitergibt.","sz":null,"k":"yellow","box":[54.1,150.6,286.6,209.4],"p":118,"i":2,"sec":"der-zirkel"},{"t":"card","x":"<b>Es gibt Beamt:innen und Sekretär:innen, die Informationen über das Team sammeln,</b> Hintergrund prüfen, auf persönliche Daten zugreifen usw. Sobald das Team Schicht 2 erreicht, lassen sie sich bis zu <u>Alona Wainwright</u> in Schicht 3 zurückverfolgen.","sz":null,"k":"yellow","box":[54.1,218.6,286.6,302.4],"p":118,"i":3,"sec":"der-zirkel"},{"t":"card","x":"<b>Ein Blick hinter den Nebel</b>, Fähigkeiten zur Erkennung von Wahrsagerei oder die Konsultation Ariadnes oder anderer Expert:innen (z. B. Hellseher:innen) kann ergeben, <b>dass jemand die Schicksalsfäden der Teammitglieder mit Hilfe von Astrologie verfolgt.</b>","sz":null,"k":"yellow","box":[54.1,311.6,286.6,395.4],"p":118,"i":4,"sec":"der-zirkel"},{"t":"card","x":"Ariadne oder andere Expert:innen können erklären, dass Risse eine stärkere Schicksalssignatur haben als Schläfer:innen. <b>Mythos-Kräfte vorübergehend nicht zu nutzen könnte als astrologische Tarnung dienen</b> und es dem Team ermöglichen, den Kult aufzuspüren.","sz":null,"k":"yellow","box":[54.1,404.6,286.6,488.4],"p":118,"i":5,"sec":"der-zirkel"},{"t":"card","x":"<b>Ein Blick hinter den Nebel kann den Mythos der Heiligen Drei Könige zeigen: drei weise Männer, die einem hellen Stern folgen.</b> Da die Ernte Jahre zurückliegt, kann man die ursprünglichen Risse nur über jemanden finden, der sie kannte (vermutlich Ariadne). Heute ist dieses Trio von ehemals reichen und weisen Verkäufern (König der Gebrauchtwagen, König der Matratzen und König der Hotdogs) zu leeren Hüllen verkommen.","sz":null,"k":"yellow","box":[54.1,497.7,286.6,631.3],"p":118,"i":6,"sec":"der-zirkel"},{"t":"sh","x":"<b>STÖRUNG DER ASTROLOGISCHEN TABELLEN DES ZIRKELS</b>","sz":10,"box":[309.4,62.8,492.9,84.8],"p":118,"i":7,"sec":"der-zirkel"},{"t":"p","x":"Das Team kann versuchen, die astrologische Weissagung zu stören, die dem Feind jeden ihrer Schritte verrät. Dies kann geschehen, indem:","sz":9.5,"box":[309,90.3,528.8,124.8],"p":118,"i":8,"sec":"der-zirkel"},{"t":"p","x":"• es auf den Einsatz von Mythos-Kräften verzichtet, um die Schicksalssignatur der SC zu verringern • mit <b>Heimlichkeit</b> das eigene Schicksal verborgen oder die Wahrsagekräfte blockiert werden • es mit einer <i>Mega!</i>-<b>Das Blatt wenden</b>-Aktion eine Tarnung durch den Nebel erschafft • das Team sich Torwächter-Ausrüstung beschafft, die Wahrsagekräfte blockt • es Silvio Yadaos Tarnkappentinktur (Mantel der Verborgenheit) nutzt, die vor Wahrsagekräften schützt • es sich eine Phiole der Tinktur der Heiligen Drei Könige beschafft und damit in einem Ritual die anderen stört (erfordert Kenntnisse des Okkulten)","sz":9.5,"box":[309,130.7,537.9,290.2],"p":118,"i":9,"sec":"der-zirkel"},{"t":"card","x":"ANGRIFF DER KULTIST:INNEN","sz":null,"k":"yellow","box":[297.5,294.6,511.8,319.4],"p":118,"i":10,"sec":"der-zirkel"},{"t":"p","x":"Wann immer sich das Team in die Angelegenheiten des Kultes einmischen will oder als Vergeltung für Ärger, den es gemacht hat, werden Agenten geschickt, um es einzuschüchtern oder kurzen Prozess zu machen.","sz":9.5,"box":[309,322.9,541.4,369.9],"p":118,"i":11,"sec":"der-zirkel"},{"t":"p","x":"Wählen den oder die Agenten, die du einsetzen willst, nach der Schicht des Falles, den Enthüllungen durch das Team, dem Schwierigkeitsgrad und eventuellen cineastischen Überlegungen aus. • Anwärter:innen (Prof. Clays Student:innen) ★★ • Ein Kreis von Initiant:innen ★★★ • Eine von Alona Wainwright angeheuerte Anwält:in, die das Team schikaniert ★★★ • Talia Al-Bahar, eine Attentäterin mit der Tinktur Wilhelm Tells ★★★★ • Die Yakuza-Yōkai, eine brutale Bande von Schlägern, die mit Tinkturen von Yōkai (japanischen Geistern und Dämon:innen) tätowiert sind ★★★★ • Ein Kreis von Jünger:innen, die Elemente kontrollieren, die auf die Kräfte des Teams abgestimmt sind ★★★★","sz":9.5,"box":[309,378.6,539.4,576.1],"p":118,"i":12,"sec":"der-zirkel"},{"t":"p","x":"• Eine Nemesis mit einer Tinktur, die auf die Kräfte eines bestimmten SC zugeschnitten ist","sz":9.5,"box":[309,581.4,526.1,603.4],"p":118,"i":13,"sec":"der-zirkel"},{"t":"p","x":"Der Kult kann das Team überall finden (wenn es keine Maßnahmen ergriffen hat, um dies zu verhindern) und wird an Orten wie diesen angreifen:","sz":9.5,"box":[309,609.3,539,643.8],"p":118,"i":14,"sec":"der-zirkel"},{"t":"p","x":"• Wo auch immer das Team ermittelt • In einem Abwasserkanal oder U-Bahn-Tunnel, in den Kultist:innen das Team gelockt haben • Bei einem Kultritual, das das Team infiltrieren und/ oder stürmen will (z. B. die <u>Silo-Prüfung,</u> das <u>Narrenfest</u> oder dem Salbungsritual in den <u>Katakomben)</u> • An Orten, die mit dem Privatleben der SC zu tun haben","sz":9.5,"box":[309,649.6,541.1,746.6],"p":118,"i":15,"sec":"der-zirkel"}],"size":[595.276,841.89]},"119":{"tab":"","blocks":[{"t":"sh","x":"<b>BEFRAGUNG DER AGENT:INNEN DES KULTS</b>","sz":10,"box":[54.3,62.8,251.8,84.8],"p":119,"i":0,"sec":"der-zirkel"},{"t":"p","x":"Jede besiegte Agent:in kann etwas anderes über den Fall aussagen:","sz":9.5,"box":[53.9,90.3,272.7,112.3],"p":119,"i":1,"sec":"der-zirkel"},{"t":"card","x":"<b>Kultist:innen</b> strotzen nur so vor alchemistischer Symbolik (Gesänge, Rezepte, Siegel) und Kräfte (Transmutationen, Tinkturen), über die das Team Nachforschungen anstellen kann <u>(1x1 der Alchemie).</u>","sz":null,"k":"yellow","box":[54.1,124.7,286.6,195.8],"p":119,"i":2,"sec":"der-zirkel"},{"t":"card","x":"Die <b>Suchenden</b> sind meist Mitglieder von <u>Prof. Clays</u> Philosophie-Club. Man kann so zu einem Treffen oder ins Büro des Professors folgen.","sz":null,"k":"yellow","box":[54.1,205.1,286.6,251.4],"p":119,"i":3,"sec":"der-zirkel"},{"t":"card","x":"<b>Initiant:innen und Jünger:innen</b> sind schwieriger zu knacken oder aufzuspüren (s. S. Textkasten) und dienen als Bodentruppen und Kurier:innen. Man kann ihnen zu fast jedem Ort mit Kultaktivität folgen (er darf nur eine Schicht unter der aktuellen liegen). Ab Schicht 3 können sie das Team in die <u>Katakomben</u> führen, vor allem, wenn es nicht während des <u>Narrenfestes</u> dorthin gekommen ist.","sz":null,"k":"yellow","box":[54.1,260.6,286.6,381.9],"p":119,"i":4,"sec":"der-zirkel"},{"t":"card","x":"Zirkelmitglied <u>Alona Wainwright</u> <b>befehligt die Anwält:in Talia und die Yakuza-Yokai</b>. Sie führen zu ihrem Unternehmen, dem Auktionshaus Wainwright.","sz":null,"k":"yellow","box":[54.1,391.1,286.6,449.9],"p":119,"i":5,"sec":"der-zirkel"},{"t":"h","x":"HOCHNOTPEINLICHES VERHÖR","sz":14,"box":[320.3,61,462.9,75],"p":119,"i":6,"sec":"der-zirkel"},{"t":"p","x":"Gefangene Kultist:innen im Rang von Initiant:innen oder höher verfügen potenziell über Wissen um den Kult bis hin zum Geschehen in den <u>Katakomben.</u> Der Fanatismus (s. S. Die Bedrohung durch das Magnum Opus) kann ihr Verhör zu einem langwierigen und quälenden Prozess für beide Seiten machen, wie es cineastisch auch sein sollte. Das Verhör kann sich parallel zu den Hauptnachforschungen über mehrere Szenen und Drehpausen erstrecken.","sz":9,"box":[320.3,87.5,529.8,192.5],"p":119,"i":7,"sec":"der-zirkel"},{"t":"p","x":"• Das Verhör eines Kultmitglieds ist eine großartige Gelegenheit, um Spannung aufzubauen und in den gehirngewaschenen Geist eines machthungrigen oder spirituell getriebenen Fanatikers einzutauchen. Lass einige kryptische alchemistische Zeilen aus dem <b>Lied der Initiant:innen</b> (s. S. 150) einfließen.","sz":9,"box":[320.3,198.3,525.7,279.3],"p":119,"i":8,"sec":"der-zirkel"},{"t":"p","x":"• Selbst beim Ausgeben von Hinweisen sprechen die Kultist:innen in Rätseln. Sie machen Andeutungen, die auf Orte auf der gleichen oder einer um 1 tieferen Schicht hinweisen, aber nie weitergehende.","sz":9,"box":[320.3,290.8,529.1,335.8],"p":119,"i":9,"sec":"der-zirkel"},{"t":"p","x":"Wenn du Gelegenheit zu einer harten Aktion hast, könnte eine Gefangene versuchen, das Team zu rekrutieren, besonders, wenn sie viel Zeit miteinander verbringen. Sie könnten abdrehen und den Zustand <t>fanatisch</t> erlangen. Oder der Zirkel kann alles astrologisch vorhersagen und <b>Talia Al-Bahar</b> (s. S. 124) schicken, um die Kultist:in zu ermorden.","sz":9,"box":[320.3,350.2,524.6,431.2],"p":119,"i":10,"sec":"der-zirkel"},{"t":"p","x":"<b>Jünger:innen</b> sind mit den Operationen des Kults betraut, wie z. B. der Ernte von Rissen und dem Sammeln von Ichor aus dem Ofen. Wenn es dem Team gelingt, die Astrologie des Zirkels und die Loyalität der Jünger:innen zu überwinden, können sie zur alten <u>Aurora-Glashütte</u> (s. S. 105, <i>Athanor</i>) oder nach <u>Canseliet Manor</u> (s. S. 155, <i>Der Alchemist</i>) weisen.","sz":10,"box":[62.4,464.7,277.7,562.3],"p":119,"i":11,"sec":"der-zirkel"}],"size":[595.276,841.89]},"120":{"tab":"","blocks":[{"t":"h","x":"DIE BEDROHUNG DURCH MAGNUM OPUS","sz":23,"box":[53.9,63.4,281.6,114.4],"p":120,"i":0,"sec":"der-zirkel"},{"t":"p","x":"Magnum-Opus-Kultist:innen operieren in kleinen Gruppen. Wenn nicht anders angegeben, hat eine Gruppe eine Handvoll Mitglieder und einen Größenfaktor von 1. Das hilft ihnen, nicht nur höhere physische, sondern auch emotionale und soziale Zustände zu erlangen, da sie sich gegenseitig in ihrem Glauben unterstützen.","sz":9.5,"box":[53.9,125.7,277.8,210.2],"p":120,"i":1,"sec":"der-zirkel"},{"t":"p","x":"Der fanatische Glaube an das Magnum Opus macht sie praktisch immun gegen geistige Beeinflussung. Je weiter sie in den Rängen aufsteigen, desto höher werden sowohl die Maximalwerte für die <i>Abkehr vom Kult</i> als auch der Wert des Zustands <t>fanatisch</t>, den sie durch die Spezialaktion <b>Kadavergehorsam</b> erhalten. Die Aufhebung des Zustands <t>fanatisch</t> erschafft eine verletzliche Position, in der die Abwehrkräfte nachlassen und eine Bindung in Frage gestellt werden kann. Nur das Erreichen des Höchstwertes von <i>Abkehr vom Kult</i> führt dazu, dass jemand den Kult verrät oder verlässt.","sz":9.5,"box":[53.9,218.9,286,353.4],"p":120,"i":2,"sec":"der-zirkel"},{"t":"p","x":"Die folgenden Bedrohungsprofile beschreiben Suchende, Anhänger:innen, Initiant:innen und Jünger:innen. Für Fortgeschrittene wie Prof. Clay, Whirler oder Alona Wainwright findest du später individuelle Profile.","sz":9.5,"box":[53.9,362,285.9,409],"p":120,"i":3,"sec":"der-zirkel"},{"t":"threat","stars":"★","name":"SUCHENDE","spectra":"VERLETZEN ODER UNSCHÄDLICH MACHEN 1 / AB- KEHR VOM KULT 3","items":["<b>Ich bin mir nicht sicher:</b> Wenn Suchende des Magnum Opus die Szene betreten, gib ihnen <t>zögernd 1</t>.","<b>Gesicht in der Menge:</b> Wenn jemand versucht, Suchende zu finden, sind sie zunächst <i>Unauffällig</i>.","Sich dem Gottkönig unterwerfen (<t>zögernd 1</t> oder 1 Stufe eines emotionalen Zustands entfernen)","Jemanden schlagen (<t>Autsch 1</t>) oder ein Werkzeug als Waffe benutzen (<t>Prellung 2</t> oder <t>Stichwunde 2</t>)","ein selbst hergestelltes Gebräu verwenden, z. B.: » Säure: einen Rüstungs-Marker verbrennen » Schmiermittel: eine Fläche <i>Rutschig</i> machen » Brandbeschleuniger: jeder in der Nähe erhält <t>verbrannt 1</t> » Blendgranate: Jeder in der Nähe erhält temporär <t>geblendet 2</t> » Rauchbombe: Ein oder zwei Suchende entkommen (Ihnen etwas verweigern, das sie wollen)","linkisch ihre Absichten verkünden","zögern, bevor sie zuschlagen","Entschlossenheit in gebrochenem Latein zeigen: „O, Pater animans!“ („Oh, lebengebender Vater!“)"],"box":[317.4,66.5,384.2,82.6],"desc":"Suchende sind Kandidat:innen, die Prof. Clay oder andere Anwerber:innen als potenzielle Mitglieder in Betracht ziehen. Es handelt sich um ein Sammelsurium von Individuen unterschiedlichen Alters, Hintergrunds und Lebensstils, die die Sehnsucht nach mehr Inhalt im Leben verbindet. Zu Beginn ihrer Reise sind sie lediglich Möchtegern-Kultist:innen. Sie haben keine magischen Kräfte. Stattdessen verlassen sie sich auf selbstgebraute Mittelchen, die auf Alchemie basieren.","p":120,"i":4,"sec":"der-zirkel"},{"t":"threat","stars":"★★","name":"ANHÄNGER:INNEN","spectra":"VERLETZEN ODER UNSCHÄDLICH MACHEN 1 / AB- KEHR VOM KULT 4","items":["<b>Kadavergehorsam:</b> Wenn sie die Szene betreten, gib ihnen <t>fanatisch 2</t>, erneuerbar als harte Aktion.","<b>Gewalt ist nicht die Antwort</b>: Wenn Anhänger:innen einen Menschen angreifen, erhalten sie zunächst <t>friedlich 2</t>.","Jemanden auffordern, die Waffen niederzulegen (<t>friedlich 2</t> oder eine Stärke verbrennen)","Jemanden dazu inspirieren, Hemmungen zu verlieren (<t>enthemmt 2</t> oder eine Stärke verbrennen)","Begeistert über ihren Guru sprechen (<t>zuhören 2</t> oder eine Stärke verbrennen)","eine tiefgründige Perspektive schildern, die Aspekte des Lebens leer und sinnlos erscheinen lässt (<t>Selbstzweifel 2</t>, eine Stärke verbrennen oder der Spieler:in erzählerisch Bruch markieren lassen)","Sich mit geschlossenen Augen und gefalteten Händen vor jemandem verbeugen","Lob auf Guru Whirler","Zur Beruhigung beten: „Spiritus meus mercurio lavatur“ („Mein Geist wird mit Quecksilber gewaschen.“)"],"box":[155,550.7,175.4,562.7],"desc":"Anhänger:innen sind Kultist:innen, die die <u>Silo-Prüfung</u> bestanden haben und auf dem Weg zur Initiation sind. In <u>Whirlers Kommune</u> werden sie angeleitet, sich von allen sterblichen Anhaftungen zu lösen und Mitgefühl, Zärtlichkeit und Liebe zu praktizieren. Von den Kräften Whirlers berührt haben sie eine ruhige Ausstrahlung und meiden Gewalt. Sie behalten ihr Aussehen, tragen aber weiße oder cremefarbene Gewänder, wenn sie für Magnum Opus tätig sind.","p":120,"i":5,"sec":"der-zirkel"}],"size":[595.276,841.89]},"121":{"tab":"","blocks":[{"t":"threat","stars":"★★","name":"INITIANT:INNEN","spectra":"VERLETZEN ODER UNSCHÄDLICH MACHEN 2 / AB- KEHR VOM KULT 5","items":["<b>Kadavergehorsam:</b> Wenn sie die Szene betreten, gib ihnen <t>fanatisch 3</t>, erneuerbar als harte Aktion.","Jemanden mit Gelaber einschüchtern oder anwerben (<t>ängstlich 2</t> oder <t>ganz Ohr 2</t>)","Fläschchen mit alchemistischen Verbindungen werfen, die speziell gegen die Kräfte des SC oder für eine bestimmte Aufgabe wirken, z. B.: » Salz gegen Flüssigkeit (<t>trocken 2</t> oder <t>kristallin 2</t>) » Klebrig gegen starke Nahkämpfer (<t>festgewurzelt 2</t> oder <t>festgeklebt 2</t>) » Quecksilber gegen Elektrizität (die Umgebung wird <i>Leitend</i>) » Sprengstoff gegen schnelle SC (jeder in der Nähe ist <t>zurückgeworfen 2</t> und hat <t>Prellungen 2</t>) » Gift gegen Pflanzen oder Tiere (<t>verdorrt 2</t> oder <t>vergiftet 2</t>) » Schwefel gegen scharfe Sinne oder Mentalisten (<t>überladene Sinne 2</t>) » Stinkbombe: alle Magnum-Opus-Mitglieder entkommen (<b>Ihnen etwas verweigern, das sie wollen</b>) und alle anderen bekommen <t>Hustenanfälle 2</t>","Feinden des Kults mit brennenden Augen entgegensehen","Einen Schlachtruf auf Latein ausstoßen: „Ut Sol elucidatur!“ („Strahlend wie die Sonne!“)"],"box":[62.4,57.5,163.5,73.6],"desc":"Die Initiant:innen sind klassische Kultmitglieder: Sie befolgen Befehle, wissen aber nichts von der schockierenden Wahrheit, die den Kern des Kultes ausmacht. Sie sind zu tief in den Kult verstrickt und ihrem Ziel zu nahe, um sich dagegen zu wenden. Auf einer Mission tragen sie Alltagskleidung, sind aber an der hellgelb-braunen Tunika darunter kenntlich.<br><br>Dank der astrologischen Kräfte des Zirkels sind die Initiant:innen gut auf die Aufgaben vorbereitet. Sie tragen alchemistische Mixturen bei sich, die auf bestimmte Bedrohungen zugeschnitten sind, wie z. B. die SC und ihre einzigartigen Kräfte und Schwächen.","p":121,"i":0,"sec":"der-zirkel"},{"t":"threat","stars":"★★★","name":"JÜNGER:INNEN","spectra":"VERLETZEN ODER UNSCHÄDLICH MACHEN 3 / AB- KEHR VOM KULT 6","items":["<b>Kadavergehorsam:</b> Wenn sie die Szene betreten, gib ihnen <t>fanatisch 4</t>, erneuerbar als harte Aktion.","<b>Ausgebildete Anwender:in:</b> Einmal pro Szene können Jünger:innen als Einmischung eine Transmutation als harte Aktion ausführen.","ihr Element zum Vorteil transmutieren: » <b>Erde:</b> eine schützende Barriere errichten (<i>Zerschlagen 4</i>) oder einen Weg versperrt (<b>Ihnen etwas verweigern, das sie wollen</b>)","» <b>Feuer:</b> jemanden mit Feuer angreifen (<t>verbrannt 3</t> oder <t>geblendet 3</t>) » <b>Wasser:</b> Dehydrieren (<t>dehydriert 3</t>) oder mit einem Wasserschwall angreifen (Betroffene sind temporär <t>niedergeschlagen 3</t>) » <b>Luft:</b> Kultist:innen <t>im Nebel versteckt 2</t> verleihen oder jemandem den Atem nehmen (<t>erstickend 3</t>) » <b>Blei (oder Silber):</b> Kultist:innen vor Bleigeschossen schützen (kontert die nächsten 3 Stufen Schüsse) oder Blei verschießen (<t>Schusswunde 3</t>) » <b>Eisen:</b> Gegenstände aus Stahl bewegen (<t>zermalmt 3</t>) oder zu einem Käfig verbiegen (<t>im Käfig 3</t>) » <b>Salz:</b> Eine Oberfläche mit Salz verätzen (<t>zerfressen 3</t> oder <t>Löcher 3</t>) oder Flüssigkeiten kristallisieren lassen (<t>kristallisiert 3</t>) » <b>Arsen:</b> Jemandem eine Arsenvergiftung zufügen (<t>vergiftet 3</t> und in jeder Drehpause erneut <t>vergiftet 3</t>) und zwingen, sich zu ergeben, damit die Jünger:in das Arsen wieder aus dem Körper entfernt » <b>Phosphor:</b> eine Rauchwand erzeugen (<t>Deckung 3</t> oder <b>Ihnen etwas verweigern, das sie wollen</b>) oder <t>chemische Verbrennungen 3</t> verursachen","Inbrünstig beteuern, dass Magnum Opus Wünsche zu erfüllen vermag (<t>in Versuchung 3</t>)","Völlige Ruhe im Angesicht von Gefahr","Transmutation bewirken und die Sigille zum Leuchten bringen, indem sie „Deus in Orbe Terrarum“ („Gott auf Erden“) flüstern","Auf einen Befehl mit „Cum pyra tua sacra“ („Mit deinem heiligen Feuer“) antworten"],"box":[140.3,382.7,170.9,394.7],"desc":"Nur Wölf:innen steigen in den Rang von Jünger:innen auf – die Lämmer erweckt der Kult stattdessen als Risse. Jünger:innen sind vollwertige Mitglieder. Bei ihrer Aufnahme bringt man ihnen erste Transmutation bei und brandmarkt sie mit einem alchemistischen Symbol. Sie repräsentieren ein Element und sind von Armands Mythos berührt. Dadurch erlangen sie magische Kontrolle über dieses Element. Jünger:innen tragen oft einen Vorrat davon bei sich, wenn es nicht allgegenwärtig ist. Sie nutzen burgunderrote Roben oder rote Tuniken unter der Kleidung.<br><br>Wie die Initiant:innen nutzt der Zirkel Jünger:innen, die nach den astrologischen Vorhersagen die für die Aufgabe benötigte Elemente besitzen. Jünger:innen, auf die die SC treffen, verfügen daher oft über Transmutationen, die zu ihren Kräften passen, es sei denn, die SC haben die Weissagung umgangen.","p":121,"i":1,"sec":"der-zirkel"}],"size":[595.276,841.89]},"122":{"tab":"","blocks":[{"t":"threat","stars":"★★★","name":"YAKUZA-YOKAI","spectra":"","items":[],"box":[138.3,56.7,168.9,68.7],"p":122,"i":0,"sec":"der-zirkel"},{"t":"p","x":"Diese Einheit ehemaliger Yakuza-Mafiosi ließ Tätowierungen mit Tinte versehen, in die Tinkturen der Yōkai-Mythen (japanische böse Geister, Gespenster und Dämon:innen) gemischt waren. Wenn sie ihre Kräfte aktivieren, umwirbelt Rauch die scheinbar lebendigen Tätowierungen, die den Körper des Gangsters ändern oder Gegenstände und Substanzen materialisieren. Als Gegenleistung für diese dämonischen Kräfte hat die Yakuza-Crew geschworen, dem Zirkel sieben Jahre zu dienen. Die Yōkai der fünf Teammitglieder sind:","sz":9,"box":[62.4,79.9,273.9,208.9],"p":122,"i":1,"sec":"der-zirkel"},{"t":"p","x":"• <b>Akaname (Dreckschlecker),</b> ein Badezimmerkobold, der Schleim und Dreck leckt und produziert • <b>Aobōzu (Blauer Mönch),</b> ein einäugiger buddhistischer Mönch mit unheimlicher Wahrnehmung und Kraft • <b>Chōchin-obake (Papierlaternengeist),</b> eine schwebende dämonische Papierlaterne, die feurige Verwüstung anrichtet • <b>Enenra (Rauchschleier),</b> ein Dämon von Finsternis und Rauch, der nur für reine Herzen sichtbar ist • <b>Jubokko (Baumkind),</b> ein Vampirbaum, dem wurzelartige Tentakel wachsen, die Blut saugen","sz":9,"box":[62.4,217.9,275.4,358.9],"p":122,"i":2,"sec":"der-zirkel"},{"t":"p","x":"Dieses Bedrohungsprofil steht für einen einzelnen Yakuza Yōkai.","sz":9,"box":[62.4,370.4,262.7,391.4],"p":122,"i":3,"sec":"der-zirkel"},{"t":"p","x":"einen Strahl ekelhaften Schleim (<t>ausrutschen 2</t>). » <b>Aobōzu:</b> Wenn Aobōzu den Schauplatz betritt, gib ihm <t>Unsichtbares sehen 2</t>, erneuerbar als harte Aktion. Bei Aobōzu reduziert <b>Hart wie Kruppstahl</b> Schaden um 2 Stufen statt 1. » <b>Chōchin-obake:</b> Wenn Chōchin-obake die Szene betritt, gib ihm <t>ausweichendes Schweben 2</t>, erneuerbar als harte Aktion. » <b>Enenra:</b> Enenra kann sich als weiche Aktion in Rauch auflösen und wieder materialisieren. In der Rauchform ist das Maximum vom <i>Verletzen-oder-unschädlich-machen</i>-Spektrum (-), und er wird <t>unsichtbar 5</t> (außer für jemand reinen Herzens). Das wirkt sich auf Sich der Gefahr stellen bei Angriffen aus. » <b>Jubokko:</b> Wenn Jubokko den Zustand <t>ausgelaugt</t> erleidet, erhält er stattdessen <t>belebt</t> derselben Stufe. Er kann Stufen von <t>belebt</t> 1:1 verwenden, um Stufen eines negativen Zustands zu entfernen. • <b>Hart wie Kruppstahl:</b> Wenn der Yakuza Yōkai einen Zustand körperlichen Schadens, Unschädlichmachung oder geistigen Schadens erleidet, sinkt die Stufe um 1.","sz":9,"box":[317.5,62.1,543.6,323.1],"p":122,"i":4,"sec":"der-zirkel"},{"t":"p","x":"• waffenloser Kampfsportangriff (<t>Armbruch 3</t>, <t>festgenagelt 3</t> oder <t>außer Gefecht 3</t>) oder Angriff mit großkalibrigen (Maschinen-)Pistolen (<t>Schusswunde 3</t>) • <b>Akaname:</b> Einen Bereich mit Schleim besprühen (<t>glitschig 2</t>) • <b>Chōchin-obake:</b> Eine neue <i>Laterne</i> anfertigen • <b>Chōchin-obake:</b> Jede Laterne versprüht einen Strahl Höllenfeuer (<t>Höllenfeuerverbrennung 3</t>) • <b>Jubokko:</b> Tentakel an jemandem befestigen und Blut saugen (<t>ausgelaugt 3</t>)","sz":9,"box":[317.5,332.1,540,449.1],"p":122,"i":5,"sec":"der-zirkel"},{"t":"sh","x":"<b>VERLETZEN ODER UNSCHÄDLICH MACHEN 4 / AB- KEHR VOM KULT 6</b>","sz":12,"box":[62.4,401.9,264.5,425.9],"p":122,"i":6,"sec":"der-zirkel"},{"t":"p","x":"• <b>Tinkturen der Yōkai:</b> Jeder der Yakuza-Yōkai besitzt eine andere Fähigkeit: » <b>Akaname:</b> Wenn man ihn angreift, versprüht er","sz":9,"box":[62.4,430.4,271.1,463.5],"p":122,"i":7,"sec":"der-zirkel"},{"t":"p","x":"• Sich mit dem Team messen, eine Pose einnehmen und Gegner abschätzen • Angriff!","sz":9,"box":[317.5,458.1,542.1,491.1],"p":122,"i":8,"sec":"der-zirkel"}],"size":[595.276,841.89]},"123":{"tab":"","blocks":[],"size":[595.276,841.89]},"124":{"tab":"","blocks":[{"t":"threat","stars":"★★★★","name":"TALIA AL-BAHAR","spectra":"VERLETZEN ODER UNSCHÄDLICH MACHEN 3 / BE- STECHEN 6 / TINKTUR-KONFLIKT 5","items":["<b>Scharfschützin:</b> Wenn Talia den Schauplatz betritt und sich in einer Scharfschützenposition befindet, gib ihr <t>verborgen 2</t>.","<b>Initiative ergreifen:</b> Wer Talia angreift, den trifft sie mit einer harten Aktion zuerst.","<b>Heldinnenmut:</b> Erleidet Talia einen mentalen oder emotionalen Zustand, verringere die Stufe um 2.","<b>Mythos-Rückkopplung:</b> Wenn Talia einen Unterdrücker beschützt oder ihm hilft, arbeitet der freiheitskämpferische Mythos Wilhelm Tells dagegen. Gib ihr <t>Tinktur-Konflikt</t> mit einer entsprechenden Stufe. Wenn <i>Tinktur-Konflikt</i> den Maximalwert erreicht, muss sie alle derartigen Handlungen einstellen oder die Tinktur fallen lassen (SL-Entscheid).","Zielen (gib jemandem <t>im Blickfeld 2</t>, angewandt auf <b>Der Gefahr stellen</b> gegen ihre Schüsse)","Einen einzigen, tödlichen, präzisen Schuss abgeben (<t>schwere Schusswunde 4</t>)","Sperrfeuer oder Feuerschutz (<b>Sie vor eine Wahl stellen</b>: in Deckung bleiben oder <t>Schusswunde 3</t>)","jemandem einen Gegenstand aus der Hand schießen, mit einer Kugel einen Schalter umlegen usw. (<b>Die Dinge richtig kompliziert machen</b> oder <b>Ihnen etwas verweigern, das sie wollen</b>)","Ein Geschoss von einer harten Oberfläche abprallen lassen oder um die Ecke schießen (<t>Schusswunde 3</t>)","im Nahkampf ein Kampfmesser zücken (<t>fiese Stichwunde 4</t>)","Eine Lichtreflexion hoch oben","Gekonnt das Magazin wechseln, während sie ihr nächstes Ziel anvisiert"],"box":[143.8,58.2,184.6,70.2],"desc":"Talia Al-Bahar ist eine frühere Söldnerin, die das Angebot das Zirkels angenommen hat, ihre Fähigkeiten mit einer „streng geheimen Technologie“ zu verbessern. Sie trägt einen Anhänger aus Titan um den Hals (der an eine Hundemarke erinnert), der die Tinktur Wilhelm Tells enthält, die Treffsicherheit, Kampfkraft und Tapferkeit erhöht (und sie auf die Existenz des Legendären aufmerksam macht). Bei der Arbeit trägt sie typische Söldnerkleidung: Kampfstiefel, Tarnhose, Tanktop, Armeejacke und Sonnenbrille. Sie hat wenig Moralvorstellungen, aber vom Mythos Wilhelm Tell kann man das nicht behaupten. Die Tinktur wehrt sich gegen die tyrannische Agenda, und Talia kann sie nur kurz nutzen, ehe sie sie „abkühlen“ lassen muss.<br><br>Talias Aktionen sind durch die Tinktur verbessert. Wenn sie die Tinktur verliert, reduziere die Effekte der harten Aktionen um 1, beschränke <b>Initiative ergreifen</b> auf Nahkampf und entferne <b>Heldinnenmut</b>.","p":124,"i":0,"sec":"der-zirkel"},{"t":"h","x":"SCHICHT 0:","sz":14,"box":[309,69.1,377.4,83.1],"p":124,"i":1,"skip":true,"sec":"schicht-0-aufhaenger"},{"t":"h","x":"AUFHÄNGER","sz":23,"box":[309,91.4,425.3,114.4],"p":124,"i":2,"skip":true},{"t":"p","x":"<i>Der Kult des Gottkönigs</i> spielt sich am besten als psychologischer Thriller, wenn mindestens ein SC, der nach Antworten sucht, den Prozess des Magnum Opus durchläuft. Obwohl das ultimative Ziel des Kults ein übles ist, kann die Reise, die der SC unter der Führung Prof. Clays, Whirlers und anderer unternimmt, dennoch sinnvoll (und im Grals-Metaplots eine Vorbereitung ) sein. Für den betreffenden SC könnten es die ersten Schritte zur ultimativen Wahrheit sein.","sz":9.5,"box":[309,122.9,537.8,232.4],"p":124,"i":3,"sec":"schicht-0-aufhaenger"},{"t":"p","x":"Natürlich können SC, die den Lehrern misstrauen oder kein Interesse an dem haben, was er zu bieten hat, ihn von außen untersuchen, indem sie Nachforschungen anstellen oder die Aktivitäten aufdecken und sabotieren. Dies führt zu einer direkten und unbarmherzigen Konfrontation mit dem Kult.","sz":9.5,"box":[309,241,538.6,313],"p":124,"i":4,"sec":"schicht-0-aufhaenger"},{"t":"p","x":"Folgendermaßen kannst du das Team in den Fall einbeziehen:","sz":9.5,"box":[309,321.7,533.1,343.7],"p":124,"i":5,"sec":"schicht-0-aufhaenger"},{"t":"p","x":"• <b>Auf der Suche nach Antworten oder Macht:</b> SC, die nach Antworten über die Stadt, den Nebel und das, was dahinter liegt, suchen, sind perfekte Kandidaten für den Beitritt zum Kult. SC, die sich für das Okkulte als Beruf, Mittel zur Lösung der Mysterien oder als Weg zu Macht interessieren, können ebenfalls Rekruten werden. Sie können auf die Visitenkarte <u>Prof. Clays</u> stoßen, die in einem verstaubten Buch der Bibliothek zu finden ist, oder ihn am Speakers’ Corner hören. Wenn <b>Ariadne</b> sie unterstützt (s. S. Textkasten), kann sie sie auf Prof. Clay als „Mann, der den Weg zu Antworten bewacht“ hinweisen.","sz":9.5,"box":[309,355.2,540,502.2],"p":124,"i":6,"sec":"schicht-0-aufhaenger"},{"t":"p","x":"• <b>Beauftragt, den Kult zu untersuchen:</b> Angehörige oder Freund:innen von Kultanhänger:innen könnten das Team anheuern, um ihre Lieben zu retten (mögliche NSC s. Textkasten). <b>Ariadne</b> könnte das Team verdeckt einschleusen, um die Geheimnisse zu enthüllen. Eine Nebendarsteller:in könnte sich mit dem Kult einlassen. Die Untersuchung des Kults beginnt mit <u>Prof. Clay</u> und seinem Philosophie-Club.","sz":9.5,"box":[309,510.9,539.9,607.9],"p":124,"i":7,"sec":"schicht-0-aufhaenger"},{"t":"p","x":"• <b>Weiterführung von</b> <i>Athanor</i><b>:</b> Wenn das Team während <i>Athanor</i> (s. S. 87) auf die Artefakte des Kults gestoßen ist, wie z. B. die Tinktur der Lebkuchenhexe, den Ernteofen oder den Jünger:innen selbst, kann es bereits nach Informationen über die seltsame Magie suchen. Die Erforschung der geheimen Kunst der Kultist:innen kann zu Antworten führen <u>(1x1 der Alchemie).</u> Die Suche nach den Operationen wird zunächst in eine Sackgasse oder einen Hinterhalt führen <u>(Schadensbegrenzung des Zirkels).</u>","sz":9.5,"box":[309,616.5,540.3,738.5],"p":124,"i":8,"sec":"schicht-0-aufhaenger"}],"size":[595.276,841.89]},"125":{"tab":"","blocks":[{"t":"p","x":"• <b>Kontakt mit der Reliktjagd des Kults:</b> Kunst- und Antiquitätenhändler:innen, Schmuggler:innen, Hehler:innen und Fälscher:innen haben Wind von einer ernstzunehmenden Sammlerin bekommen, die Artefakte kauft und damit einen Hype und vermehrte Antiquitäten-Diebstählen auslöst (ein solcher Kontakt ist Michel Ahmagi von der Galerie Ananda, siehe <i>Dämon:innen in Cross End</i> in Spielleitung 1x1","sz":9.5,"box":[53.9,62.5,283.6,159.5],"p":125,"i":0,"sec":"schicht-0-aufhaenger"},{"t":"p","x":"Ansprechpartner ist <b>Silvio Yadao</b>, ein Einbrecher, der für die anonyme Sammlerin (Alona Wainwright) gearbeitet hat, nun aber aussteigen will und daher vom Kult bedroht wird. Silvio schlägt vor, sich auf dem <u>Chinatown Festival</u> zu treffen, einem überfüllten Straßenfest, das sich ideal für Treffen eignet und viele Fluchtmöglichkeiten bietet.","sz":9.5,"box":[62.4,167.3,284.3,251.8],"p":125,"i":1,"sec":"schicht-0-aufhaenger"},{"t":"p","x":"Es kann sein, dass Mitglieder des Teams zufällig auf dem <u>Chinatown-Festival</u> sind, als der Kult Silvio angreift, was sie zum Handeln und späteren Nachforschungen veranlasst. Auch könnten Nebenfiguren in das Chaos verwickelt sein und um Hilfe bitten.","sz":9.5,"box":[62.4,260.8,284.6,320.3],"p":125,"i":2,"sec":"schicht-0-aufhaenger"},{"t":"h","x":"KULTIST:INNEN SIND AUCH NUR MENSCHEN","sz":14,"box":[64.7,354.9,269.7,368.9],"p":125,"i":3,"sec":"schicht-0-aufhaenger"},{"t":"p","x":"Wenn weder die SC noch ihre Nebenfiguren dem Kult beitreten, kannst du die folgenden NSC als Opfer einsetzen, um das Team emotional zu involvieren.","sz":9,"box":[64.7,381.5,274.5,414.5],"p":125,"i":4,"sec":"schicht-0-aufhaenger"},{"t":"p","x":"<b>Peter Hill</b>, ein breitschultriger Sportler, ist ein streitsüchtiger junger Mann. Sein Anspruchsdenken und Ehrgeiz können seine Unsicherheit kaum verbergen. Hill ist nicht interessiert, die schwere Kindheit mit fehlenden Vorbildern zu verarbeiten. Stattdessen will er eine Macht besitzen, die jeden zum Schweigen bringt, der ihn darauf anspricht.","sz":9,"box":[64.7,423.1,273.9,504.1],"p":125,"i":5,"sec":"schicht-0-aufhaenger"},{"t":"p","x":"<b>Sloane Martinez</b> (Nymphe) ist ein feingliedriger, schüchterner Bücherwurm, mit großen Fragen zu den Geheimnissen des Universums. Die zarte Seele ist bereit, für Wahrheit und die Magie alles zu opfern. Zunächst gelingt es ihr, die Tatsache zu verbergen, dass sie ein Riss ist. Wenn der Kult das herausfindet, wird er sie besonders genau beobachten.","sz":9,"box":[64.7,512.8,273.9,593.8],"p":125,"i":6,"sec":"schicht-0-aufhaenger"},{"t":"p","x":"<b>Jiahao „Jaja“ Zhang</b> ist ein pummeliges, immer lächelndes Anhängsel der beiden anderen. Er schließt sich dem Kult an, weil seine Freunde dort sind, und tut alles, um ihnen nachzueifern, auch wenn er nicht gerade für die Lehren brennt. Jiahao will vor allem dazugehören. Sobald er den Kult als Gruppe erlebt, könnte er der eifrigste Kultist der drei werden.","sz":9,"box":[64.7,602.5,270.8,683.5],"p":125,"i":7,"sec":"schicht-0-aufhaenger"}],"size":[595.276,841.89]},"126":{"tab":"","blocks":[{"t":"h","x":"ARIADNE","sz":23,"box":[53.9,63.4,137.1,86.4],"p":126,"i":0,"sec":"schicht-0-aufhaenger"},{"t":"p","x":"In den spirituellen und okkulten Kreisen der Subkultur der Risse ist <b>Ariadne</b> (Ariadne, die Frau des Dionysos, die Theseus das Fadenknäuel gab, um ihn aus dem Labyrinth des Minotaurus zu führen) eine bekannte Gestalt und gefragte mystische Ratgeberin. Sie ist ein mächtiger aber zurückhaltender Riss, durch den Mythos dazu getrieben, die, die es wert sind, aus sprichwörtlichen Labyrinthen herauszuführen.","sz":9.5,"box":[53.9,94.9,284.4,191.9],"p":126,"i":1,"sec":"schicht-0-aufhaenger"},{"t":"p","x":"Ariadne weiß viel über die Vorgänge unter den Rissen, insbesondere in deren esoterischen und magischen Kreisen. Du kannst über sie SC, die nach mystischen Antworten suchen, Weisheit und Informationen geben. In der Regel gibt sie ihr Wissen jedoch nur sparsam weiter, so dass die SC gerade informiert genug sind, um den nächsten Schritt zu machen, wie eine Schnur, die in einem Labyrinth um eine Ecke führt. Während Szenen verhält sie sich <t>kryptisch 3</t>, was es schwer macht, Hinweise zu erhalten, die sie nicht preisgeben will.","sz":9.5,"box":[53.9,200.5,286.3,322.5],"p":126,"i":2,"sec":"schicht-0-aufhaenger"},{"t":"p","x":"Niemand weiß, wer oder was Ariadne ist. Sie könnte ein mächtiger (legendärer) Riss sein, der kurz vor der Avatarschaft steht und bereit ist, es mit den Hüter:innen des Nebels aufzunehmen, oder sie ist gar eine Torwächterin. Wahrscheinlich ist sie beides und spielt mit den Torwächter:innen und Rissen, um die Ziele ihres Mythos zu erreichen: denen, die es wollen, zu helfen, das labyrinthische Gefängnis der Stadt zu überwinden.","sz":9.5,"box":[53.9,331.2,284.6,428.2],"p":126,"i":3,"sec":"schicht-0-aufhaenger"},{"t":"h","x":"ARIADNE UND MAGNUM OPUS","sz":16,"box":[53.9,443.9,250.7,459.9],"p":126,"i":4,"skip":true,"sec":"ariadne-und-magnum-opus"},{"t":"p","x":"Ariadne spürt in ihrem Herzen, dass der Magnum- Opus-Kult ein Schwindel ist, und es sich eher um ein Labyrinth handelt, in dem sich ein gefräßiger „Minotaurus“ verbirgt, als um ein Knäuel, das zur Befreiung führt. Das triggert ihren Mythos und bringt sie dazu, denen, die den Machenschaften des Kults zum Opfer gefallen sind, zu helfen, den Weg zurück zu finden.","sz":9.5,"box":[53.9,463.8,279,548.3],"p":126,"i":5,"sec":"ariadne-und-magnum-opus"},{"t":"p","x":"Gleichzeitig spürt sie, dass sich hinter den Lügen ein Körnchen Wahrheit verbirgt, auch wenn sie nicht genau weiß, welches das ist (sie könnte das Gralswasser spüren, mit dem der Kult Risse erweckt (Die Katakomben). Das macht sie neugierig, aber es ist ein Geheimnis, das außerhalb ihrer Reichweite bleibt: Armands Alchemie ist stark genug, um ihre Wahrsagekräfte zu beeinträchtigen, und die Astrologie des Zirkels würde sie als Zielscheibe markieren, wenn sie direkt eingreift.","sz":9.5,"box":[53.9,556.9,285.8,666.4],"p":126,"i":6,"sec":"ariadne-und-magnum-opus"},{"t":"p","x":"Ariadne ist nicht auf Konfrontation aus – sie neigt vielmehr dazu, „athenische“ Held:innen zu rekrutieren und ins Labyrinth zu schicken, um die Arbeit für sie zu erledigen. Das Team (oder einige Mitglieder) passt perfekt in dieses Profil. Ariadne wird nicht alles verraten, was sie über den Kult weiß und ahnt, nur so viel, dass das Team Nachforschungen anstellt.","sz":9.5,"box":[53.9,675.1,285.2,759.6],"p":126,"i":7,"sec":"ariadne-und-magnum-opus"},{"t":"h","x":"ARIADNE INS SPIEL BRINGEN","sz":16,"box":[309,62.2,497.6,78.2],"p":126,"i":8,"skip":true,"sec":"ariadne-ins-spiel-bringen"},{"t":"p","x":"Der Kontakt mit Ariadne beginnt mit einem Faden, an dem man ziehen muss: ein physischer roter Faden, der auffällig an einer Türklinke hängt, eine in einem Gespräch angedeutete Gelegenheit oder eine mystische Spur, die ein Magier-Riss zu ihr zurückverfolgen kann. Sie trifft ihre Schützlinge im Verborgenen, in einer verrauchten Sackgasse, auf einem Dach, in einem schattenverhangenen Lagerhaus abseits eines belebten Marktes oder in einer stillen Kirchen- oder Tempelnische. Dort taucht sie lautlos aus den Schatten auf, eine grauhaarige, vermummte Frau mittleren Alters in einem silbernen, aus Spinnenseide gewebten Gewand. Auf Risse wirkt sie fast geisterhaft. Für Schläfer:innen ist sie nur eine furchterregende, alte, kettenrauchende Frau in einem aschfahlen Trenchcoat.","sz":9.5,"box":[309,82.2,541.3,266.7],"p":126,"i":9,"sec":"ariadne-ins-spiel-bringen"},{"t":"p","x":"Ariadne bietet an, das Team aus dem Labyrinth von Lügen und Betrug, das die Stadt darstellt, herauszuführen. Der erste Schritt dabei ist Prof. Clay, entweder um Nachforschungen über ihn anzustellen oder um zu erfahren, was er lehrt. Sie kann einem SC, der sich zu verirren droht, ein Wollkleidungsstück schenken, das sich in der Not als Wollknäuel entpuppt (der SC erhält ein vorübergehendes Extra-Thema).","sz":9.5,"box":[309,275.3,538.2,372.3],"p":126,"i":10,"sec":"ariadne-ins-spiel-bringen"},{"t":"sh","x":"<b>ARIADNES WOLLKNÄUEL</b>","sz":12,"box":[320.6,425.1,470.9,437.1],"p":126,"i":11,"sec":"ariadne-ins-spiel-bringen"},{"t":"p","x":"<i>Relikt</i>","sz":10,"box":[320.6,446.8,346.6,456.8],"p":126,"i":12,"sec":"ariadne-ins-spiel-bringen"},{"t":"h","x":"MYSTERIUM","sz":10,"box":[320.6,468.3,375.9,478.3],"p":126,"i":13,"sec":"ariadne-ins-spiel-bringen"},{"t":"p","x":"Wie verhindere ich das Verschlingen der Reinheit?","sz":9,"box":[320.6,483,518.4,492],"p":126,"i":14,"sec":"ariadne-ins-spiel-bringen"},{"t":"h","x":"STÄRKEN","sz":10,"box":[320.6,503.8,361.2,513.8],"p":126,"i":15,"sec":"ariadne-ins-spiel-bringen"},{"t":"card","x":"<i>Besten Weg finden</i>, <i>Verwirrung zerstreuen</i>, <i>Verirrte retten</i>, <i>In ein wolliges Gewand hüllen</i>, <i>Vor Monstern warnen</i>, <i>Sackgassen erkennen</i>, <i>Mächtiger bei Held:innen</i>, <i>Kryptische Botschaften entschlüsseln</i>, <i>Schicksalsfäden erkennen</i>, <i>Nebel entmystifizieren</i>","sz":null,"k":"yellow","box":[320.8,517.2,522.7,575.4],"p":126,"i":16,"sec":"ariadne-ins-spiel-bringen"},{"t":"h","x":"SCHWÄCHEN","sz":10,"box":[320.6,587.3,377.5,597.3],"p":126,"i":17,"sec":"ariadne-ins-spiel-bringen"},{"t":"card","x":"<i>Zieht Monster an</i>, <i>Angst führt zu Zweifel</i>, <i>Leicht brennbar</i>, <i>Blinde Mitläufer:in</i>","sz":null,"k":"yellow","box":[320.8,600.8,477.8,622.9],"p":126,"i":18,"sec":"ariadne-ins-spiel-bringen"},{"t":"h","x":"THEMENVERBESSERUNG","sz":10,"box":[320.6,634.8,427.3,644.8],"p":126,"i":19,"sec":"ariadne-ins-spiel-bringen"},{"t":"p","x":"<b>Entmystifizierer:</b> Wenn du <b>Das Blatt wenden</b> mit Stärken von diesem Thema nutzt, um Merkmale und Zustände von Verwirrung oder Irreführung zu entfernen, erhältst du +1 Momentum.","sz":9,"box":[320.6,649.5,521.2,694.5],"p":126,"i":20,"sec":"ariadne-ins-spiel-bringen"}],"size":[595.276,841.89]},"127":{"tab":"","blocks":[{"t":"h","x":"SCHICHT 1:","sz":14,"box":[53.9,61.9,120.8,75.9],"p":127,"i":0,"skip":true,"sec":"schicht-1-eine-kerze-in-der-dunkelheit"},{"t":"h","x":"EINE KERZE IN DER DUNKELHEIT","sz":23,"box":[53.9,84.2,229.7,135.2],"p":127,"i":1,"skip":true},{"t":"card","x":"PROF. CLAY","sz":null,"k":"yellow","box":[72.6,140.5,167.6,165.3],"p":127,"i":2,"sec":"schicht-1-eine-kerze-in-der-dunkelheit"},{"t":"ro","x":"Ihr schleicht euch in den Hörsaal und nehmt in den hinteren Reihen Platz. Der stämmige, bärtige Mann auf dem Podium fesselt seine Zuhörer mit tiefgründigen Fragen. Hinter ihm an der Tafel sind Schaubilder und Diagramme zu sehen, das Wort TRANSFORMATION? ist mehrfach eingekreist. Ihr hört ihn sagen: „Ist es also möglich, denselben Prozess zu durchlaufen, all den Lärm und Dreck loszulassen und das zu werden, was wir wirklich sind? Die Alten dachten das, und sie haben uns genaue Anweisungen hinterlassen ...“","sz":9,"box":[62.4,167.2,283.8,305.8],"p":127,"i":3,"sec":"schicht-1-eine-kerze-in-der-dunkelheit"},{"t":"p","x":"<b>Prof. Gregory Clay</b>, ein angesehener (und unorthodoxer) Professor für Philosophie und Altertum an der Altstadt-Universität, ist in Wirklichkeit Jünger des Magnum Opus und wichtigster Rekrutierer. Er ist Frontmann des Kultes und rekrutiert gefügige Personen für Erweckung und Ernte (Lämmer) sowie Draufgänger:innen, um den Kult zu vergrößern (Wölf:innen).","sz":9.5,"box":[53.9,314.8,284.8,399.3],"p":127,"i":4,"sec":"schicht-1-eine-kerze-in-der-dunkelheit"},{"t":"p","x":"Prof. Clay hat eine anziehende Persönlichkeit und jahrelange Erfahrung darin, Suchende durch die ersten Stufen des Erwachens zu führen. Er hält sich für einen Freidenker und glaubt von ganzem Herzen an den Magnum-Opus-Weg. Er rekrutiert die Anhänger:innen nicht aus böser Absicht, sondern furchtbar fehlgeleiteter Vaterliebe. Mehr noch als nach Macht strebt er nach der Mitgliedschaft im Zirkel und nach der Vereinigung mit der Quelle des Lebens, wie er sie sieht: dem Gottkönig.","sz":9.5,"box":[53.9,408,284.2,530],"p":127,"i":5,"sec":"schicht-1-eine-kerze-in-der-dunkelheit"},{"t":"p","x":"Der Professor ist mittleren Alters, kräftig, mit fassartiger Brust, Armen wie Baumstämmen und einem beeindruckenden grau melierten Bart. Seine Stimme ist rau und kratzig, die Augen fast schwarz, scheinen aber zu glimmen wie glühende Kohlen. Er kleidet sich elegant, wie es seiner Position entspricht. Wenn er leidenschaftlich Ideen vorträgt, sieht man ihn schwitzend in Hemd und Hosenträgern, mit hochgekrempelten Ärmeln und gelockerter Krawatte.","sz":9.5,"box":[53.9,538.6,286.3,648.1],"p":127,"i":6,"sec":"schicht-1-eine-kerze-in-der-dunkelheit"},{"t":"p","x":"Der Professor ist an vier Standorten anzutreffen, die sich alle in der Altstadt befinden:","sz":9.5,"box":[53.9,656.8,273.7,678.8],"p":127,"i":7,"sec":"schicht-1-eine-kerze-in-der-dunkelheit"},{"t":"p","x":"• <b>Im Hörsaal der Universität</b>, in dem er Vorträge über Religion, Spiritualität und Wege der Verwandlung hält, um Kandidat:innen anzulocken. Nutze das, um ihn als Autorität in diesen Fragen zu etablieren.","sz":9.5,"box":[53.9,690.3,286.7,737.3],"p":127,"i":8,"sec":"schicht-1-eine-kerze-in-der-dunkelheit"},{"t":"p","x":"• <b>In seinem Büro an der Uni</b>, wo er private Treffen mit den Kandidat:innen abhält. Es ist ein dunkler","sz":9.5,"box":[53.9,746,274.4,768],"p":127,"i":9,"sec":"schicht-1-eine-kerze-in-der-dunkelheit"},{"t":"h","x":"PROF. CLAYS FÄHIGKEITEN","sz":14,"box":[318.5,60.8,442.4,74.8],"p":127,"i":10,"sec":"schicht-1-eine-kerze-in-der-dunkelheit"},{"t":"p","x":"Neben esoterischem Wissen und den Mentorentechniken verfügt der Professor über zwei Elementar- Transmutationen, für Wasser und Erde, die er sich durch jahrelange treue Dienste für den Kult verdient hat. Die Sigille für diese Transmutationen sind in zwei konzentrischen Kreisen, die den größten Teil seines Rückens bedecken, in sein Fleisch eingebrannt. Sie leuchten neonhell, wenn sie aktiviert sind, sind aber unter seinem dicken Hemd gut versteckt.","sz":9,"box":[318.5,87.4,528.2,192.4],"p":127,"i":11,"sec":"schicht-1-eine-kerze-in-der-dunkelheit"},{"t":"p","x":"Die Transmutationen von Wasser und Erde erlauben es Clay, die Elemente mit einer Bewegung der Finger oder Arme zu formen. Am nützlichsten ist, dass er Wasser im Körper einer Person manipulieren kann, um sie zu lähmen oder Bewegungen zu kontrollieren. Wenn er verdeckt arbeitet, setzt er die Gaben nie ein, es sei denn, er befindet sich in großer Gefahr.","sz":9,"box":[318.5,201,528.8,282],"p":127,"i":12,"sec":"schicht-1-eine-kerze-in-der-dunkelheit"},{"t":"p","x":"S. das Bedrohungsprofil von Clay auf S. 136.","sz":9,"box":[318.5,290.7,494.6,299.7],"p":127,"i":13,"sec":"schicht-1-eine-kerze-in-der-dunkelheit"},{"t":"p","x":"Raum, mit Holz verkleidet und mit Büchern gefüllt, die Fenster mit Vorhängen verhängt. Für einen Philosophieprofessor ist das Büro groß und plüschig und bietet Blick auf das Universitätsgelände. Es ist mit alten Kunstwerken dekoriert, darunter ein Gobelin, eine Büste und ein Labor-Set. Es gibt Texte über Spiritualität und Alchemie <u>(1x1 der Alchemie).</u>","sz":9.5,"box":[317.5,351.9,539.9,436.4],"p":127,"i":14,"sec":"schicht-1-eine-kerze-in-der-dunkelheit"},{"t":"p","x":"• <b>Im Philosophie-Club</b>, in dem er die Suchenden unterrichtet. Prof. Clay nutzt eine Studiengruppe, die für die Öffentlichkeit zugänglich ist, um Sucher:innen zu rekrutieren und sie auf den ersten Schritten des spirituellen Weges zu begleiten. Die Treffen des Clubs finden regelmäßig an drei Abenden der Woche auf dem Campus statt, im Haus der ehrenhaften <b>Studierenden-Verbindung <i>My Omikron</i></b>, von der viele Mitglieder anwesend sind. Während eines Treffens wird das Haus von Mitgliedern (<t>wachsam 1</t>) bewacht. Die Versammlungsnächte sind <i>Neblig</i>, was zusätzlichen Schutz bietet. Prof. Clay ist <t>wachsam 3</t> und könnte einen Eindringling entdecken. Die Treffen, bei denen er die Grundlagen der Alchemie und des Magnum Opus beibringt, mit dem <b>Buch „Die Alchemie der Seele“</b> als Referenz (s. S. <u>1x1 der Alchemie),</u> finden bei gedämpftem Licht statt. Mit Neulingen beobachtet Prof. Clay zunächst deren Reaktion, bevor er Bunsenbrenner und Mörser hervorholt.","sz":9.5,"box":[309,445.1,540.5,679.6],"p":127,"i":15,"sec":"schicht-1-eine-kerze-in-der-dunkelheit"},{"t":"p","x":"• <b>In einer privaten Blockhütte</b> in den bewaldeten Hügeln außerhalb der Stadt, wohin er kleine Gruppen vielversprechender Studierender zu spirituellen Exerzitien mit nächtlichen Kamingesprächen und Prüfungen im Freien mitnimmt.","sz":9.5,"box":[309,688.2,536.7,747.7],"p":127,"i":16,"sec":"schicht-1-eine-kerze-in-der-dunkelheit"}],"size":[595.276,841.89]},"128":{"tab":"","blocks":[{"t":"p","x":"Wenn die SC eintreffen, versucht der Professor, einen von ihnen anzuwerben. Wenn sie misstrauisch sind, wird er nicht drängen, sondern Sucher:innen beauftragen, damit sie sich aus seinen Angelegenheiten heraushalten. Sobald das Team in eine Auseinandersetzung mit den Suchenden oder dem Professor gerät, taucht es in den astrologischen Wahrsagungen auf, was zu Vergeltungsmaßnahmen führt <u>(Schadensbegrenzung des Zirkels).</u>","sz":9.5,"box":[53.9,59.9,281.5,169.4],"p":128,"i":0,"sec":"schicht-1-eine-kerze-in-der-dunkelheit"},{"t":"p","x":"Du entlarvst Gregory Clay automatisch als Bedrohung, wenn du harte Aktion nutzt, um ihn einen SC überzeugen zu lassen (z. B. indem du ihm <t>überzeugt 3</t> gibst).","sz":9.5,"box":[53.9,178.1,285,212.6],"p":128,"i":1,"sec":"schicht-1-eine-kerze-in-der-dunkelheit"},{"t":"p","x":"Wenn ein SC echtes Interesse hat, solltest du erwägen, auf harte Aktionen zu verzichten und die Beweggründe im Dunkeln zu lassen. Spiel weiter und versuche, einen überzeugenden Prof. Clay zu präsentieren. Wenn der SC sich entschließt, ihm wegen dem Inhalt und nicht dem Zustand zu folgen, wirkt das cineastischer.","sz":9.5,"box":[53.9,221.3,286.1,293.3],"p":128,"i":2,"sec":"schicht-1-eine-kerze-in-der-dunkelheit"},{"t":"sh","x":"<b>NACHFORSCHUNGEN ÜBER DEN PROFESSOR</b>","sz":10,"box":[54.3,306.9,202.1,328.9],"p":128,"i":3,"sec":"schicht-1-eine-kerze-in-der-dunkelheit"},{"t":"card","x":"<b>Die Überprüfung des Professors ergibt nichts Auffälliges.</b> Er scheint ein geschätztes Mitglied der Fakultät zu sein, abgesehen von der Bemerkung, dass er einmal eine nicht genehmigte Exkursion unternommen hat. <b>Ein Fälscher</b> könnte erkennen, dass dies platziert wurde, damit die <b>manipulierte Datei</b> nicht zu perfekt aussieht. Wenn man weiterspürt, kommt man zu Silvio Yadao (s. S. Aufhänger, S.124, <u>Das Chinatown-Festival),</u> der die vorherige Akte für Bankerin Alona Wainwright ausgetauscht hat. Die alte Akte ist voller Einträge, die Zweifel an den weit hergeholten Ideen und der strengen Methodik des Professors aufkommen lassen.","sz":null,"k":"yellow","box":[54.1,337,286.6,533.4],"p":128,"i":4,"sec":"schicht-1-eine-kerze-in-der-dunkelheit"},{"t":"card","x":"<b>Prof. Clay leitet den Philosophie-Club</b>, eine AG, die sich im Haus der Studentenverbindung My Omikron auf dem Campus trifft.","sz":null,"k":"yellow","box":[54.1,542.3,286.6,588.7],"p":128,"i":5,"sec":"schicht-1-eine-kerze-in-der-dunkelheit"},{"t":"card","x":"<b>Clay hat viele Gesichter.</b> In der Vorlesung ist er leidenschaftlich, im Gespräch charmant und zu den Studierenden streng (sogar beleidigend, wenn sie enttäuschen), obwohl er versucht, letzteres öffentlich zu verbergen.","sz":null,"k":"yellow","box":[54.1,597.9,286.6,669.3],"p":128,"i":6,"sec":"schicht-1-eine-kerze-in-der-dunkelheit"},{"t":"sh","x":"<b>NACHFORSCHUNGEN ÜBER DEN PHILOSOPHIE-CLUB</b>","sz":10,"box":[54.3,681.4,202.1,703.4],"p":128,"i":7,"sec":"schicht-1-eine-kerze-in-der-dunkelheit"},{"t":"card","x":"Mitglieder wollen nicht theoretische Philosophie studieren – sie streben <b>danach, durch okkultes Wissen Macht zu erlangen</b>. Zum Beitreten muss man sich an Clay wenden.","sz":null,"k":"yellow","box":[54.1,711.1,286.6,769.8],"p":128,"i":8,"sec":"schicht-1-eine-kerze-in-der-dunkelheit"},{"t":"card","x":"Der Philosophie-Club besteht aus Männern und Frauen, hat aber die Mentalität einer Männerseilschaft, die sich durch Clays Aufforderung, mutig mit Fehlern und dunklen Trieben umzugehen, noch verstärkt.","sz":null,"k":"yellow","box":[309.3,54.1,541.7,125.6],"p":128,"i":9,"sec":"schicht-1-eine-kerze-in-der-dunkelheit"},{"t":"card","x":"Einige Mitglieder sind sich nicht so sicher wie andere, dass dies der richtige Weg für sie ist. Sie reden vielleicht, wenn sie alleine sind.","sz":null,"k":"yellow","box":[309.3,134.8,541.7,180.9],"p":128,"i":10,"sec":"schicht-1-eine-kerze-in-der-dunkelheit"},{"t":"card","x":"<b>Prof. Clay bringt seinen Studierenden grundlegende alchemistische Rezepte bei</b>, um einen Vorgeschmack auf das zu geben, was ihnen später zur Verfügung stehen könnten.","sz":null,"k":"yellow","box":[309.3,190.1,541.7,249.1],"p":128,"i":11,"sec":"schicht-1-eine-kerze-in-der-dunkelheit"},{"t":"card","x":"<b>Die meisten Lehren stammen aus „Die Alchemie der Seele“, einem mittelalterlichen Buch</b> von Mathilda von Aquin. Die Untersuchung des Buches führt zu <u>1x1 der Alchemie.</u>","sz":null,"k":"yellow","box":[309.3,258,541.7,317.1],"p":128,"i":12,"sec":"schicht-1-eine-kerze-in-der-dunkelheit"},{"t":"card","x":"<b>Die Kandidat:innen warten sehnsüchtig auf ihre „letzte Prüfung“</b> (die <u>Silo-Prüfung),</u> nach der der Professor sie in das „Mysterium des Gottkönigs“ einweihen wird.","sz":null,"k":"yellow","box":[309.3,326,541.7,385.1],"p":128,"i":13,"sec":"schicht-1-eine-kerze-in-der-dunkelheit"},{"t":"sh","x":"<b>SCHWÄRZUNG: KONFRONTATION MIT DER NICHTIGKEIT</b>","sz":10,"box":[309.4,396.5,534.2,418.5],"p":128,"i":14,"sec":"schicht-1-eine-kerze-in-der-dunkelheit"},{"t":"p","x":"Als erster Rekrutierer ist es die Aufgabe des Professors, die ernsthaft Suchenden von den Leichtgewichten, falschen oder schnüffelnden Kandidat:innen zu trennen. Dies geschieht durch das <b>Anbieten von Antworten</b> und durch den Zwang, sich <b>mit den eigenen Fehlern auseinanderzusetzen</b> – eine unangenehme Erfahrung, die nur die ernsthaftesten Suchenden ertragen.","sz":9.5,"box":[309,424.1,541.4,508.6],"p":128,"i":15,"sec":"schicht-1-eine-kerze-in-der-dunkelheit"},{"t":"p","x":"Bei der Rekrutierung neuer Sucher:innen, SC wie NSC, geht der Professor folgendermaßen vor:","sz":9.5,"box":[309,517.3,537.9,539.3],"p":128,"i":16,"sec":"schicht-1-eine-kerze-in-der-dunkelheit"},{"t":"p","x":"1. <b>Die Suchenden analysieren</b> (ggf. unter Verwendung der Spezialaktion <b>Dunkler Mentor</b>) und einschätzen, ob sie Lämmer oder Wölf:innen sind, was sie interessiert und wie er sie ansprechen kann (freundlich, autoritär, charmant usw.)","sz":9.5,"box":[309,548,535.5,607.5],"p":128,"i":17,"sec":"schicht-1-eine-kerze-in-der-dunkelheit"},{"t":"h","x":"RISS-REKRUT:INNEN","sz":14,"box":[320.3,635.1,416.3,649.1],"p":128,"i":18,"sec":"schicht-1-eine-kerze-in-der-dunkelheit"},{"t":"p","x":"Magnum Opus nimmt auch Risse auf, sie müssen nur den gleichen Prozess wie Schläfer:innen durchlaufen, um sich zu beweisen. Ein Riss gilt erst dann als wertvoll, wenn er die Lehren des Kults akzeptiert und bereit ist, sich dem Gottkönig zu opfern.","sz":9,"box":[320.3,661.7,526.2,718.7],"p":128,"i":19,"sec":"schicht-1-eine-kerze-in-der-dunkelheit"},{"t":"p","x":"Von Riss-Anwärter:innen erwartet der Kult, dass sie ihre Kräfte nicht nutzen, bis sie im Salbungsritual die Macht des Gottkönigs erleben.","sz":9,"box":[320.3,727.4,528.7,760.4],"p":128,"i":20,"sec":"schicht-1-eine-kerze-in-der-dunkelheit"}],"size":[595.276,841.89]},"129":{"tab":"","blocks":[{"t":"p","x":"2. So <b>eine Beziehung aufbauen</b> und über die Themen sprechen, die die Suchenden interessieren.","sz":9.5,"box":[53.9,59.9,285.5,81.9],"p":129,"i":0,"sec":"schicht-1-eine-kerze-in-der-dunkelheit"},{"t":"p","x":"3. <b>Sie einladen, das Magnum Opus zu durchlaufen:</b> Antworten auf ihre Fragen oder die Macht, ihre Position zu ändern, versprechen, wenn sie bereit ist, den Weg der Veränderung zu gehen.","sz":9.5,"box":[53.9,90.6,285,137.6],"p":129,"i":1,"sec":"schicht-1-eine-kerze-in-der-dunkelheit"},{"t":"p","x":"4. <b>Von Suchenden verlangen, dass sie ihre Ernsthaftigkeit beweisen, indem sie sich mit ihren Schwächen auseinandersetzen.</b> Eine Aufgabe wählen, die schwierig zu bewältigen ist, z. B. eine Situation, die die Schwäche eines SC auslöst (s. S. Spezialaktion <b>Dunkler Spiegel</b>) oder zu etwas bringen, das ohne Mythos-Kräfte schwierig wäre.","sz":9.5,"box":[53.9,146.3,284.3,230.8],"p":129,"i":2,"sec":"schicht-1-eine-kerze-in-der-dunkelheit"},{"t":"p","x":"5. <b>Bemühungen mit Antworten belohnen:</b> einem kostenlosen Hinweis über Alchemie oder <i>ein Exemplar von „Die Alchemie der Seele“</i>, das die Suchenden studieren können (s. S. Hinweise in <u>1x1 der Alchemie)</u>","sz":9.5,"box":[53.9,239.4,279.4,298.9],"p":129,"i":3,"sec":"schicht-1-eine-kerze-in-der-dunkelheit"},{"t":"p","x":"6. <b>Schritte 4 und 5 wiederholen</b>, dabei immer schwierigere Aufgaben stellen und größere Belohnungen gewähren.","sz":9.5,"box":[53.9,307.6,277.1,342.1],"p":129,"i":4,"sec":"schicht-1-eine-kerze-in-der-dunkelheit"},{"t":"p","x":"7. <b>Die letzte Prüfung:</b> Wenn die Kandidat:in ausreichend Engagement gezeigt hat und Clay glaubt, dass sie die Prüfung bestehen kann, lädt er sie zur <u>Silo-Prüfung</u> ein.","sz":9.5,"box":[53.9,350.8,277.8,397.8],"p":129,"i":5,"sec":"schicht-1-eine-kerze-in-der-dunkelheit"},{"t":"sh","x":"<b>ZITATE DES PROFESSORS</b>","sz":10,"box":[54.3,411.4,191.5,421.4],"p":129,"i":6,"sec":"schicht-1-eine-kerze-in-der-dunkelheit"},{"t":"p","x":"• <b>„Sie sind blind</b>. Deshalb finden Sie nicht, was Sie suchen. Der erste Schritt auf dem Weg ist, in dem zu erwachen, was Sie nicht sehen - Ihre eigene Dunkelheit, Ihre eigene Nichtigkeit.“","sz":9.5,"box":[53.9,429.8,282,476.8],"p":129,"i":7,"sec":"schicht-1-eine-kerze-in-der-dunkelheit"},{"t":"p","x":"• „<b>Alchemie ist der Weg zur Transformation der Seele</b>. Ich und dieses Buch, wir können Ihnen nur den Weg weisen. Gehen müssen Sie ihn selbst.“","sz":9.5,"box":[53.9,485.5,272.4,520],"p":129,"i":8,"sec":"schicht-1-eine-kerze-in-der-dunkelheit"},{"t":"threat","stars":"★★","name":"PROF. CLAY UNDERCOVER","spectra":"VERLETZEN ODER UNSCHÄDLICH MACHEN 2 / VOR- LÄUFIG BEDROHEN 3","items":["<b>Disziplinierter Geist:</b> Wenn Prof. Clay die Szene betritt, gib ihm <t>wachsam 3</t>. Er achtet auf das, was er sagt, und auf seine Umgebung.","<b>Dunkler Mentor:</b> Immer, wenn ein SC Prof. Clay um Antworten bittet (egal, ob mit <b>Nachforschungen</b> oder nicht), fragt die SL: „Was suchst du?“ Clay kennt die Antwort. Die fragende Person erhält einen relevanten Stufe-1-Zustand, z. B. <t>Wunsch nach Dazugehörigkeit 1</t>, <t>Suche nach arkanem Wissen 1</t> usw. Mehrere Zustände addieren normal.","<b>Dunkler Spiegel:</b> Immer wenn ein SC eine Schwäche nutzt, während er eine Aufgabe Prof. Clays ausführt, verringert sich seine Kraft um 3 statt um 1.","<b>Ärmel hochkrempeln:</b> Wenn er in Lebensgefahr ist oder geheime Informationen preisgeben könnte, lässt er zuvor die Tarnung auffliegen. Verwende das Profil <b>Gregory Clay als Jünger</b> (s. S. 136).","Eine universelle Wahrheit aussprechen, die jemanden <t>nachdenklich 2</t> oder <t>zögernd 2</t> macht","Jemandem bei der Bewältigung von Angst oder Verwirrung helfen (bis zu 2 Stufen entfernen)","Erkennen, was jemand sucht (indem er ihm wie bei <b>Dunkler Mentor</b> einen Zustand verleiht)","Jemanden mit der Möglichkeit verführen, zu finden, was die betreffende Person sucht","Jemanden mit seinem brennenden, die Seele durchdringenden Blick anstarren","„<b>Ihre Kräfte sind das, was wir <i>Katzengold</i> nennen</b>. Wissen Sie, woher sie stammen? Was sie sind? Sind es wirklich Ihre Kräfte? Oh nein. Für die Wahrheit müssen Sie die Lüge aufgeben. Um zum Stein der Weisen zu werden, müssen Sie sich zuerst schmelzen und die Schlacken und Verunreinigungen entfernen.“","„Wenn Sie nicht bereit sind, etwas dafür zu opfern, sind Sie nicht bereit für die Wahrheit. <b>Nur Eingeweihte können die letzte Wirklichkeit erfassen.</b>“","„<b>Ich verlange nicht, dass Sie Ihre Aufgabe erfolgreich bewältigen, ich verlange, dass Sie es versuchen</b>, damit Sie Ihre Fehler sehen und erkennen.„","„Jenseits der Grenzen dieser Stadt, dieser perversen Welt, wartet der <b>Gottkönig</b>, die Quelle aller Existenz. Sich mit ihm zu vereinen bedeutet absolute Allwissenheit und Allmacht. Das ist das Potenzial, das in Ihrer Seele verborgen ist.“"],"box":[445.1,58.3,465.5,70.3],"p":129,"i":9,"sec":"schicht-1-eine-kerze-in-der-dunkelheit"}],"size":[595.276,841.89]},"130":{"tab":"","blocks":[{"t":"h","x":"1X1 DER ALCHEMIE","sz":16,"box":[79.7,68.9,206.5,84.9],"p":130,"i":0,"skip":true,"sec":"1x1-der-alchemie"},{"t":"ro","x":"„Hier ist es“, sagt die ernste Bibliothekarin, während sie das abgenutzte Buch sanft über den Tresen schiebt. ‚Die Alchemie der Seele’, 1233, von Mathilda von Aquin. Es ist ein Faksimile des mittelalterlichen Originalmanuskripts, ziemlich schwer zu bekommen.“ Ihr nehmt das in Leder gebundene Buch in die Hand und blättert es durch, überfliegt kryptische Worte, heilige Verse, vergessene Formeln und seltsame Sigillen. Es sieht aus, als hättet ihr eine Menge Arbeit vor euch.","sz":9,"box":[62.4,87.3,283.8,215.1],"p":130,"i":1,"sec":"1x1-der-alchemie"},{"t":"p","x":"Früher oder später wird sich das Team mit den magischen Künsten befassen müssen, die die Grundlage der Macht des Kults sind. Es könnte Dinge sehen, die auf ein Studium oder die Anwendung alchemistische Kräfte durch den Kult hindeuten, z. B.:","sz":9.5,"box":[53.9,224.1,276.2,283.6],"p":130,"i":2,"sec":"1x1-der-alchemie"},{"t":"p","x":"• Jemand ruft Phrasen in mittelalterlichem Latein • Die von Suchenden und Initiant:innen verwendeten alchemistischen Pulver und Gebräue • Die strahlenden Sigillen einer Transmutation, die eine Jünger:in aktiviert • Eine Mythos-Tinktur <i>• Athanor</i>: Ofen oder Ichor (Rohstoff der Ernte)","sz":9.5,"box":[53.9,289.4,281.5,373.9],"p":130,"i":3,"sec":"1x1-der-alchemie"},{"t":"p","x":"Akademische Teammitglieder oder solche, die sich mit Okkultismus auskennen, sollten <b>Nachforschungen</b> anstellen, um die folgenden Hinweise über Magnum Opus zu erhalten. Andere SC könnten sich an Fachleute wenden. Je mehr das Team über den Kult und seine Alchemie erfährt, desto mehr Aufmerksamkeit erregt es, was schließlich einen Angriff auslöst, wenn es am dramatischsten ist <u>(Schadensbegrenzung des Zirkels).</u>","sz":9.5,"box":[53.9,379.7,284,476.7],"p":130,"i":4,"sec":"1x1-der-alchemie"},{"t":"sh","x":"<b>NACHFORSCHUNGEN ÜBER DIE KULTIST:INNEN</b>","sz":10,"box":[54.3,490.3,202.1,512.3],"p":130,"i":5,"sec":"1x1-der-alchemie"},{"t":"card","x":"<b>Magnum Opus nutzt Schlagworte und Rufe in mittelalterlichem Latein.</b> Sie nenen den „lebensspendenden Vater“, die „Waschung mit Quecksilber“, etwas, „so leuchtend wie die Sonne“ und ein „heiliges Feuer“. Dies sind Zeilen aus dem <b>Gesang der Initiant:innen</b>, einem Choral aus „<b>Die Alchemie der Seele</b>„.","sz":null,"k":"yellow","box":[54.1,522.4,286.6,618.9],"p":130,"i":6,"sec":"1x1-der-alchemie"},{"t":"card","x":"Die verwendeten <b>chemischen Formeln</b> gehen auf die alte Wissenschaft der Alchemie zurück. <b>Die leuchtenden Zeichen</b>, aus denen die Jünger:innen ihre Kraft schöpfen, sind Sigillen, die Elemente repräsentieren. <b>Die Kraft der Elemente-Manipulation</b> könnte alchemistischer Natur sein. Quelle der Symbolik ist <b>ein esoterisches mittelalterliches Buch, „Die Alchemie der Seele“</b> von Mathilda von Aquin, das man ganz hinten in der Bibliothek oder in einem alten Buchladen finden kann.","sz":null,"k":"yellow","box":[54.1,628.1,286.6,774.4],"p":130,"i":7,"sec":"1x1-der-alchemie"},{"t":"sh","x":"<b>NACHFORSCHUNGEN ÜBER DIE ARTEFAKTE</b>","sz":10,"box":[309.4,62.8,457.2,84.8],"p":130,"i":8,"sec":"1x1-der-alchemie"},{"t":"card","x":"<b>Eine (Mythos-)Tinktur</b> enthält die Essenz einer Legende (Ichor ist ihr Rohstoff). Die einzig denkbare Quelle einer solch mächtigen Mythos-Kraft ist der Riss dieses Mythos.","sz":null,"k":"yellow","box":[309.3,88.7,541.7,147.5],"p":130,"i":9,"sec":"1x1-der-alchemie"},{"t":"card","x":"<b>Den Ofen</b> hat ein Meister okkulter Künste gebaut, jemandem, der geistige Essenz aus Materie extrahieren kann – wahrscheinlich ein Alchemist. Es ist nicht zu enträtseln, wer ihn gebaut hat oder wie er funktioniert, wenn man nicht über alchemistisches Wissen verfügt.","sz":null,"k":"yellow","box":[309.3,156.7,541.7,240.5],"p":130,"i":10,"sec":"1x1-der-alchemie"},{"t":"p","x":"<b>Wenn du eine Verbindung zwischen den Fällen herstellen willst, könnte das Studium einer Tinktur mit divinatorischen Kräften auch zu anderen Spuren führen:</b>","sz":10,"box":[317.5,255.3,525.1,302.8],"p":130,"i":11,"sec":"1x1-der-alchemie"},{"t":"p","x":"• Zum Ofen, in dem sie geerntet wurde (die alte <u>Aurora-Glashütte</u> in <i>Athanor</i>, S. 105),","sz":10,"box":[317.5,310.9,515,333.5],"p":130,"i":12,"sec":"1x1-der-alchemie"},{"t":"p","x":"• Zur Macherin des Ofens, Rosina Leckermaul <u>(Frau Leckermauls Haus</u> in <i>Athanor</i>, S. 92) oder","sz":10,"box":[317.5,338.7,527.9,373.7],"p":130,"i":13,"sec":"1x1-der-alchemie"},{"t":"p","x":"• Zum Erschaffer der Tinktur(en), Armand Kai in <u>Canseliet Manor</u> (in <i>Der Alchemist</i>, S. 155).","sz":10,"box":[317.5,379.1,522,414.1],"p":130,"i":14,"sec":"1x1-der-alchemie"},{"t":"sh","x":"<b>DIE LEKTÜRE VON „DIE ALCHEMIE DER SEELE“</b>","sz":10,"box":[309,437.6,461.7,459.6],"p":130,"i":15,"sec":"1x1-der-alchemie"},{"t":"card","x":"Auf der Innenseite der Umschlagseite hat jemand etwas gekritzelt: <b>„Suchen Sie Antworten? Rufen Sie Prof. Gregory Clay an“</b>. Daneben steht die Telefonnummer <u>Prof. Clays.</u>","sz":null,"k":"yellow","box":[309.3,464.5,541.7,523.3],"p":130,"i":16,"sec":"1x1-der-alchemie"},{"t":"card","x":"Dem Buch zufolge geht es in der Alchemie nicht um die Wandlung unedler Metalle in Gold. Die Erschaffung des Steins der Weisen, <b>auch Großes Werk oder Magnum Opus genannt, ist eine Transformation der Seele</b> aus dem Schlaf ins Erwachen, in dem sie sich mit der Quelle allen Lebens verbinden kann.","sz":null,"k":"yellow","box":[309.3,532.5,541.7,628.7],"p":130,"i":17,"sec":"1x1-der-alchemie"},{"t":"card","x":"<b>Die Quelle allen Lebens ist „die Gottheit“ oder „der Gottkönig“.</b> Obwohl dieses Wesen verehrt wird, ist es keine moralische Instanz oder personifizierte Gottheit, sondern ein Quell von Wissen und Macht, mit der sich Alchemist:innen zu vereinen suchen.","sz":null,"k":"yellow","box":[309.3,637.9,541.7,721.7],"p":130,"i":18,"sec":"1x1-der-alchemie"}],"size":[595.276,841.89]},"131":{"tab":"","blocks":[{"t":"card","x":"Wie das Team weiß, tragen die Menschen in dieser Stadt eine besondere Art von Magie in sich (den Mythos). <b>Theoretisch kann man diese Form der Alchemie nutzen, um mythische Kräfte zu manipulieren oder gar zu erwecken.</b>","sz":null,"k":"yellow","box":[8.6,24.8,286.6,125.6],"p":131,"i":0,"sec":"1x1-der-alchemie"},{"t":"card","x":"<b>Das alchemistische Magnum Opus besteht aus vier Stufen:</b> Schwärzung oder Fäulnis, Weißung oder Läuterung, Gilbung oder Erwachen und Rötung oder Transformation.","sz":null,"k":"yellow","box":[54.1,134.8,286.6,193.5],"p":131,"i":1,"sec":"1x1-der-alchemie"},{"t":"card","x":"<b>Das Buch enthält den Gesang der Initiant:innen,</b> der ein Gebet an den Gottkönig oder ein meditativer Choral sein kann. Sowohl im Original als auch in der Übersetzung gibt es einige Ungenauigkeiten (s. S. nächster Hinweis).","sz":null,"k":"yellow","box":[54.1,202.8,286.6,273.9],"p":131,"i":2,"sec":"1x1-der-alchemie"},{"t":"card","x":"Eine weitere Untersuchung bringt das Buch mit keiner anderen Literatur in Verbindung. Es scheint sehr obskur zu sein. Eine besonders sorgfältige Recherche könnte zu Tage fördern, <b>dass der Text in Wirklichkeit eine neuzeitliche Fälschung ist.</b> (Der Autor ist Armand Kai.)","sz":null,"k":"yellow","box":[54.1,283.1,286.6,366.9],"p":131,"i":3,"sec":"1x1-der-alchemie"},{"t":"card","x":"<b>Im Buch gibt es ein Rezept, um unsichtbare Tinte herzustellen und sichtbar zu machen.</b> Bei erfolgreicher Anwendung auf das Buch entdeckt man verborgene Anmerkungen, die den Zustand <t>obskur</t> aufheben (s. u.) und weitere Hinweise geben (s. S. <u>Valériens Kuriosa).</u> Fehler bei dem Prozess zerstören das Buch.","sz":null,"k":"yellow","box":[54.1,376.1,286.6,472.6],"p":131,"i":4,"sec":"1x1-der-alchemie"},{"t":"p","x":"SC, die Nachforschungen anstellen, können die oben genannten Hinweise entdecken. Wenn sie tiefer gehen, stoßen sie auf eine Mauer: Die alchemistische Symbolik und Überlieferung wird <t>obskur 3</t> oder <t>esoterisch 3</t>, es sei denn, der SC ist Experte für diese Art von Alchemie.","sz":9.5,"box":[53.9,486.2,286.5,545.7],"p":131,"i":5,"sec":"1x1-der-alchemie"},{"t":"card","x":"<b>Kontakte in akademischen oder okkulten Kreisen</b> können auf <u>Valériens Kuriosa</u> als Ort hinweisen, an dem man nach Antworten auf obskure und esoterische Themen sucht.","sz":null,"k":"yellow","box":[54.1,563.6,286.6,622.7],"p":131,"i":6,"sec":"1x1-der-alchemie"},{"t":"h","x":"CHINATOWN-FESTIVAL","sz":16,"box":[334.8,68.9,486.3,84.9],"p":131,"i":7,"skip":true,"sec":"chinatown-festival"},{"t":"ro","x":"Das ständige Pfeifen und Knistern von Feuerwerkskörpern und der Klang von Glocken und Zimbeln übertönen fast den Lärm der Menschenmenge, die sich um euch herum tummelt. An jedem Haus und über den Straßen hängen Lampions. Tausende von Besucher:innen und Einheimischen schlendern durch die Straßen, probieren Street Food und bewundern die farbenfrohen Aufführungen. Im Zentrum des Festes starten Feuerwerkskörper, um eine Prozession von Festwagen und die riesige Figur eines Drachens in Szene zu setzen. Euer Kontaktmann hat diesen Ort aus gutem Grund gewählt: Hier kann man leicht in der Menge verschwinden. Aber irgendwas stimmt nicht. Euch sträuben sich die Nackenhaare, als ihr die dunklen Gassen Chinatowns um euch seht. Dann hört ihr einen Schrei, der die festliche Musik übertönt. Hinter euch sind Flammen, und inmitten des Brandes windet sich der Drache, während seine Lenker:innen in Panik fliehen.","sz":9,"box":[317.5,87.3,538.9,333.9],"p":131,"i":8,"sec":"chinatown-festival"},{"t":"p","x":"Als der Einbrecher und Reliktdieb <b>Silvio Yadao</b> (Tinktur der <i>Tarnkappe</i> aus dem <i>Nibelungenlied</i>) beschloss, ehrlich zu werden und seiner Auftraggeberin (Alona Wainwright vom Zirkel) aus dem Weg zu gehen, schickte sie ihm eine unmissverständliche Drohung. Während Silvio und seine Tochter Helena (Schläferin) darauf warten, das Team beim Fest in Chinatown zu treffen, schenkt einer der Verkäufer, vom Kult bezahlt, Helena eine Handrassel.","sz":9.5,"box":[309,342.9,540.4,452.4],"p":131,"i":9,"sec":"chinatown-festival"},{"t":"p","x":"<b>Die Handrassel ist eine mythoserfüllte „Bombe“</b>: Sie enthält die unfallträchtige Tinktur des <i>Zauberlehrlings</i>, des Mythos der außer Kontrolle geratenen Magie. Jedes Mal, wenn Helena die Rassel schüttelt, verzaubert sie einen Gegenstand und erweckt ihn zum Leben. Aufgrund des Mythos führt jeder unbedachte Versuch, das Objekt zu stoppen, dazu, dass es sich dupliziert und mehr Chaos anrichtet. Leider war eines der ersten Dinge, die Helena verzauberte, die feuerspeiende Drachenfigur des Festes.","sz":9.5,"box":[309,461,541.1,583],"p":131,"i":10,"sec":"chinatown-festival"},{"t":"p","x":"Darüber hinaus ist die Rassel für magiebegabte Risse, die die Kontrolle über ihre Kräfte verlieren könnten, gefährlich. Zauber:innen und Hexen, die die Trommel berühren, müssen <b>Ein Risiko eingehen</b>, um ihre Kräfte zu kontrollieren. 7-9 bedeutet, dass die Beherrschung ihren Tribut fordert oder ein Zugeständnis verlangt (<b>Sie vor eine Wahl stellen</b>), während ein Scheitern dazu führt, dass sie temporär die Kontrolle verlieren (ähnlich wie ein Scheitern bei <b>Jetzt reicht’s!</b>), mit je nach Situation leichten oder schweren Auswirkungen. Optional kannst du einem solchen SC <t>unkontrollierte Kräfte 2</t> verleihen.","sz":9.5,"box":[309,591.7,535.7,738.7],"p":131,"i":11,"sec":"chinatown-festival"}],"size":[595.276,841.89]},"132":{"tab":"","blocks":[{"t":"p","x":"Dieser dramatische Vorfall dient als spannungsgeladener Aufhänger, der den Fall aufklären oder Ermittlungen in Gang bringen kann. Das Team muss seinen Informanten Silvio Yadao ausfindig machen und retten, der dann bitten wird, seine Tochter zu retten. Das Teams muss möglicherweise unschuldige Zuschauer:innen schützen. Die Untersuchung des Vorfalls kann während des Geschehens oder danach erfolgen.","sz":9.5,"box":[53.9,361.8,285.5,458.8],"p":132,"i":0,"sec":"chinatown-festival"},{"t":"card","x":"<b>Die Drohung wirkt: Silvio gibt den Widerstand für den <u>Job auf der Ausgrabung</u> auf, um sein kleines Mädchen nicht zu gefährden.</b> Er ist von der Rücksichtslosigkeit der Arbeitgeberin überrascht. Silvio hätte nicht gedacht, dass sie seine Tochter verletzen könnte. Falls das Team ihn aufhalten will, warnt Silvio, ihm aus dem Weg zu gehen.","sz":null,"k":"yellow","box":[309.3,356,541.7,464.8],"p":132,"i":1,"sec":"chinatown-festival"},{"t":"card","x":"<b>Helenas Handrassel verursacht das Chaos.</b> Die Untersuchung des Musikinstruments zeigt, dass sie eine flüchtige magische Flüssigkeit (Tinktur) enthält. <b>Jenseits des Nebels</b> offenbart sich der Mythos des Zauberlehrlings, die Vision eines hilflosen jungen Mannes in einem Zauberergewand, der die Kontrolle über eine Schar animierter Besen verloren hat.","sz":null,"k":"yellow","box":[54.1,473.5,286.6,582.3],"p":132,"i":2,"sec":"chinatown-festival"},{"t":"card","x":"<b>Laut Silvio ist eine Antiquitätensammlerin, für die er arbeitet, verantwortlich.</b> Er weiß nicht, wie sie heißt, nur, dass sie Artefakte sammelt. Silvio hat für sie Gegenstände gestohlen, aber jetzt, will er ehrlich werden.","sz":null,"k":"yellow","box":[54.1,591.6,286.6,662.7],"p":132,"i":3,"sec":"chinatown-festival"},{"t":"card","x":"<b>Silvio verbirgt seine Gefühle und will nichts über die <u>Ausgrabung</u> sagen, denn er hat</b> <t>Angst um seine Tochter 3</t>. Er weiß, dass es um den Diebstahl einer alten Tafel geht. Wenn das Team den Plan aufdeckt, bittet er die SC, sich nicht einzumischen.","sz":null,"k":"yellow","box":[309.3,474,541.7,557.9],"p":132,"i":4,"sec":"chinatown-festival"},{"t":"card","x":"<b>Silvio vergisst zu erwähnen, dass er die Tinktur der Tarnkappe trägt, die er von seiner Arbeitgeberin bekommen hat.</b> Die Ampulle ermöglicht es, sich unsichtbar zu machen und schützt vor Überwachung und Wahrsagerei, was das Leben als Einbrecher sehr erleichtert.","sz":null,"k":"yellow","box":[309.3,567.1,541.7,650.9],"p":132,"i":5,"sec":"chinatown-festival"},{"t":"card","x":"<b>Bedienstete seiner Arbeitgeber:in - Initiant:innen von Magnum Opus – überwachen die Falle</b> aus einer sicheren Position auf den Dächern Chinatowns.","sz":null,"k":"yellow","box":[309.3,660.1,541.7,718.8],"p":132,"i":6,"sec":"chinatown-festival"},{"t":"card","x":"Zu Informationen, die das Studium der Tinktur erbringt, s. <u>1x1 der Alchemie.</u>","sz":null,"k":"yellow","box":[309.3,728.1,541.7,761.8],"p":132,"i":7,"sec":"chinatown-festival"}],"size":[595.276,841.89]},"133":{"tab":"","blocks":[{"t":"threat","stars":"★★★","name":"ANIMIERTER FEUERDRACHE","spectra":"ZERREISSEN 2 / ENTZAUBERN 4 / LÖSCHEN 4","items":["<b>Monströs</b>: Wenn die Drachenfigur einen Zustand erleidet, den ihre Größe konterkariert, reduziere seine Stufe um 1. Wenn die SL eine harte Aktion mit der Drachenfigur ausführt, kann sie zwei Ziele oder ein einzelnes Ziel für +1 Stufe treffen.","<b>Unglückliche Verzauberung</b>: Wenn <i>Zerreißen 2</i> den Maximalwert erreicht, spaltet sich die Figur in zwei separate Drachen (anstelle dieser Bedrohung entstehen zwei neue Feuerdrachen).","Die Flammen verbrennen (<t>Verbrennungen 2</t>)","Der Drache lässt eine Person fallen, die sie trägt (<t>Rippenbruch 3</t> oder <t>Gehirnerschütterung 3</t>)","Einen Straßenabschnitt mit einem Feuerstoß in Brand setzen und dabei Helena, Silvio, einen SC oder einen Passanten gefährden","Helena, Silvio, einen SC oder Unbeteiligte, die sich mit Mühe festhalten können, in die Luft tragen","Sich brennend winden und in der Luft tanzen"],"box":[202,57.5,232.6,69.5],"p":133,"i":0,"sec":"chinatown-festival"},{"t":"h","x":"MONDGEIST","sz":16,"box":[53.9,379.7,135.4,395.7],"p":133,"i":1,"skip":true,"sec":"mondgeist"},{"t":"p","x":"Erschwerend kommt hinzu, dass <b>Tracy Chang</b> (Chang’e, chinesische Mondgöttin), unter Verbrechern bekannt als die maskierte Superheldin <b>Mondgeist</b>, das Chaos von den Dächern aus beobachtet. Mondgeist ist eine Sportlerin und in vielen Gymnastik- und Kampfsportarten firm. Vor kurzem hat sie ihre Fähigkeit, im Mondlicht zu fliegen, entdeckt und bekämpft seitdem Verbrechen. Sie weiß nicht, dass ihr Mythos sie unsterblich macht, bis sie zum ersten Mal stirbt.","sz":9.5,"box":[53.9,399.6,284.3,509.1],"p":133,"i":2,"sec":"mondgeist"},{"t":"p","x":"Mondgeist fühlt sich von der Szene angezogen, weil der Mythos ihrer Göttin mit dem Herbstfest in Verbindung steht und sie eine Verbrechensbekämpferin ist. Zusätzlich führt ihr Mythos sie an den Ort, weil Silvio Yadao das Rezept für das Lebenselixier stehlen will (das Trinken eines solchen Elixiers machte Chang’e zur Mondgöttin). All dies macht ihre Verstrickung mit Silvio, dem Team und dem Kult geradezu unaufhaltsam.","sz":9.5,"box":[53.9,517.8,286.3,614.8],"p":133,"i":3,"sec":"mondgeist"},{"t":"p","x":"Mondgeist kann sich mit dem Team zusammentun, um das Chaos auf dem Festival zu beenden, oder in einen Streit mit ihm geraten, wenn es sie fälschlicherweise mit Silvios Arbeitgeberin in Verbindung bringt oder sie herausfindet, dass sie hinter der Tafel her sind. Letztlich wird sie jedoch alles tun, um die Tafel während der <u>Ausgrabung</u> zu schützen.","sz":9.5,"box":[53.9,623.5,285.7,708],"p":133,"i":4,"sec":"mondgeist"},{"t":"threat","stars":"★★★","name":"MONDGEIST (+ )","spectra":"VERLETZEN ODER UNSCHÄDLICH MACHEN 4 / GEFANGEN- NEHMEN 4","items":["<b>Unsterblich:</b> Wenn Mondgeist stirbt, kann die SL als harte Aktion ihr Spektrum <i>Verletzen oder unschädlich</i> machen zurücksetzen, es sei denn, etwas behindert die Mythos-Kräfte.","<b>Äthergestalt</b>: Mondgeist kann Äthergestalt annehmen. Sie ist sichtbar aber nicht über Gewicht, Bewegung, Hitze oder Geräusche erkennbar.","<b>Mondlicht</b>: Im Mondlicht kann Mondgeist fliegen. Es erhöht außerdem die Stufe aller ihrer harten Aktionen um 1.","<b>Wiedererweckung</b> +★: Wenn Mondgeist zum ersten Mal stirbt, wird sie vom berührten Riss zur Grenzgängerin. Sie wird zu ihrer eigenen Quelle des <b>Mondlichts</b>. Behandle Mondlicht als immer anwendbar. Außerdem erhält sie <b>Himmlische Mond-Aura</b> und eine neue harte Aktion.","<b>Himmlische Mond-Aura:</b> Wenn Mondgeist körperlichen Schaden, Unschädlichmachung, Fesselung oder einen Zustand aus dunkler oder böser Quelle erleidet, reduziert sich seine Stufe um 2.","Durch die Luft fliegen und übermenschliche akrobatische Kunststücke vollbringen (sich <t>ausweichen 1</t> verleihen)","Sturzflug oder Kampfsportschlag im Vorbeifliegen (<t>benommen 2</t>, <t>Prellung 2</t> oder <t>liegend 2</t>)","Auftauchen, um eine zwielichtige Aktivität im Mondlicht zu unterbrechen (<b>Die Dinge richtig kompliziert machen</b>)","Der Mond kommt hinter einer Wolke hervor oder spiegelt sich irgendwo (<b>Die Dinge richtig kompliziert machen</b> oder ein Merkmal entfernen, das das Mondlicht verdeckt)","(Nach der Aktivierung von <b>Wiedererweckung</b>) Gleißende Mondstrahlen aus den Fingerspitzen verschießen (dreimal <t>geschockt 2</t>. Die Effekte von <b>Mondlicht</b> sind einberechnet)","Eine dunkle Silhouette huscht über den Mond"],"box":[393.8,55.3,438.3,67.3],"desc":"Mondgeist ist eine kurvenreiche junge Frau in sportlicher Kleidung: ein Kapuzenpulli über einem Sport-T-Shirt, Jogginghosen oder Leggins und Sneakers. Sie ist wendig, stark und kann problemlos an Feuerleitern, Abflussrohren und anderen Befestigungen städtisches Terrain schnell erklimmen. Im Mondlicht kann sie Hindernisse überfliegen.","p":133,"i":5,"sec":"mondgeist"},{"t":"sh","x":"<b>MONDGEIST</b>","sz":12,"box":[350.3,536.4,423.6,548.4],"p":133,"i":6,"sec":"mondgeist"},{"t":"p","x":"<i>Verbündete</i>","sz":10,"box":[350.3,558.1,404.7,568.1],"p":133,"i":7,"sec":"mondgeist"},{"t":"h","x":"MYSTERIUM","sz":10,"box":[350.3,579.6,405.6,589.6],"p":133,"i":8,"sec":"mondgeist"},{"t":"p","x":"Was ist der Preis des ewigen Lebens?","sz":9,"box":[350.3,594.3,500.3,603.3],"p":133,"i":9,"sec":"mondgeist"},{"t":"h","x":"STÄRKEN","sz":10,"box":[350.3,615.1,391,625.1],"p":133,"i":10,"sec":"mondgeist"},{"t":"card","x":"<b><i>Erfahrene Kampfsportlerin</i></b>, <i>unsterblich</i>, <i>Fliegen im Mondlicht</i>, <i>Verbrechensbekämpfung</i>, <i>Mondstrahlen aus den Fingerspitzen</i>, <i>Himmlische Mond-Aura</i>, <i>Informanten in der Unterwelt</i>, <i>Trainingsraum</i>, <i>Königinmutter des Westens</i>, <i>unbestechlich</i>","sz":null,"k":"yellow","box":[350.5,628.7,553,686.6],"p":133,"i":11,"sec":"mondgeist"},{"t":"h","x":"SCHWÄCHEN","sz":10,"box":[350.3,698.6,407.3,708.6],"p":133,"i":12,"sec":"mondgeist"},{"t":"card","x":"<i>Impulsiv</i>, <i>schwächer ohne Mond</i>, <i>ignoriert das Gesetz</i>, <i>Schwäche für Bogenschützen</i>","sz":null,"k":"yellow","box":[350.5,711.9,559.3,734.1],"p":133,"i":13,"sec":"mondgeist"},{"t":"h","x":"THEMENVERBESSERUNG","sz":10,"box":[350.3,746.1,457.1,756.1],"p":133,"i":14,"sec":"mondgeist"},{"t":"p","x":"<b>Unsterblich:</b> Wenn sie körperlichen Schaden Stufe 6 erleidet, entferne ihn nach der nächsten Drehpause.","sz":9,"box":[350.3,760.8,566,781.8],"p":133,"i":15,"sec":"mondgeist"}],"size":[595.276,841.89]},"134":{"tab":"","blocks":[{"t":"h","x":"SCHICHT 2:","sz":14,"box":[53.9,61.9,122.1,75.9],"p":134,"i":0,"skip":true,"sec":"schicht-2-gefaehrliche-ausgrabungen"},{"t":"h","x":"GEFÄHRLICHE AUSGRABUNGEN","sz":23,"box":[53.9,84.2,212.4,135.2],"p":134,"i":1,"skip":true},{"t":"h","x":"VALÉRIENS KURIOSA","sz":16,"box":[79.7,148.8,215,164.8],"p":134,"i":2,"skip":true,"sec":"val-riens-kuriosa"},{"t":"ro","x":"Valériens Kuriosa liegt in der verwinkelten Altstadt. Nur ein gemalter Schriftzug über der altertümlichen Tür weist auf den Laden hin. Innen ist er überraschend groß und vom Boden bis zur Decke vollgestopft mit Büchern, Schmuckstücken, archäologischen Gegenständen, Gläsern mit seltsamen Zutaten und zerfallenden Schriftrollen. „Man könnte sich hier unten verirren“, warnt der Besitzer Valérien, ein ergrauender, bebrillter Mann in einer Tweedweste, während er auf die Wege in dem riesigen Fundus an esoterischem Wissen zeigt, den er hegt. „Nehmen Sie eine Lampe mit“, fügt er hinzu.","sz":9,"box":[62.4,167.2,283.8,327.4],"p":134,"i":3,"sec":"val-riens-kuriosa"},{"t":"p","x":"Valériens Kuriosa (das Kaninchenloch aus <i>Alice im Wunderland</i>) ist die Anlaufstelle für alle, die sich mit dem Okkulten beschäftigen. SC, die sich aktiv mit Magie befassen, kennen ihn wahrscheinlich schon oder werden sich freuen, ihn zu entdecken. Sein einziger Eingang ist die besagte Tür in einer Gasse der Altstadt, aber im Inneren scheint er sich tief ins Gebäude zu erstrecken. Wer den Laden erkundet, findet immer wieder einen neuen Gang, weiteren Raum oder eine Wendeltreppe. Die tiefen Nischen scheinen in einen Erdkeller überzugehen, und unvorsichtige Besucher könnten in ein tieferes Stockwerk fallen, um dort auf einem alten, mit Laub bedeckten Sessel zu landen.","sz":9.5,"box":[53.9,336.4,285.8,495.9],"p":134,"i":4,"sec":"val-riens-kuriosa"},{"t":"p","x":"Valériens Kuriosa bietet akademisch und okkult interessierten Teammitgliedern die Möglichkeit, die Überlieferungen des Magnum Opus zu erforschen. Als Enklave des Kaninchenlochs findet sich hier vermutlich jedes Buch oder Objekt, das Forscher:innen oder Okkultist:innen benötigen, und kann sogar SC, die keine Gelehrten sind, helfen, Antworten zu finden. Während der vordere Teil des Ladens Bücher zu trivialen oder alltäglichen Themen enthält, finden sich tiefer uralte Manuskripte und magische Gegenstände, die viele Geheimnisse entschlüsseln könnten.","sz":9.5,"box":[53.9,504.6,280.8,639.1],"p":134,"i":5,"sec":"val-riens-kuriosa"},{"t":"sh","x":"<b>IN DER KURIOSA</b>","sz":10,"box":[54.3,652.7,145.5,662.7],"p":134,"i":6,"sec":"val-riens-kuriosa"},{"t":"p","x":"Das Betreten des Ladens ist eine <b>Das Blatt wenden</b>- Aktion, die man nur einmal pro Szene durchführen kann. Wenn ein SC den Laden erkundet, wählt er aus, wie tief er geht, und erhält einen Zustand, der dies widerspiegelt – <t>neugierig 1</t>, <t>erkundend 2</t>, <t>eingedrungen 3</t> oder <t>in Büchern verloren 4</t> –, und seine <b>Das Blatt wenden</b>-Aktion verbessert. SC, die gemeinsam auf Erkundungstour gehen, müssen die gleiche Stufe wählen,","sz":9.5,"box":[53.9,668.2,286,765.2],"p":134,"i":7,"sec":"val-riens-kuriosa"},{"t":"p","x":"und nur einer kann die Aktion ausführen, die anderen unterstützen. Ist die Aktion erfolgreich, können alle beteiligten SC das generierte Momentum für Geschichten-Marker oder Hinweise ausgeben.","sz":9.5,"box":[309,59.9,541.4,106.9],"p":134,"i":8,"sec":"val-riens-kuriosa"},{"t":"p","x":"Sobald die Aktion abgewickelt ist, erleiden alle Charaktere der Erkundungsgruppe den Zustand <t>verirrt</t>, um 1 höher als ihr Erkundungs-Zustand. Wenn <b>Das Blatt wenden</b> erfolgreich war, können die SC <b>Sich der Gefahr stellen</b>. Ansonsten kann die SL ihnen den Zustand <t>verirrt</t> auferlegen, ohne ihnen zu erlauben, <b>Sich der Gefahr</b> zu stellen. Der Zustand, sich im Laden <t>verirrt</t> zu haben, kann wörtlich gemeint sein (die SC haben sich verirrt oder stecken in einem Teil des Ladens fest), aber auch mystischer Art sein (sie öffnen Bücher und sehen keine Schrift, fallen endlos in einen psychedelischen Raum usw.) Ein SC kann sich davon durch das Vergehen von Zeit oder mit anderen Mitteln erholen. Um den Zustand sofort zu beenden, kann ein SC eine Stärke verbrennen, die Ordnung, Struktur oder Logik repräsentiert, oder Bruch bei einem Logos-Thema markieren, das ihn auf den Boden zurückholt.","sz":9.5,"box":[309,115.6,541.2,325.1],"p":134,"i":9,"sec":"val-riens-kuriosa"},{"t":"card","x":"Magnum Opus bildet nicht aus, um das Große Werk der Alchemie zu vollbringen. Die <b>Anhänger:innen sind Ausgangsmaterial</b>, das Werk der Prozess, der sie zu etwas anderem macht.","sz":null,"k":"yellow","box":[309.3,336.1,541.7,394.8],"p":134,"i":10,"sec":"val-riens-kuriosa"},{"t":"card","x":"Die <b>Schwärzung steht für Fäulnis</b>. Zu Beginn müssen die Ausgangsmaterialien faulen und sich zersetzen. Psychologisch gesehen steht dies für die Konfrontation mit der eigenen Nichtigkeit und Verderbtheit. Wenn man sich in seinen Makeln und Bedeutungslosigkeit suhlt, kann man sich befreien <u>(Prof. Clays</u> unmögliche Aufgaben und die <u>Silo-Prüfung).</u>","sz":null,"k":"yellow","box":[309.3,404.1,541.7,512.9],"p":134,"i":11,"sec":"val-riens-kuriosa"},{"t":"card","x":"<b>Die Weißung ist Läuterung</b>. Nachdem der Widerstand der Materialien gebrochen ist, kann man sie läutern, ein Rohmaterial bleibt. In diesem Stadium muss man alle Anhaftungen und weltlichen Begierden loslassen, indem man sich „läutert“. So erreicht man inneren Frieden und Vergebung der Sünden. Expert:innen oder Ortskundige können die Abwendung vom Leben mit Gemeinschaften im Untergrund <u>(Whirlers Kommune)</u> oder dem mittelalterlichen <u>Narrenfest</u> in Verbindung bringen, das gelegentlich in Form eines großen Avantgarde-Raves gefeiert wird.","sz":null,"k":"yellow","box":[309.3,522.1,541.7,693.5],"p":134,"i":12,"sec":"val-riens-kuriosa"}],"size":[595.276,841.89]},"135":{"tab":"","blocks":[{"t":"card","x":"Die <b>Gilbung steht für das Erwachen</b>. Eine geläuterte Substanz (oder Seele) kann Licht aufnehmen. Wenn man sie dem göttlichen Licht (oder Wissen) aussetzt, leuchtet sie auf und erwacht. Die Seele erreicht das Bewusstsein (es entsteht ein Riss). Wenn das Team die <u>Katakomben</u> besucht hat, kann es das Erweckungsritual mit dieser Phase in Verbindung bringen. Andernfalls könnte es vermuten, dass der Kult einen Ort hat, an dem diese Phase stattfindet.","sz":null,"k":"yellow","box":[54.1,54.1,286.6,200.4],"p":135,"i":0,"sec":"val-riens-kuriosa"},{"t":"card","x":"Die <b>Rötung steht für Transformation</b>. Die erweckte Materie kann in eine höhere Ordnung umgewandelt werden. Eine erwachte Seele transzendiert und vereint sich mit ihrer Quelle, dem Gottkönig. <b>Selbst wenn das Team den Ofen gesehen hat, ist es schwierig, ihn mit dieser Phase in Verbindung zu bringen.</b> Hier entlarven sich die Lügen des Kults: Am Ende wartet keine Vereinigung mit dem Gottkönig, sondern nur gierige Wölf:innen, die sich an den Lämmern laben. Dies wird erst deutlich, wenn das Team den gesamten Prozess verstanden hat.","sz":null,"k":"yellow","box":[54.1,209.7,286.6,381],"p":135,"i":1,"sec":"val-riens-kuriosa"},{"t":"p","x":"Man kann die Rötung mit dem Ofen der <u>Aurora-Glashütte</u> (s. S. 105, <i>Athanor</i>) oder <u>Canseliet Manor</u> (s. S. 155, <i>Der Alchemist</i>) verbinden.","sz":10,"box":[62.4,395.7,268.2,443.2],"p":135,"i":2,"sec":"val-riens-kuriosa"},{"t":"card","x":"DIE SILO-PRÜFUNG","sz":null,"k":"yellow","box":[75.2,457.9,217.7,483.8],"p":135,"i":3,"sec":"val-riens-kuriosa"},{"t":"ro","x":"In dem feuchten, dunklen Silo kann man kaum atmen oder sehen. Ein schauerlicher lateinischer Gesang hallt durch die zylindrische Kammer. Irgendwo am Boden hört man ersticktes Weinen, Zähneklappern und ein ständiges Tröpfeln. Als sich eure Augen auf das schwache Licht einstellen, seht ihr menschliche Gestalten, die an Rohre gekettet sind. Über ihnen, auf einem Steg, drehen verhüllte Gestalten knarrende Ventile. Das Tröpfeln wird zum Rinnsal, dann zum Fluss, dann zum Schwall. Die Gesänge schwellen mit dem Wasser an und übertönen das Keuchen der Opfer, bis ein einzelner markerschütternder Schrei euren Schock durchdringt – und euch zum Handeln zwingt.","sz":9,"box":[62.4,486.2,283.8,668],"p":135,"i":4,"sec":"val-riens-kuriosa"},{"t":"p","x":"Die Silo-Prüfung ist die erste echte Prüfung des Magnum Opus, um die Eignung der Kandidat:innen zu testen. Sie zeigt ihnen ihre dunkle Seite: Verletzlichkeit und Hilflosigkeit für Lämmer oder Grausamkeit und Rücksichtslosigkeit für Wölf:innen. Sobald sie ihr Versagen akzeptieren, haben sie bestanden.","sz":9.5,"box":[53.9,677,279.9,749],"p":135,"i":5,"sec":"val-riens-kuriosa"},{"t":"p","x":"<b>Die Prüfung ist einfach: Lämmer müssen sich bereit erklären, sich von Wölf:innen opfern zu lassen, Wölf:innen müssen sich bereit erklären, Lämmer zu töten.</b> Dafür bringt der Kult die Suchenden zu einem landwirtschaftlichen Silo am Rande der Stadt. Der Boden ist abgedichtet und lässt sich über mehrere Rohrmündungen mit Wasser füllen. Während sie das Lied der Initiant:innen (s. S. 150) singen, fesseln die Wölf:innen die Lämmer an Stahlringe neben den Rohren, erklimmen eine Leiter zu einem Steg in 6 m Höhe und ziehen die Leiter hoch. Für die Lämmer besteht die Prüfung darin, keinen Widerstand zu leisten. Der Wasserfluss wird durch Ventile um den Steg herum gesteuert. Die Prüfung für die Wölf:innen besteht darin, das Wasser aufzudrehen und zuzusehen, wie die anderen ertrinken. Im sprudelnden Wasser kommt es zu Tragödien und Dramen, bei denen die Lämmer um ihr Leben schreien und die Wölf:innen zitternd ihre Moralvorstellungen über Bord werfen. Die Lämmer, die „ertrinken“, bestehen den Test, ebenso wie Wölf:innen, die nicht zusammengebrochen sind.","sz":9.5,"box":[309,62.6,541.4,322],"p":135,"i":6,"sec":"val-riens-kuriosa"},{"t":"p","x":"Vor der Prüfung verspricht Prof. Clay beiden Gruppen, dass niemandem etwas zustoßen wird und alles nur ein Test ist, der ihnen die Herrlichkeit des Gottkönigs und ihre eigene Düsterkeit und Bedeutungslosigkeit vor Augen führen soll. Tatsächlich setzt Prof. Clay, der von weiter oben zuschaut, seine Wasser-Transmutation ein, um es aus den Lungen der ertrinkenden Lämmer zu verdrängen und sie unter Wasser am Leben zu erhalten, sobald alle ihr wahres Gesicht gezeigt haben.","sz":9.5,"box":[309,330.7,538.7,440.2],"p":135,"i":7,"sec":"val-riens-kuriosa"},{"t":"p","x":"Am Ende sind die Suchenden körperlich unversehrt, wenn auch mental <t>gebrochen 3</t>. Clay verabschiedet jene, die sich nicht anketten lassen oder ihre Freunde ertrinken sehen wollten, und fordert sie auf, nie darüber zu sprechen (sie wissen, was passiert, wenn sie sich nicht daran halten). Wer den Test besteht wird <t>fanatisch 3</t> und darf sich ein paar Tage ausruhen, bevor sie als Anhänger:innen in <u>Whirlers Kommune</u> einziehen.","sz":9.5,"box":[309,448.8,539.8,558.3],"p":135,"i":8,"sec":"val-riens-kuriosa"},{"t":"card","x":"<b>Mit alchemistischem Wissen</b> kann man dieses Ritual mit der Schwärzungsphase des Magnum Opus in Verbindung bringen.","sz":null,"k":"yellow","box":[309.3,565.9,541.7,612],"p":135,"i":9,"sec":"val-riens-kuriosa"},{"t":"card","x":"<b>Die Untersuchung des wundersamen Überlebens der Lämmer</b> weist auf Prof. Clay, der mit Transmutation Wasser kontrolliert. Nachforschungen führen zu <u>1x1 der Alchemie.</u>","sz":null,"k":"yellow","box":[309.3,621.2,541.7,680.3],"p":135,"i":10,"sec":"val-riens-kuriosa"},{"t":"card","x":"<b>Nach dem Prozess verlassen die Suchenden, nun Anhänger:innen, ihren Alltag</b> und leben auf der Straße, in der Kanalisation und verlassenen U-Bahn-Tunneln. Wenn man ihnen folgt, gelangt man zu <u>Whirlers Kommune.</u>","sz":null,"k":"yellow","box":[309.3,689.2,541.7,760.6],"p":135,"i":11,"sec":"val-riens-kuriosa"}],"size":[595.276,841.89]},"136":{"tab":"","blocks":[{"t":"sh","x":"<b>DIE WACHEN DRAUSSEN</b>","sz":10,"box":[62.8,64.2,195.6,74.2],"p":136,"i":0,"sec":"val-riens-kuriosa"},{"t":"p","x":"Wie alle Initiationen ist die Silo-Prüfung für den Kult ein Ereignis, bei dem viel auf dem Spiel steht und das Teil der Mythos-Erntekette ist. Unbemerkt überwachen Agent:innen die Probe.","sz":9.5,"box":[62.4,79.8,315.5,126.8],"p":136,"i":1,"sec":"val-riens-kuriosa"},{"t":"p","x":"Nachdem alle Kandidat:innen das Silo betreten haben und die Tür versiegelt ist, umringen Wachen das Silo, um Störungen zu verhindern. Normalerweise handelt es sich um eine Handvoll <b>Initiant:innen</b> (s. S. 121), aber wenn das Team sie zuvor besiegt hat, könnte eine größere Zahl auftauchen (bei starken Teams kannst du sie durch <b>Yakuza Yōkai</b> ersetzen). Beachte, dass das Team im Silo gegen Prof. Clay und seine Wölf:innen (Suchende des Magnum Opus, S. 120) antreten muss.","sz":9.5,"box":[62.4,135.4,323.5,232.4],"p":136,"i":2,"sec":"val-riens-kuriosa"},{"t":"sh","x":"<b>WÄHREND DER PRÜFUNG</b>","sz":10,"box":[62.8,246,201.7,256],"p":136,"i":3,"sec":"val-riens-kuriosa"},{"t":"p","x":"Protagonist:innen, die den Lehren des Kults folgen oder so tun, könnten die Prüfung zu Ende führen oder zulassen wollen. Das kann die Szene in ein moralisches Dilemma verwandeln, das einige SC dazu bringen könnte, Bruch/Verblassen zu markieren oder <t>verärgert 2</t> oder <t>erschüttert 3</t> zu sein.","sz":9.5,"box":[62.4,261.6,321.8,321.1],"p":136,"i":4,"sec":"val-riens-kuriosa"},{"t":"p","x":"SC, die keine Suchenden sind, müssen die Wachen und Prof. Clay umgehen, wenn sie zusehen wollen. Aus der Ferne, z. B. per Drohne oder Hellsicht, könnte es den Astrologen auffallen, die dann Kultist:innen schicken, um den Spion zu eliminieren.","sz":9.5,"box":[62.4,329.8,317.5,389.3],"p":136,"i":5,"sec":"val-riens-kuriosa"},{"t":"p","x":"SC, die die Prüfung stören wollen, müssen die Wachen unschädlich machen oder austricksen, das Silo erreichen, sich mit Clay und den Wölf:innen anlegen und die ertrinkenden Lämmer retten, auch wenn sie sich wehren. Das könnte tragisch enden: Wenn sie Prof. Clay ablenken, könnte jemand ertrinken.","sz":9.5,"box":[62.4,397.9,320.8,469.9],"p":136,"i":6,"sec":"val-riens-kuriosa"},{"t":"threat","stars":"★★","name":"DIE SILO-PRÜFUNG","spectra":"LÄMMER UNTER WASSER 5 / DAS SILO AUFBRECHEN 6","items":["<b>Verstärkt</b>: Wenn das Silo physischen Schaden nimmt, sinkt seine Stufe um 2.","<b>Gefesselt</b>: Die Lämmer sind <t>angekettet 3</t>. Der Zustand kann sich stufenweise durch einen entgegengesetzten (z. B. <t>gesprengte Ketten</t>) verringern oder ganz entfernt werden.","<b>Ertränkungsritual</b>: Gib dem Silo als weiche Aktion <t>steigender Wasserstand 2</t> auf dem <i>Unter Wasser</i>-Spektrum der Lämmer. Wenn das Spektrum sein Maximum erreicht, erhalten alle, die nicht an die Oberfläche schwimmen können, als weiche Aktion <t>ertrinkend 3</t>. Wenn ein Lamm <t>ertrinkend 5</t> erreicht und Prof. Clay nicht beschäftigt ist, entfernt er den Ertrinkend-Zustand des Lamms.","Ein Lamm bittet ein Teammitglied, es NICHT zu retten und „Zeuge des Wunders des Gottkönigs“ zu werden (<t>zögerlich 2</t>)","Eine Störung hindert Prof. Clay daran, ein Lamm zu retten, und es ertrinkt (<b>Etwas Schreckliches geschehen lassen</b>)","Das sprudelnde Wasser dämpft die Hilfeschreie eines Lamms","Ein Lamm ringt nach Luft","Stille herrscht im Silo, als das letzte Lamm untergeht"],"box":[158.2,504.1,178.6,516.1],"p":136,"i":7,"sec":"val-riens-kuriosa"},{"t":"threat","stars":"★★★","name":"GREGORY CLAY (JÜNGER)","spectra":"VERLETZEN ODER UNSCHÄDLICH MACHEN 4 / ERSCHÖPFEN 6 / ABKEHR VOM KULT 6","items":["<b>Kadavergehorsam:</b> Wenn er die Szene betritt, gib ihm <t>fanatisch 5</t>, erneuerbar als harte Aktion.","<b>Schützende Barriere</b>: Wenn Clay oder eine Person, die er schützt, körperlichen Schaden erleidet, umhüllt er sich oder das Ziel mit einer Barriere aus Erde, Wasser oder Lehm, die Schaden um 3 reduziert. Die Barriere schmilzt dann. Für jedes Ziel erleidet er <t>angestrengt 1</t>.","Jemanden zwingen, den Mund zu halten (<t>Klappe halten 3</t>), stehen zu bleiben (<t>aufgehalten 3</t>) oder das Silo zu verlassen (<t>kontrolliert 3</t>), was ihn <t>angestrengt 1</t>","Ein oder zwei Student:innen predigen (entfernt bis zu 3 Schwächen oder Zweifel-Zustände)","Ein Wasserspektakel erschaffen und erklären, man solle die Macht des Gottkönigs sehen (entfernt bis zu 2 Schwächen oder Zweifel-Zustände, und gibt ihm selbst a<t>ngestrengt 2</t>)","Jemanden mit einer Flutwelle gegen die Silowand schleudern (<t>zermalmt 3</t>) oder durch eine Luke aus dem Silo drücken (<t>angestrengt 1</t> für jedes Ziel)","Einen Eindringling schlagen oder niederringen (<t>blaue Flecken 2</t> oder <t>festgehalten 2</t>), wobei er den Angriff manchmal mit Transmutationen verstärkt (er verbrennt eine Stärke oder Kampffähigkeit, und verleiht sich selbst <t>angestrengt 1</t>)","In einen Anfall fanatischer Wut verfallen (reduziert <t>angestrengt</t> um 1. Beachte, dass dies bei höheren Stufen effektiver ist)","Die Ärmel hochkrempeln und vom obersten Steg aus wütend nach unten blicken"],"box":[478.6,69.2,509.2,81.2],"desc":"Die Silo-Prüfung ist die Krönung der Arbeit des Professors für Magnum Opus und ein Wendepunkt für seine Anhänger:innen, den er sich nicht verderben lassen will. Während der Prüfung kennt er kein Pardon. Er wird seine Transmutationen nutzen, um sich von Eindringlingen und Saboteuren zu befreien, indem er ihre Körper wie Figuren manipuliert. Das Silo enthält Wasser und Erde, mit denen er arbeiten kann. Wenn sein Hemd nass oder zerrissen ist, sieht man das neonhelle Leuchten der Sigillen auf seinem Rücken.","p":136,"i":8,"sec":"val-riens-kuriosa"}],"size":[595.276,841.89]},"137":{"tab":"","blocks":[{"t":"h","x":"PROTAGONIST:INNEN IM MAGNUM OPUS","sz":14,"box":[80.1,69.5,270.3,83.5],"p":137,"i":0,"sec":"val-riens-kuriosa"},{"t":"p","x":"Der Eintritt einer Protagonist:in beim Magnum Opus kann narrativ sein (wie unter <u>Prof. Clay,</u> S. 128, erläutert, ist das manchmal besser, um den Kult nicht als Antagonisten darzustellen). Alternativ kann es sich um einen <t>fanatisch</t>-Zustand handeln, der SC dazu zwingt, den Lehrern des Kultes zu folgen.","sz":9,"box":[80.1,96,285.4,165],"p":137,"i":1,"sec":"val-riens-kuriosa"},{"t":"p","x":"SC, die dem Kult folgen, müssen auf dabei unter Umständen Opfer bringen und könnten ein Thema ersetzen. Unabhängig von der Art des Themas kann die Spieler:in wählen, ob sie es durch ein Thema aus dem folgenden Baukasten ersetzen möchte. Die SL könnte es als temporäres Extra-Thema geben.","sz":9,"box":[80.1,173.7,287.1,242.7],"p":137,"i":2,"sec":"val-riens-kuriosa"},{"t":"sh","x":"<b>ANHÄNGER:IN DES GOTTKÖNIGS</b>","sz":11,"box":[71.4,287.6,246.2,298.6],"p":137,"i":3,"sec":"val-riens-kuriosa"},{"t":"p","x":"<i>Mission</i>","sz":10,"box":[71.4,308.6,106.2,318.6],"p":137,"i":4,"sec":"val-riens-kuriosa"},{"t":"h","x":"IDENTITÄT","sz":10,"box":[71.4,330.1,117.7,340.1],"p":137,"i":5,"sec":"val-riens-kuriosa"},{"t":"p","x":"Ich will mich mit dem Gottkönig vereinen","sz":9,"box":[71.4,344.8,233.4,353.8],"p":137,"i":6,"sec":"val-riens-kuriosa"},{"t":"h","x":"STÄRKEN","sz":10,"box":[71.4,365.6,112.1,375.6],"p":137,"i":7,"sec":"val-riens-kuriosa"},{"t":"card","x":"<b><i>Unerschütterlicher Glaube</i></b>, <i>Nützliche chemische Rezepte</i>, <i>Stärker in Gruppen</i>, <i>Theoretische Alchemie</i>, <i>Den Anweisungen des Lehrers folgen</i>, <i>Über den Mainstream lustig machen</i>, <i>Brennende spirituelle Fragen</i>, <i>Den Respekt des Lehrers verdienen</i>, <i>Ein Exemplar von „Die Alchemie der Seele“</i>, <i>Loyal gegenüber Magnum Opus</i>","sz":null,"k":"yellow","box":[71.7,379,274.2,461.4],"p":137,"i":8,"sec":"val-riens-kuriosa"},{"t":"h","x":"SCHWÄCHEN","sz":10,"box":[71.4,473.1,128.4,483.1],"p":137,"i":9,"sec":"val-riens-kuriosa"},{"t":"card","x":"<i>Kryptische Führer:innen</i>, <i>Mein altes Leben</i>, <i>Nagender Zweifel</i>, <i>Will die Wahrheit nicht sehen</i>","sz":null,"k":"yellow","box":[71.7,486.7,257.5,508.9],"p":137,"i":10,"sec":"val-riens-kuriosa"},{"t":"h","x":"THEMENVERBESSERUNG","sz":10,"box":[71.4,520.6,178.2,530.6],"p":137,"i":11,"sec":"val-riens-kuriosa"},{"t":"p","x":"<b>Fanatisch:</b> Einmal pro Szene kannst du dir den Zustand <t>fanatisch 3</t> geben, wenn jemand versucht, dich vom Weg des Magnum Opus abzubringen.","sz":9,"box":[71.4,535.4,272.8,568.4],"p":137,"i":12,"sec":"val-riens-kuriosa"}],"size":[595.276,841.89]},"138":{"tab":"","blocks":[{"t":"card","x":"DIE AUSGRABUNG","sz":null,"k":"yellow","box":[70.3,59.9,205.3,84.4],"p":138,"i":0,"sec":"val-riens-kuriosa"},{"t":"ro","x":"Die seltsame Ausgrabungsstätte im Herzen der Stadt liegt still im Mondlicht, abgeschirmt von der Öffentlichkeit durch Glaswände, die Passant:innen einen Blick in die staubige archäologische Stätte erlauben. Ihr lasst euch von der friedlichen Fassade nicht täuschen. An den Wänden befinden sich Überwachungs- und Einbruchssensoren, die unheilvoll als Eigentum von Helix Labs gekennzeichnet sind. Wer auch immer hier das Sagen hat, weiß, dass sie oder er den Jackpot geknackt hat und ist auf Gäste vorbereitet.","sz":9,"box":[62.4,88.7,283.8,227.3],"p":138,"i":1,"sec":"val-riens-kuriosa"},{"t":"p","x":"Der Legende nach erhielt der chinesische Kaiser Wu von Xiwangmu, der Königinmutter des Westens, die Pfirsiche der Unsterblichkeit (sie hat das von Chang’e konsumierte Lebenselixier hergestellt, s. S. 133). Obwohl Wu nie Unsterblichkeit erlangte, bewahrte er dieses <b>heilige Rezept der Unsterblichkeit</b> in Form einer <b>Tafel</b> auf, die er in seinem Palast versteckte. Sein Vorgänger, Qin Shi Huang, strebte ebenfalls nach Unsterblichkeit und scheiterte. Zu seinem irdischen Vermächtnis gehörten sowohl die <b>Chinesische Mauer</b> als auch die <b>Terrakotta-Armee</b> als Wache im Jenseits.","sz":9.5,"box":[53.9,236.3,283.3,370.9],"p":138,"i":2,"sec":"val-riens-kuriosa"},{"t":"p","x":"Irgendwo unter der Altstadt haben sich all diese Mythen und Geschichten geballt und sind zu einem Schwellenort verschmolzen: einem diebessicheren Mausoleum, bewacht von den Mythen der Chinesischen Mauer und der Terrakotta-Armee, in dem sich die Tafel mit dem Geheimnis der Unsterblichkeit befindet. Kurz nach der Entdeckung übernahm <b>Helix Labs</b> die Ausgrabung unter dem Deckmantel akademischer Forschung, doch bis jetzt ist es nicht gelungen, die Mauer zu durchbrechen. Die Kunstsammlerin <u>Alona Wainwright</u> hat Einbrecher <b>Silvio Yadao</b> (Tinktur der <i>Tarnkappe</i> aus dem <i>Nibelungenlied</i>) beauftragt, die Tafel zu holen, damit sie die Mythos-Essenz ernten kann.","sz":9.5,"box":[53.9,379.4,286.3,538.9],"p":138,"i":3,"sec":"val-riens-kuriosa"},{"t":"p","x":"Je nach Beteiligung des Teams und spielerischen Vorlieben kann die Ausgrabung eine kurze Szene oder ein minutiös geplanter Raubzug sein. Neben dem Teams gibt es viele Beteiligte, die ein Interesse daran haben:","sz":9.5,"box":[53.9,547.6,281.7,594.6],"p":138,"i":4,"sec":"val-riens-kuriosa"},{"t":"p","x":"• <b>Silvio Yadao</b> will die Tafel für den Zirkel stehlen, weil Magnum Opus das Leben seiner Tochter bedroht (s. S. <u>Chinatown Festival).</u>","sz":9.5,"box":[53.9,606.1,286.3,640.6],"p":138,"i":5,"sec":"val-riens-kuriosa"},{"t":"p","x":"• Der Leiter der Geheimoperationen von <b>Helix Labs</b>, <b>Jakub Krask</b>, soll die Tafel zu schützen, aber seine Archäologin <b>Macey Reynolds</b> braucht übernatürliche Hilfe, so dass sie vielleicht Risse für den Job anwerben will. Beide sind von Helix Labs berührt und können das Legendäre wahrnehmen.","sz":9.5,"box":[53.9,649.3,277.6,721.3],"p":138,"i":6,"sec":"val-riens-kuriosa"},{"t":"p","x":"• <b>Der Zirkel</b> will die Tafel, und Silvios Fähigkeiten und Tinktur sind die beste Chance, sie zu bekommen. Wenn das Team nichts daran geändert hat, hat","sz":9.5,"box":[53.9,730,281.1,764.5],"p":138,"i":7,"sec":"val-riens-kuriosa"},{"t":"p","x":"der Zirkel Tochter Helena entführt und will sie gegen die Tafel tauschen. Mindestens eine Jünger:in und eine Gruppe Initiant:innen lauern in der Nähe und warten darauf, den Handel abzuschließen.","sz":9.5,"box":[317.5,59.9,541,106.9],"p":138,"i":8,"sec":"val-riens-kuriosa"},{"t":"p","x":"• Falls <b>Mondgeist</b> im Spiel ist, drängt ihr Mythos, die Stätte und Rezept der Unsterblichkeit zu schützen.","sz":9.5,"box":[309,115.6,535.2,137.6],"p":138,"i":9,"sec":"val-riens-kuriosa"},{"t":"sh","x":"<b>DIE AUSGRABUNGSSTÄTTE</b>","sz":10,"box":[309.4,148.4,456.7,158.4],"p":138,"i":10,"sec":"val-riens-kuriosa"},{"t":"p","x":"Bei der Ausgrabung handelt es sich um einen von Gassen umschlossenen Bereich, an dem einst ein großes Haus stand. Sie besteht hauptsächlich aus Erde, Felsen, einigen halb vergrabenen Steinmauern und alten Münzen. In der Mitte stieß das Team von Helix Labs auf einen Steinkomplex, der fehl am Platz zu sein schien. Als es sich näher heranarbeitete, sahen sich die Archäologen mit einer hohen, dicken Mauer aus Felsen, verdichteter Erde und Ziegeln konfrontiert. Schon bald stellten sie fest, dass dieser <i>Schwellenort</i> den Gesetzen des Raums und der Schwerkraft trotzt. Selbst wenn man sich in dem teilweise freigelegten Komplex abseilt, steht man vor der Großen Mauer (Bedrohungsprofil s. u.) Daher ist es nicht möglich, darüber zu springen oder zu fliegen. Die Schwerkraft verlagert sich einfach, und Eindringlinge stehen erneut vor der Mauer.","sz":9.5,"box":[309,163.9,541.4,373.4],"p":138,"i":11,"sec":"val-riens-kuriosa"},{"t":"p","x":"Wer die Mauer erklimmt oder durchbricht, findet sich in einem dunklen Raum wieder, der an das Mausoleum Kaiser Qin Shi Huangs erinnert. Der Raum steht voller Terrakotta-Soldaten, bereit, jeden zu vernichten, der versucht die Mitte zu erreichen, wo die Tafel mit dem Rezept für ewiges Leben im Mondlicht ruht.","sz":9.5,"box":[309,382.1,538.9,454.1],"p":138,"i":12,"sec":"val-riens-kuriosa"},{"t":"sh","x":"<b>NACH DEM RAUB</b>","sz":10,"box":[309.4,467.7,401.9,477.7],"p":138,"i":13,"sec":"val-riens-kuriosa"},{"t":"card","x":"<b>Wenn der Kult die Tafel hat, kann man sie zu der Kunstsammlerin <u>Alona Wainwright</u> verfolgen.</b> Dies kann mit Hilfe von Wahrsagerei geschehen, z. B. wenn man ihrer magischen Spur folgt oder mit detektivischen Fähigkeiten. Technologie kann zum Einsatz kommen, indem man einen Peilsender anbringt usw.","sz":null,"k":"yellow","box":[309.3,486.4,541.7,582.9],"p":138,"i":14,"sec":"val-riens-kuriosa"},{"t":"card","x":"<b>Sollte der Kult scheitern, wird <u>Alona Wainwright</u> versuchen, die Tafel von ihren neuen Besitzer:innen zu kaufen</b> und eine gewaltige Summe bieten (Helix Labs würde das Angebot ablehnen). Die Spur des Geldes und Gerüchte unter Schmuggler:innen und Hehler:innen würde ausreichen, um das Team zum <b>Auktionshaus Wainwright</b> zu führen.","sz":null,"k":"yellow","box":[309.3,591.8,541.7,700.7],"p":138,"i":15,"sec":"val-riens-kuriosa"}],"size":[595.276,841.89]},"139":{"tab":"","blocks":[{"t":"card","x":"Sieht man von den kulturellen Unterschieden ab, beschreibt der Text der Tafel einen Weg zur Unsterblichkeit, der bemerkenswert mit den Lehren des Magnum Opus übereinstimmt (s. S. <u>1x1 der Alchemie</u> und <u>Valériens Kuriosa).</u>","sz":null,"k":"yellow","box":[54.1,54.1,286.6,125.6],"p":139,"i":0,"sec":"val-riens-kuriosa"},{"t":"threat","stars":"★★","name":"SILVIO YADAO","spectra":"VERLETZEN ODER UNSCHÄDLICH MACHEN 3 / FAN- GEN 4 / ZUM AUFGEBEN ÜBERREDEN 4","items":["<b>Tinktur der Tarnkappe</b>: Einmal pro Szene kann Silvio, wenn er die Tinktur trägt, als weiche Aktion völlig <t>unsichtbar 5</t> werden. Man kann ihn nur noch durch Berührung aufspüren. Keine anderen Sinnes-, Überwachungs- oder Wahrnehmungsfähigkeiten registrieren ihn und können für <b>Nachforschungen</b> nicht eingesetzt werden. <b>Blicke jenseits des Nebels</b> sind auch unwirksam. Er kann das in der gleichen Szene als harte Aktion erneut durchführen.","<b>Bedroht</b>: Wenn man zum ersten Mal versucht, Silvio umzustimmen, bekommt er <t>Angst um seine Tochter 4</t>.","Problemlos Sicherheitsmaßnahmen überwinden, während das Team zurückbleibt (<b>Die Dinge richtig kompliziert machen</b>)","Jemandem etwas Wertvolles oder Wichtiges stehlen (verbrenne bis zu zwei entsprechende Stärken)","Brasilianisches Jiu Jitsu und Akrobatik nutzen, um sich aus Fesseln zu befreien (bis zu 3 Stufen einer Fesselung entfernen) oder andere zu fesseln (<t>verstrickt 2</t>, wenn er das Ziel dann allein lässt, <t>gefesselt 3</t>, wenn er die Fesselung aufrechterhält)","Gänzlich verschwinden und die Szene verlassen (<b>Ihnen etwas verweigern, das sie wollen</b>)","Den Gegenstand nehmen, hinter dem er her ist, ihn in seinen Anorak stecken und verschwinden.","Abhauen"],"box":[132.5,161.7,152.9,173.7],"desc":"Durch seine Tinktur der Tarnkappe und dem Wissen über Sicherheitssysteme ist Silvio Yadao ein Mann, der kaum zu fassen ist. Das Team kann ihn zu überreden, sich der Polizei zu stellen oder gegen den Zirkel zu helfen, aber das Leben seiner Tochter steht auf dem Spiel. Silvio kann nicht durch feste Materie oder magische Barrieren gehen, unbegrenzt die Luft anhalten oder mentalen Einflüssen widerstehen, so dass ein cleveres Team ihn fangen könnte.","p":139,"i":1,"sec":"val-riens-kuriosa"},{"t":"card","x":"<b>Jenseits des Nebels</b> sieht man die Himmlische Königinmutter des Westens über der Tafel schweben. Sie könnte einem würdigen Träger des Relikts Unsterblichkeit verleihen.","sz":null,"k":"yellow","box":[309.3,54.1,541.7,112.9],"p":139,"i":2,"sec":"val-riens-kuriosa"},{"t":"card","x":"<b>Wenn das Team über Tinkturen Bescheid weiß</b>, kann es vermuten, dass der Kult beabsichtigt, die Mythos-Essenz zu ernten.","sz":null,"k":"yellow","box":[309.3,122.1,541.7,168.5],"p":139,"i":3,"sec":"val-riens-kuriosa"},{"t":"threat","stars":"★★★","name":"DIE KOMPLEXE MAUER","spectra":"ZERTRÜMMERN – / EROSION 5 / ÜBERKLETTERN 4","items":["<b>Tränen der Meng Jiang</b>: Wenn jemand die Mauer mit Tränen tiefer Trauer benetzt, füge den emotionalen Zustand dem <i>Erosions</i>-Spektrum hinzu.","<b>Jiayuguan-Mauerstabilisator</b>: Körperlose Wesen und Teleportation können die Mauer nicht durchdringen, da ein magischer Ziegelstein absichtlich auf der Innenseite platziert ist. Diese Eigenschaft sowie die physische Immunität der Mauer (<i>Zertrümmern –</i>) enden, wenn man den Ziegelstein entfernt (Spektrum auf <i>Zertrümmern:6</i> ändern).","<b>Bao Sis vergnüglicher Signalturm</b>: Wenn sich ein Eindringling nähert, leuchtet der Signalturm auf. Erschaffe eine Bedrohung: <b>Terrakotta-Soldaten</b> (Größe 1). Der Eindringling kann <b>Heimlichkeit</b> nutzen. Wenn die Terrakotta-Soldaten den Eindringling nicht finden, erhält er <t>lachen 1</t>. Wenn man dies nach zwei Fehlalarmen ein drittes Mal auslöst, reagieren die Soldaten nicht mehr.","Ziegelsteine brechen, so dass Kletternde abrutschen (zwei Stufen von <i>Überklettern</i> entfernen, und die Kletternden erleiden <t>verstauchter Knöchel 2</t>)","Der Signalturm leuchtet auf (löse <b>Bao Sis vergnüglicher Signalturm aus</b>)","Ragt monolithisch und unheilverkündend auf"],"box":[432.4,213.3,463,225.3],"desc":"Die komplexe Mauer, die von den drei Legenden erfüllt ist, die sich um die Chinesische Mauer ranken, kann Eindringlinge aufhalten. Man kann sie beschädigen und kleine Löcher hineinmachen, aber keine physische Wucht – legendär oder alltäglich – kann sie durchschlagen. Die Legenden weisen der Mauer ungewöhnliche Schwächen zu: Tränen können sie zersetzen, ihre Kraft stamme von einem einzigen Ziegelstein, und wenn man den Signalturm irreführend einsetzt, führt das dazu, dass Bewacher selbstgefällig und unaufmerksam werden. Man kann die Mauer überklettern und sie ist anfällig für Erosion.","p":139,"i":4,"sec":"val-riens-kuriosa"}],"size":[595.276,841.89]},"140":{"tab":"","blocks":[{"t":"threat","stars":"★★","name":"TERRAKOTTA-SOLDAT","spectra":"ZERSCHLAGEN 2 / AUSTROCKNEN 1 / GEIST BEEIN- FLUSSEN –","items":["<b>Wächter für das Jenseits</b>: Mythos-Kräfte können Terrakotta-Soldaten nicht direkt beeinflussen","Angriff mit Metallwaffen (<t>aufgeschlitzt 2</t>)","Die Reihen schließen und lauschen (sie geben sich selbst <t>aufmerksam</t>. Die Stufe entspricht ihrem Größenfaktor und kann nicht darüber hinaus gehen.)","Stillstehen, staubig und doch lebendig"],"box":[173.3,57.5,193.7,69.5],"desc":"Innerhalb des Komplexes gibt es tausende Terrakotta- Soldaten (Größe 4), und Dutzende (Größe 2) können sich gleichzeitig mit einem Eindringling anlegen. Die Tonfiguren sollten ihren Kaiser vor bösen Geistern im Jenseits schützen. Sie sind immun gegen Mythos- Kräfte. Man muss sie mit gewöhnlichen Mitteln oder mit indirekten Mythos-Kräften zerschlagen.","p":140,"i":0,"sec":"val-riens-kuriosa"},{"t":"threat","stars":"★★★","name":"HELIX LABS-BLACK OPS","spectra":"VERLETZEN ODER UNSCHÄDLICH MACHEN 4 / AUS- RÜSTUNG AUFBRAUCHEN 4","items":["<b>Kollektiv</b>: Dieses Kollektiv hat mehrere Mitglieder und Größenfaktor 2.","<b>Fortschrittliche Technologie</b>: Wenn man eine Aktion gegen Helix Labs‘ Black Ops-Ausrüstung und -Waffen macht, kann man keine Stärken aus Logos-Themen nutzen.","<b>Automatische Zündung</b>: Wenn sie die Szene betreten, kann die SL als Einmischung zwei harte Bedrohungen nutzen, bei aktiver Ausrüstung.","<b>Spielentscheidend</b>: Als harter Aktion enthüllen die Helix Labs-Black Ops ein spezielles Stück Technologie, das „kriegsentscheidend“ ist (<b>Die Dinge richtig kompliziert machen</b>), woraufhin sie eine harte Aktion mit Stufe-6-Effekt ausführen können.","Ein Gerät aktivieren: » Kraftfeldgenerator (<t>abgeschirmt 3</t>) » Multispektralscanner (<t>aufmerksam 2</t> oder spezifisches Wissen über Bedrohungen in der Nähe, insbesondere Risse) » Biomaterie-Pflaster (entfernt bis zu 2 Stufen eines medizinischen Zustands) » Ion-9-Sturmgewehr (Gegner: <t>durchlöchert 3</t> oder <t>niedergehalten 3</t>) » Netze verschießende Spinnen (Gegner: <t>gefesselt 3</t>) » Laserpointer (<t>in die Enge getrieben 3</t>)","Geräuschlos um ein Ziel herum positionieren"],"box":[182.6,363.3,213.2,375.3],"p":140,"i":1,"sec":"val-riens-kuriosa"},{"t":"h","x":"SCHICHT 3:","sz":14,"box":[309,61.9,377.2,75.9],"p":140,"i":2,"skip":true,"sec":"schicht-3-schatten-der-wahrheit"},{"t":"h","x":"SCHATTEN DER WAHRHEIT","sz":21,"box":[309,85.5,539.7,106.5],"p":140,"i":3,"skip":true},{"t":"h","x":"WHIRLERS KOMMUNE","sz":16,"box":[334.8,120.8,481.7,136.8],"p":140,"i":4,"skip":true,"sec":"whirlers-kommune"},{"t":"ro","x":"Hinter der Biegung des Tunnels stoßt ihr unerwartet auf eine stillgelegte U-Bahn- Station. Die Fliesen, die einst die Wände zierten, sind rissig und schmutzig, aber der Ort ist alles andere als verlassen. Bahnsteig und Gleise sind durch Bretter, Paletten und Bettlaken zu einem Häuserkomplex geworden. Bunte Girlanden spannen sich von einer Seite zur anderen, schwach beleuchtet von Müllfeuern, Fässern und hohen Kerzen, die überall im Bahnhof stehen. Schmutzige, ungepflegte Schemen huschen zwischen Zelten und Graffiti mit seltsamen Zeichen umher: zentrische Kreise, Dreiecke und Quadrate in Schwarz, Weiß, Gelb und Rot. Im Zentrum, über einem improvisierten Altar und von Flammen umhüllt, ist ein Wandgemälde des Gottkönigs, einer schattenhaften, gekrönten Gestalt, die ewiges Leben in Form eines leuchtenden Kelches anbietet.","sz":9,"box":[317.5,139.2,538.9,364.2],"p":140,"i":5,"sec":"whirlers-kommune"},{"t":"p","x":"Die Suchenden, die die <u>Silo-Prüfung</u> bestehen, werden Anhänger:innen und gehen zum nächsten Schritt über: ein Leben in Armut und Askese bei der spirituellen Führerin <b>Whirler</b>, das sie von sterblichen Anhaftungen befreien soll. Sie packen das Nötigste zusammen und machen sich auf den Weg zur Kommune der Mystikerin, in den Tunneln unter der Altstadt.","sz":9.5,"box":[309,373.2,540.2,457.7],"p":140,"i":6,"sec":"whirlers-kommune"},{"t":"p","x":"Wenn Peter Hill, Sloane Martinez, Jiahao „Jaja“ Zhang (s. S. 125) oder andere Nebencharaktere dem Kult beigetreten und nun hier sind, bietet sich Gelegenheit für zwischenmenschliche Dramen (wenn das Team sie aufzuhalten versucht) oder traurige Enthüllungen (wenn die SC einfach entdecken, dass sie weg sind). Wenn SC versuchen, Anhänger:innen davon abzubringen, in die Kommune zu ziehen, sind sie schwieriger zu beeinflussen als zuvor. Verwende das Bedrohungsprofil Anhänger:innen (s. S. 120).","sz":9.5,"box":[309,466.4,541.1,588.4],"p":140,"i":7,"sec":"whirlers-kommune"},{"t":"sh","x":"<b>DIE KOMMUNE</b>","sz":10,"box":[309.4,602,390,612],"p":140,"i":8,"sec":"whirlers-kommune"},{"t":"p","x":"Die Kommune ist ein Hüttendorf in einer stillgelegten U-Bahn-Station. Der Weg ist mit Kultsymbolen markiert und verkleidete Mitglieder:innen achten auf Eindringlinge. Um den Weg dorthin ohne Führung zu finden, bedarf es Wahrsagerei, Beschattungs- oder Fährtenlesekunst oder Kontakten zum Undertrash (den unterirdischen Territorien unter der Stadt, die voller Ausgestoßener und Monstrositäten sind). Wenn der Kult eine Bedrohung voraussieht, geht er mit voller Kraft dagegen vor <u>(Schadensbegrenzung des Zirkels).</u>","sz":9.5,"box":[309,617.5,541.1,739.5],"p":140,"i":9,"sec":"whirlers-kommune"}],"size":[595.276,841.89]},"141":{"tab":"","blocks":[{"t":"sh","x":"<b>WHIRLER</b>","sz":10,"box":[54.3,62.8,106.6,72.8],"p":141,"i":0,"sec":"whirlers-kommune"},{"t":"p","x":"Whirler begrüßt alle Neuankömmlinge, ob Anhänger:in oder nicht (sie glaubt, dass der Kult Bedrohungen vorhersehen und sich mit ihnen befassen wird, bevor sie in die Kommune eindringen). Die zierliche Mönchin – früher Versicherungsvertreterin und später Selbsthilfe-Influencerin – schreitet in orangefarbenen Gewändern, barfuß und mit glatt rasiertem Kopf durch das Zeltlager. Sie spricht leise, lächelt herzlich und hat aufrichtig Mitleid mit den Anhänger:innen, die ihr Leben zurücklassen mussten, betont aber die Notwendigkeit einer vollständigen Läuterung, um sich dem Gottkönig zu öffnen. Whirler ist eine Jüngerin im Besitz der <b>Krishna-Tinktur</b> (hinduistische Gottheit des Mitgefühls, der Zärtlichkeit und der Liebe), die sie nutzt, um die Anhänger:innen zu trösten, zu beruhigen und mit innerem Frieden und Gelassenheit zu erfüllen.","sz":9.5,"box":[53.9,78.3,286,275.3],"p":141,"i":1,"sec":"whirlers-kommune"},{"t":"p","x":"Hinter der Guru-Fassade ist Whirler mehr interessiert, die Retterin zu spielen, als den spirituellen Weg bis zum Ende zu gehen oder anderen zu helfen. Sie führt Anhänger:innen durch eine echte Transformation, aber nur, weil dies für den Kult, den sie unterstützt, entscheidend ist. Whirler fühlt sich dort wohl, wo sie ist, und will vor allem die Kommune schützen.","sz":9.5,"box":[53.9,284,282.8,368.5],"p":141,"i":2,"sec":"whirlers-kommune"},{"t":"card","x":"<b>Mit alchemistischem Wissen</b> kann man die Kommune mit der Weißungsstufe des alchemistischen Magnum Opus in Verbindung bringen. Wenn man den Weg des Magnum Opus kennt, kann man daraus schließen, dass am Ende dieser Periode (mit dem <u>Narrenfest)</u> ein weiteres Weiheritual stattfinden wird.","sz":null,"k":"yellow","box":[54.1,377.3,286.6,473.5],"p":141,"i":3,"sec":"whirlers-kommune"},{"t":"card","x":"<b>Whirler sagt, das nächste Initiationsritual (das <u>Narrenfest)</u> werde für die Anhänger:innen „das Ende des alten Lebens in der Stadt“ sein.</b> Undercover-SC haben das Gefühl, die Anhänger:innen während des Rituals genau im Auge behalten zu müssen.","sz":null,"k":"yellow","box":[54.1,482.7,286.6,566.5],"p":141,"i":4,"sec":"whirlers-kommune"},{"t":"card","x":"Neben dem Kochen und dem Studium von „Alchemie der Seele“ (s. S. <u>1x1 der Alchemie)</u> gehören zu den Aktivitäten in der Kommune die Vorbereitungen für eine Zeremonie: <b>Die Bewohner:innen nähen Kostüme, insbesondere Tierkostüme</b>, sowie Banner, Luftschlangen, Gebetsfahnen usw.","sz":null,"k":"yellow","box":[54.1,575.7,286.6,671.9],"p":141,"i":5,"sec":"whirlers-kommune"},{"t":"card","x":"<b>Ein- bis zweimal pro Woche tauchen vermummte Initiant:innen in Straßenkleidung auf</b>, um Whirler Botschaften des Zirkels zu übermitteln und ihren Bericht entgegenzunehmen. Man kann ihnen zu <u>Alona Wainwright</u> oder in die <u>Katakomben</u> folgen. <b>Whirler teilt so mit, welches Kostüm die einzelnen Anhänger:innen auf dem <u>Narrenfest</u> tragen werden.</b>","sz":null,"k":"yellow","box":[54.1,681.1,286.6,790],"p":141,"i":6,"sec":"whirlers-kommune"},{"t":"card","x":"<b>Hinter der Ziegelmauer mit dem Wandgemälde des Gottkönigs befindet sich ein weiterer U-Bahn-Tunnel.</b> Er führt in eine große Höhle, dem Schauplatz des <u>Narrenfests.</u> Am Fuße der Wand befindet sich ein Flickwerk aus Ziegeln und Mörtel, ein mehrmals benutzter und wieder verschlossener Eingang.","sz":null,"k":"yellow","box":[309.3,54.1,541.7,150.6],"p":141,"i":7,"sec":"whirlers-kommune"},{"t":"sh","x":"<b>DIE WEISSUNG: LÄUTERUNG VON ALLEN ANHAFTUNGEN</b>","sz":10,"box":[309.4,164.8,531.5,186.8],"p":141,"i":8,"sec":"whirlers-kommune"},{"t":"p","x":"Das Leben in der Kommune dient als zweite Stufe des Magnum Opus, der <b>Weißung</b>, um sie auf das Erwachen aus dem Mythos vorzubereiten.","sz":9.5,"box":[309,192.4,540.8,226.9],"p":141,"i":9,"sec":"whirlers-kommune"},{"t":"p","x":"SC, die den Weg des Kults einschlagen und der Kommune beitreten wollen, müssen vorübergehend ihre Prägenden Beziehungen, Routinen und möglicherweise Missionen und Besitztümer aufgeben, was sie unter Umständen <b>Vor eine Wahl stellt</b>. Du solltest es ihnen nicht leicht machen, sondern <b>Die Dinge kompliziert machen</b> und dafür sorgen, dass ihre Logos-Themen Probleme verursachen: Jemand steckt ihnen eine (wahre oder falsche) Nachricht mit Neuigkeiten über ihr altes Leben zu (vielleicht mit Hilfe anderer SC).","sz":9.5,"box":[309,235.6,537.6,357.6],"p":141,"i":10,"sec":"whirlers-kommune"},{"t":"p","x":"In der Kommune können die SC während eines <b>Zusammenschnitts in der Drehpause</b> ihren Themen keine <i>Aufmerksamkeit</i> schenken. Es ist möglich sich wegzuschleichen, aber <t>fanatisch</t>-Zustände, die von der Silo-Prüfung übrig sind, verhindern die Aktion. Wenn man Anhänger:innen dabei ertappt, fliegt sie unter Umständen aus der Kommune und müssen diesen Weg ganz aufgeben (<b>Sie vor eine Wahl stellen</b>).","sz":9.5,"box":[309,366.2,538.9,463.3],"p":141,"i":11,"sec":"whirlers-kommune"},{"t":"p","x":"Anhänger:innen können Wochen in der Kommune verbringen, bis ihnen ihr altes Leben wie ein Traum vorkommt. Erst wenn Whirler genügend Anhänger:innen für den nächsten Schritt hat, gibt sie das Zeichen, mit den Vorbereitungen für das <u>Narrenfest</u> zu beginnen.","sz":9.5,"box":[309,471.9,540.2,531.4],"p":141,"i":12,"sec":"whirlers-kommune"},{"t":"p","x":"Am Tag des Festes weist Whirler die Anhänger:innen an, die mit Wandmalereien bedeckte Ziegelmauer zu entfernen, die die Öffnung zu einem U-Bahn-Tunnel verdeckt, der sie zum Ritual führen wird. Sie warnt, dass <b>während des <u>Narrenfests</u> ein Führer kommen wird, um sie zum Gottkönig zu geleiten. Dies sei die einzige Chance, und dafür müssten sie die Stadt für immer verlassen.</b> Dann ziehen sie ihre Kostüme an und schreiten in den dunklen Tunnel.","sz":9.5,"box":[309,540.1,539.5,649.6],"p":141,"i":13,"sec":"whirlers-kommune"}],"size":[595.276,841.89]},"142":{"tab":"","blocks":[{"t":"sh","x":"<b>WHIRLERS WARME WORTE</b>","sz":10,"box":[54.3,62.8,202,72.8],"p":142,"i":0,"sec":"whirlers-kommune"},{"t":"p","x":"• „Deine Augen sind offen, aber du sehnst dich immer noch danach, einzuschlafen. Lass nicht zu, dass es die ganze Arbeit zunichtemacht.“ • „Was du hinter dir gelassen hast, hat nicht gereicht, um dich glücklich zu machen, die Fragen zu beantworten oder dein Schicksal zu ändern. Der einzige Weg zur Wahrheit ist, alles loszulassen.“ • „Man hat euch gelehrt, die Leere zu fürchten, aber die Leere ist das Fundament der Erleuchtung. Wer kein leeres Glas wird, kann nie das Licht aufnehmen.“ • „Ich kann nicht beschreiben, was sich offenbart, wenn ihr euch mit dem Gottkönig vereinigt. Aber es wird eure kühnsten Träume übersteigen. Alles, was ihr begehrt, wird eures sei, ohne Kampf oder Konflikt. Im Augenblick ist der Wunsch das Hindernis.“","sz":9.5,"box":[53.9,75.5,282.5,272.5],"p":142,"i":1,"sec":"whirlers-kommune"},{"t":"threat","stars":"★★★","name":"WHIRLER","spectra":"VERLETZEN ODER UNSCHÄDLICH MACHEN 1 / EMO- TIONAL UNSCHÄDLICH MACHEN 4 / ABKEHR VOM KULT 6","items":["<b>Kadavergehorsam:</b> Wenn sie die Szene betritt, gib ihr <t>fanatisch 5</t>, erneuerbar als harte Aktion.","<b>Liebe und Frieden</b>: Bei aggressiven Handlungen gegen Whirler, nimmst du zuerst <t>Liebe und Frieden 5</t>.","<b>Diamant-Mantra</b>: Wenn Whirler einen Zustand der emotionalen oder mentalen Beeinflussung erhält, reduziert sich seine Stufe um 2.","<b>Leibwächter:innen</b>: Wenn Whirler einen Zustand erhält, vor dem Leibwächter:innen schützen können, nehmen diese den Zustand stattdessen (verwende <b>Anhänger:innen</b>, S. 120).","Jemanden ermutigen, weltliche Bindungen aufzugeben, um im Magnum Opus voranzukommen (<t>in Versuchung 3</t>, <t>fanatisch 3</t> oder <b>Die Dinge richtig kompliziert machen</b>, und zwar so, das es die Spieler:in einlädt, Bruch zu markieren)","Jemanden mit guten Wünschen und guten Absichten füttern (<t>Liebe und Frieden 5</t>)","Gefolgsleute zu Hilfe rufen (erstellen eine neue Bedrohung: <b>Anhänger:innen</b>, S. 120)","Die Hand einer Person nehmen und mitfühlend lächeln"],"box":[111.1,296.5,141.7,308.5],"desc":"Trotz oder gerade wegen des ruhigen Wesens ist Whirler so gefährlich wie die Mitstreiter:innen im Kult. Sie stellt keine Bedrohung für die Sicherheit des Teams dar, kann aber eine für das Privatleben sein.<br><br>Whirlers Ausstrahlung übernatürlicher Ruhe und Unerschütterlichkeit rührt von der Krishna-Tinktur her, die sie in einem Fläschchen an einer Kette um den Hals trägt. Ohne sie ist sie nur ein weiterer Möchtegern-Guru. Der Trick ist, die Tinktur zu entfernen, bevor sie einen mit guten Absichten erfüllt.","p":142,"i":2,"sec":"whirlers-kommune"},{"t":"card","x":"DAS NARRENFEST","sz":null,"k":"yellow","box":[322.8,60.2,472.6,84.7],"p":142,"i":3,"sec":"whirlers-kommune"},{"t":"ro","x":"Seltsame, schräge Musik, eine wilde Mischung aus modernen Beats und mittelalterlichen Melodien, hallt aus der Tiefe empor. Dort, in einer riesigen Naturhöhle, sehr ihr Tausende von Raver:innen, die tanzen, umherspringen und in Tiermasken und Alltagsklamotten, in Uniformen und Arbeitskleidung herumalbern. Irgendwo in diesem Treiben verbirgt sich derjenige, der euch weiter führen kann, dorthin, wo sich alle Geheimnisse erschließen. Aber ihr fragt euch, ob ihr sie werdet finden können und wenn ja, ob ihr bereit seid, den letzten Schritt zu tun.","sz":9,"box":[317.5,87.3,538.9,236.7],"p":142,"i":4,"sec":"whirlers-kommune"},{"t":"p","x":"Das Narrenfest ist die zweite Initiation, das die Befreiung der Anhänger:innen vom alten Leben, der Mainstream-Gesellschaft und traditionellen Vorstellungen von Moral darstellt. Es ist der Höhepunkt der zweiten Phase des Magnum Opus: die <b>Weißung</b> oder Läuterung.","sz":9.5,"box":[309,245.7,533,317.7],"p":142,"i":5,"sec":"whirlers-kommune"},{"t":"p","x":"<b>Wie die <u>Silo-Prüfung</u> ist auch diese einfach: Die Anhänger:innen müssen sich entscheiden ihrer Führer:in zu folgen und ihr Leben in der Stadt aufzugeben, wissend, dass sie nie wieder zurückkehren können (zumindest nicht so, wie sie jetzt sind).</b>","sz":9.5,"box":[309,326.5,541.3,386],"p":142,"i":6,"sec":"whirlers-kommune"},{"t":"p","x":"Der Übergangsritus findet während eines vom Kult organisierten unterirdischen Raves statt, bei dem Tausende Menschen in einer riesigen Höhle tanzen und trinken, ohne zu wissen, dass sie Teil des Rituals sind. Die Teilnehmer:innen tragen Masken in Form von Tierköpfen – Esel, Füchse, Krähen, Fische und Schildkröten – und Kostüme, die die Alltagskleidung diverser Stadtbewohner:innen karikieren – Polizist:innen, Richter:innen, Bankangestellte usw. – und so die sozialen Rollen und Normalität ins Lächerliche ziehen.","sz":9.5,"box":[309,394.5,540.5,516.5],"p":142,"i":7,"sec":"whirlers-kommune"},{"t":"p","x":"Die Anhänger:innen des Magnum-Opus (SC wie NSC) nehmen teil, verzichten aber auf den Rausch, bis sie inmitten des Chaos jemand aufmerksam anstarrt und ihnen zuwinkt (auch diese Person trägt einen Tierkopf). Dies ist <b>die Führer:in</b>, deren Erscheinen den Augenblick der Wahrheit bedeutet.","sz":9.5,"box":[309,525.2,534.4,597.2],"p":142,"i":8,"sec":"whirlers-kommune"},{"t":"p","x":"Die Führer:in ist eine Jünger:in, die die Transmutation der Erde gemeistert hat. Wenn die Anhänger:innen folgen, öffnet sie ihnen einen engen Bergwerksstollen, indem sie die Erde beiseite schiebt und hinter ihnen versiegelt. Der Stollen ist dunkel, und die Anhänger:innen müssen sich lange entlang tasten, bis er an einer Steintür endet, in die die Geheimnisse des Magnum Opus eingraviert sind: im Kreis geschriebene Dreiecke und Quadrate, Formeln und alchemistische Symbole. Die Erde verschiebt sich erneut und versiegelt den Tunnel hinter den Anhänger:innen.","sz":9.5,"box":[309,605.8,538.8,740.3],"p":142,"i":9,"sec":"whirlers-kommune"}],"size":[595.276,841.89]},"143":{"tab":"","blocks":[{"t":"p","x":"Stundenlang müssen sie dasitzen und über ihren Übergang nachdenken. Während des Aufenthalts in der Kammer scheint die Erde unter ihnen zu beben – ohne dass die Anhänger:innen es wissen, verlegen die Jünger:innen die Kammer in die <u>Katakomben,</u> ganz auf der anderen Seite der Stadt und tiefer unter der Erde.","sz":9.5,"box":[53.9,59.9,286.3,131.9],"p":143,"i":0,"sec":"whirlers-kommune"},{"t":"p","x":"Dieses Ritual dient dazu, die Anhänger:innen zu beeindrucken und zu erschrecken und als Sicherheitsvorkehrung, um zu verhindern, dass Unbefugte die <u>Katakomben</u> finden. Wenn alle Gefolgsleute weggezaubert sind, endet der Rave und die Feiernden räumen die Höhle. Alle Anhänger:innen, die ihrer Führer:in nicht gefolgt sind, hören nie wieder etwas vom Kult.","sz":9.5,"box":[53.9,140.6,285,225.1],"p":143,"i":1,"sec":"whirlers-kommune"},{"t":"sh","x":"<b>DIE PARTY SPRENGEN</b>","sz":10,"box":[54.3,238.7,174.9,248.7],"p":143,"i":2,"sec":"whirlers-kommune"},{"t":"p","x":"SC, die keine Anhänger:innen sind, können den Rave ausfindig machen, indem sie der Prozession der Anhänger:innen von <u>Whirlers Kommune</u> aus folgen oder die Gerüchte mit den Hinweisen in <u>Valériens Kuriosa</u> vergleichen.","sz":9.5,"box":[53.9,254.3,280.2,313.8],"p":143,"i":3,"sec":"whirlers-kommune"},{"t":"p","x":"Ein Angriff ist unpraktisch, da überall Kultist:innen versammelt sind, <b>Whirlers</b> Anwesenheit beruhigend wirkt, <b>Talia Al-Bahar</b> in Scharfschützenposition ist und die <b>Yakuza-Yōkai</b> sich unter die Menge gemischt haben. Selbst ein Einsturz der Höhle ist bei Jünger:innen, die sich mit Transmutation der Erde auskennen, unwahrscheinlich, ganz zu schweigen von Tausenden mehr oder weniger unschuldigen Raver:innen.","sz":9.5,"box":[53.9,322.4,280.6,419.4],"p":143,"i":4,"sec":"whirlers-kommune"},{"t":"p","x":"Stattdessen ist die Szene eine großartige Gelegenheit, die Versammlung zu infiltrieren (kostümiert!), mehr über den Kult zu erfahren und zu versuchen, die Anhänger:innen zu retten, an denen dem Team liegt – und das alles vor dem Hintergrund der Feierlichkeiten.","sz":9.5,"box":[53.9,428.1,284.1,487.6],"p":143,"i":5,"sec":"whirlers-kommune"},{"t":"p","x":"• Es ist schwierig, die Anhänger:innen inmitten des <i>Kostümchaos</i> und der <i>Betrunkenen Menge</i> ausfindig zu machen, aber genau diese Bedingungen machen <b>Heimlichkeit</b> einfacher.","sz":9.5,"box":[53.9,499.1,277.2,546.2],"p":143,"i":6,"sec":"whirlers-kommune"},{"t":"p","x":"• Die Führer:innen (Jünger:innen), die den einzelnen Anhänger:innen zugewiesen sind, öffnen den Tunnel nicht für andere, es sei denn, sie verwechseln sie. So gäbe es ein Expressticket in die <u>Katakomben.</u>","sz":9.5,"box":[53.9,554.8,285.8,601.8],"p":143,"i":7,"sec":"whirlers-kommune"},{"t":"card","x":"<b>Mit alchemistischem Wissen</b> kann man dieses Ritual mit der Weißungsstufe des alchemistischen Magnum Opus in Verbindung bringen.","sz":null,"k":"yellow","box":[54.1,606.2,286.6,652.6],"p":143,"i":8,"sec":"whirlers-kommune"},{"t":"p","x":"<b>Schwärzung Weißung</b>","sz":10,"box":[93.8,671.5,255,681.5],"p":143,"i":9,"sec":"whirlers-kommune"},{"t":"p","x":"<i>Wenn mein</i> <b><i>Körper</i></b> <i>verrottet, bin</i> <b><i>Quecksilber</i></b> <i>wäscht</i>","sz":8,"box":[61.8,690.6,272,698.6],"p":143,"i":10,"sec":"whirlers-kommune"},{"t":"p","x":"<i>ich erlöst meinen Geist</i>","sz":8,"box":[100.9,702.6,260.2,710.6],"p":143,"i":11,"sec":"whirlers-kommune"},{"t":"p","x":"<b>Salz</b> oder <b>Körper Quecksilber</b>","sz":8,"box":[87.1,718.6,259.8,726.6],"p":143,"i":12,"sec":"whirlers-kommune"},{"t":"card","x":"Eine Schmuggler:in könnte annehmen, dass das Fest als Tarnung für die Verschleppung der Anhänger:innen in ein Versteck oder Zufluchtsort dient. Die <b>Verfolgung von Anhänger:innen</b> wird zeigen, dass eine Führer:in sie in einen Tunnel führt. Wenn man eine <b>Führer:in identifiziert</b> und ihr folgt, sieht man, dass sie nach einem bestimmten Kostüm sucht.","sz":null,"k":"yellow","box":[309.3,54.1,541.7,163],"p":143,"i":13,"sec":"whirlers-kommune"},{"t":"card","x":"Wenn man all das mit den Lehren des Magnum Opus in Verbindung bringt, <b>kann man daraus schließen, dass der nächste Schritt die Gilbung</b> oder das Erwecken ist. Der letzte Schritt, die Rötung oder Transformation, wird die vollständige Vereinigung mit dem Gottkönig sein.","sz":null,"k":"yellow","box":[309.3,172.2,541.7,256],"p":143,"i":14,"sec":"whirlers-kommune"},{"t":"sh","x":"<b>DAS RÄTSEL DER INITIANT:INNEN</b>","sz":10,"box":[309.4,268,497.1,278],"p":143,"i":15,"sec":"whirlers-kommune"},{"t":"p","x":"Bevor die Kammer ihre endgültige Position in den <u>Katakomben</u> erreicht, müssen Anhänger:innen (oder Eindringlinge) als letzte Sicherheitsmaßnahme das Rätsel der Initiant:innen lösen: Es gilt, eine Folge von vier alchemistischen Symbolen zu vervollständigen, die den Versen des <b>Liedes der Initiant:innen</b> aus dem Buch „Die Alchemie der Seele“ (s. S. 150) entsprechen. Einige der alchemistischen Zeichen erscheinen auf der Steintür als leuchtende Siegel. <b>Anhänger:innen müssen die restlichen Symbole auf die Tür malen.</b>","sz":9.5,"box":[309,283.6,540.2,418.2],"p":143,"i":16,"sec":"whirlers-kommune"},{"t":"p","x":"Die richtige Reihenfolge entspricht den Wörtern „Körper“, „Quecksilber<b>“</b>, „Sonne“ und „Feuer“, die in den Versen erscheinen, die der Schwärzung, Weißung, Gilbung und Rötung entsprechen (s. S. Symbole in der folgenden Tabelle). In der einfachsten Version des Rätsels fehlt nur noch das letzte Symbol (Feuer). Du kannst es schwieriger machen, indem du Symbole entfernst, oder den Einsatz erhöhen, indem du nur einen Versuch zugestehst.","sz":9.5,"box":[309,426.7,538.2,536.2],"p":143,"i":17,"sec":"whirlers-kommune"},{"t":"p","x":"Ein SC, der die Lehre ernsthaft verfolgt hat, wird die vier Stufen, das Lied der Initiant:innen und die alchemistischen Elementsymbole auswendig kennen.","sz":9.5,"box":[309,544.9,535.2,579.4],"p":143,"i":18,"sec":"whirlers-kommune"},{"t":"p","x":"SC, die die Antwort nicht kennen, können <b>Nachforschungen</b> anstellen, wenn sie über das erforderliche Wissen oder eine Möglichkeit verfügen, Zugang dazu zu erlangen. <i>Ein Exemplar von „Die Alchemie der Seele“</i> ist in dieser Situation nützlich und kann nach deinem Ermessen einige kostenlose Hinweise liefern.","sz":9.5,"box":[309,588.1,535.2,660.1],"p":143,"i":19,"sec":"whirlers-kommune"},{"t":"p","x":"<b>Gilbung Rötung</b>","sz":10,"box":[343.4,671.5,491.7,681.5],"p":143,"i":20,"sec":"whirlers-kommune"},{"t":"p","x":"<i>Meine</i> <b><i>Seele</i></b> <i>leuchtet Ich brenne, um mich mit deinem</i>","sz":8,"box":[321.4,690.6,532.9,698.6],"p":143,"i":21,"sec":"whirlers-kommune"},{"t":"p","x":"<i>wie die</i> <b><i>Sonne</i></b> <i>heiligen</i> <b>Feuer</b> <i>zu vereinen</i>","sz":8,"box":[333.6,702.6,522.8,710.6],"p":143,"i":22,"sec":"whirlers-kommune"},{"t":"p","x":"<b>Sonne/Schwefel</b> oder <b>Seele Feuer</b>","sz":8,"box":[308.5,718.6,488.5,726.6],"p":143,"i":23,"sec":"whirlers-kommune"}],"size":[595.276,841.89]},"144":{"tab":"","blocks":[{"t":"card","x":"Während die Anhänger:in das Rätsel lösen, ist hinter der Tür gedämpft das <b>Lied der Initiant:innen</b> zu hören.","sz":null,"k":"yellow","box":[54.1,54.1,286.6,100.5],"p":144,"i":0,"sec":"whirlers-kommune"},{"t":"card","x":"Das Rätsel ist wörtlich gemeint, nicht symbolisch. Die Zeichen stehen für Worte.","sz":null,"k":"yellow","box":[54.1,109.7,286.6,143.4],"p":144,"i":1,"sec":"whirlers-kommune"},{"t":"card","x":"Das alchemistische Element, das den Körper repräsentiert, ist Salz.","sz":null,"k":"yellow","box":[54.1,152.6,286.6,186.6],"p":144,"i":2,"sec":"whirlers-kommune"},{"t":"p","x":"Wenn die Person in der Kammer das Rätsel löst, bewegt diese sich in ihre endgültige Position. Eine Jünger:in mit Kerze in der Hand öffnet die Tür und führt die Anhänger:in in die <u>Katakomben.</u> Sie erhält als <b>Initiant:in</b> ein gelb-braunes Gewand (<t>fanatisch 4</t>).","sz":9.5,"box":[53.9,200.9,286.3,260.5],"p":144,"i":3,"sec":"whirlers-kommune"},{"t":"p","x":"Wer versagt, wird als Eindringling betrachtet, und entweder wird die Kammer zum Einsturz gebracht oder man lässt sie verhungern, gefangen unter Hunderten von Metern Erde (<t>lebendig begraben 5</t>). Erschwerend kommt hinzu, dass die <i>Siegel an der Tür</i> magischen Transport oder Körperlosigkeit behindern.","sz":9.5,"box":[53.9,269.1,283,341.1],"p":144,"i":4,"sec":"whirlers-kommune"},{"t":"h","x":"ALONA WAINWRIGHT","sz":16,"box":[79.7,357.8,219,373.8],"p":144,"i":5,"skip":true,"sec":"alona-wainwright"},{"t":"ro","x":"Es regnet in Strömen, als ihr neben einem goldenen Schild mit der Aufschrift AUK- TIONSHAUS WAINWRIGHT vor dem tadellos restaurierten Haus anhaltet. Irgendwie überrascht es euch nicht, dass alles auf ein Auktionshaus hinausläuft. Die Begehrlichkeit, das Verlangen nach Besitz hängt über dem Ort wie fauliger Atem. Hier versieht man das Alte und Unbezahlbare mit einem Preisschild und verkauft es an den Meistbietenden. Es ist zu bezweifeln, ob Leute, die sich danach sehnen museumswürdige Schätze zu besitzen, es dabei bewenden lassen. Sicher verspüren sie den Drang, mit sakraleren Gütern zu handeln.","sz":9,"box":[62.4,376.1,283.8,536.3],"p":144,"i":6,"sec":"alona-wainwright"},{"t":"p","x":"Wie ihre Mitstreiter im Zirkel ist <b>Alona Wainwright</b> durch und durch eine Wölfin des Magnum Opus: Für sie ist die Verehrung des Gottkönigs ein Weg zu unvergleichlicher Macht. Als eine der bekanntesten Kunstsammler:innen und -händler:innen der Stadt kam sie vor Jahren in Kontakt mit dem Kult, nachdem sie über ein Manuskript von „Die Alchemie der Seele“ gestolpert war und es als Fälschung identifiziert hatte. Sie drohte, Prof. Clay auffliegen zu lassen, wenn er sie nicht in seine Geheimnisse einweihte, und verschaffte sich einen Platz bei einer der ersten Silo-Prüfungen, die sie mit Bravour bestand. Ein Jahr später nahm man sie in den Zirkel auf, und von da an sammelte sie gierig Tinkturen von Mythen und baute die Aktivitäten des Kultes immer weiter aus.","sz":9.5,"box":[53.9,545.3,285.6,729.8],"p":144,"i":7,"sec":"alona-wainwright"},{"t":"p","x":"Wainwright, eine anziehende, erfolgreiche und willensstarke Frau Mitte 40, ist Geldgeberin und Rechtsberaterin des Kults. Sie finanziert eine Reihe von","sz":9.5,"box":[53.9,738.5,278.3,773],"p":144,"i":8,"sec":"alona-wainwright"},{"t":"p","x":"Anwält:innen, die die Kultmitglieder schützen und Feind:innen schikanieren. Sie nutzt ihren Einfluss und Verbindungen, um die Aufmerksamkeit der Strafverfolgungsbehörden und Medien von den Aktivitäten des Kults abzulenken.","sz":9.5,"box":[309,59.9,540.7,119.4],"p":144,"i":9,"sec":"alona-wainwright"},{"t":"p","x":"Als Trägerin der <b>Tinktur der Heiligen Drei Könige</b> verfügt Wainwright über umfangreiches magisches und astrologisches Wissen, das ritueller Natur ist und sich nicht für Konflikte eignet. Sie bewahrt die Tinktur in einem kleinen, aus Rubin geschliffenen Gefäß auf, das an ihrer Gürtelschnalle hängt. Oft trägt sie teuren Schmuck, um Diebe von der Tinktur abzulenken.","sz":9.5,"box":[309,128.1,538.1,212.6],"p":144,"i":10,"sec":"alona-wainwright"},{"t":"p","x":"Das Team kann Aktivitäten des Kults bis zu Wainwright zurückverfolgen. Für den Kult arbeitende Söldner:innen wie <b>Silvio Yadao</b> <u>(Die Ausgrabung),</u> die <b>Yakuza-Yōkai</b> und <b>Talia Al-Bahar</b> <u>(Schadensbegrenzung des Zirkels)</u> sind ihr direkt unterstellt, ebenso die Anwält:innen des Kults.","sz":9.5,"box":[309,221.3,539.2,293.3],"p":144,"i":11,"sec":"alona-wainwright"},{"t":"sh","x":"<b>NACHFORSCHUNGEN ÜBER ALONA WAINWRIGHT</b>","sz":10,"box":[309.4,306.9,457.2,328.9],"p":144,"i":12,"sec":"alona-wainwright"},{"t":"p","x":"Wainwright führt ihre Geschäfte von ihrem Büro im <b>Auktionshaus Wainwright</b>, das sich in einem prächtigen historischen Gebäude an der Grenze zwischen Alt- und Innenstadt befindet. Die Schwierigkeit, sie festzunageln, liegt in ihrem <b>täglichen Horoskop</b>, das jede Störung oder Bedrohung für sie selbst oder den Kult vorhersagt (wie man sich gegen diese Macht wehren kann s. <u>Schadensbegrenzung des Zirkels,</u> S. 117). Wenn das Team glaubt, sie in die Enge getrieben zu haben, ist sie nicht da, und eine böse Überraschung könnte auf die SC warten. Wenn das Team die Wahrsagung umgehen kann, könnte es Folgendes entdecken:","sz":9.5,"box":[309,334.4,538.4,481.4],"p":144,"i":13,"sec":"alona-wainwright"},{"t":"card","x":"<b>Wainwrights Aufgabe ist es, zusammen mit anderen Mitgliedern des Zirkels den Kult am Laufen zu halten</b>. Sie prüft die Zahl der Absolventen bei der <u>Silo-Prüfung,</u> in <u>Whirlers Kommune</u> und beim <u>Narrenfest,</u> als gäbe es eine Quote zu erfüllen.","sz":null,"k":"yellow","box":[309.3,495.1,541.7,578.9],"p":144,"i":14,"sec":"alona-wainwright"},{"t":"card","x":"Wie bei allen Mitgliedern des Zirkels ist <b>Wainwrights Vereinbarung mit dem Kult nicht spirituell, sondern transaktional: Wer mehr Macht erzeugt, erhält einen Teil.</b> Die Währung dieser Macht sind Tinkturen.","sz":null,"k":"yellow","box":[309.3,587.8,541.7,659.2],"p":144,"i":15,"sec":"alona-wainwright"},{"t":"card","x":"Die letzten beiden Phasen des Magnum-Opus- Prozesses finden in den <u>Katakomben</u> statt. Wainwright scheint ihren Lohn in Tinkturen zu erhalten, aber erst nachdem die vierte und letzte Phase abgeschlossen ist.","sz":null,"k":"yellow","box":[309.3,668.4,541.7,739.9],"p":144,"i":16,"sec":"alona-wainwright"}],"size":[595.276,841.89]},"145":{"tab":"","blocks":[{"t":"card","x":"<b>Ein- oder zweimal pro Woche übermittelt eine Initiant:in Berichte</b> aus <u>Whirlers Kommune</u> oder von den Ritualen in den <u>Katakomben.</u> Man kann ihnen zu beiden Orten folgen.","sz":null,"k":"yellow","box":[54.1,54.1,286.6,112.9],"p":145,"i":0,"sec":"alona-wainwright"},{"t":"card","x":"<b>Wainwright sammelt als Nebengeschäft Relikte, z. B. die Tafel von der <u>Ausgrabung.</u></b> Die Relikte schickt sie zum Athanor-Ofen/ nach Canseliet Manor (zur Ernte). Sie führt ein <t>verschlüsselt 2</t> Buch, in dem sie auflistet, welche Relikte sie verkauft (es enthält keine Informationen über menschliche Risse).","sz":null,"k":"yellow","box":[54.1,122.1,286.6,218.6],"p":145,"i":1,"sec":"alona-wainwright"},{"t":"card","x":"<b>Wainwright bewahrt ein halbes Dutzend Tinkturen in einem</b> <t>verschlossen 3</t> <b>und fallenbewehrten (</b><t>vergiftet 4</t> <b>und</b> <t>vom Pech verfolgt 4</t><b>, falls ausgelöst) Schmuckkästchen.</b> Es befindet sich im Safe des Auktionshauses, mit vielen anderen Gegenständen von Wert, darunter auch einige Relikte (die auf ihre Ernte warten).","sz":null,"k":"yellow","box":[54.1,227.5,286.6,324],"p":145,"i":2,"sec":"alona-wainwright"},{"t":"card","x":"<b>Wainwright benutzt die Tinktur der Heiligen Drei Könige, um auf magische Weise mit anderen Zirkelmitgliedern zu kommunizieren:</b> Sie können sich gegenseitig in der Oberfläche eines Wasserbeckens, in den Flammen eines Kamins oder in einer Rauch- und Nebelwolke sehen und hören.","sz":null,"k":"yellow","box":[54.1,333.2,286.6,429.4],"p":145,"i":3,"sec":"alona-wainwright"},{"t":"p","x":"<b>So kommuniziert Wainwright</b> auch mit dem “<b>Großer Lehrer</b>“, was zu Canseliet Manor und Armand Kai in <i>Der Alchemist</i> (s. S. 155) führt.","sz":10,"box":[62.4,444.2,272.1,479.3],"p":145,"i":4,"sec":"alona-wainwright"},{"t":"p","x":"<b>Wenn der Ofen noch in Betrieb ist, meldet sich Rachel Woods telefonisch</b> oder durch eine:n Kurier:in. Das könnte eine Verbindung von diesem Fall zu <i>Athanor</i> (s. S. 87) schaffen.","sz":10,"box":[62.4,499.7,269.2,559.7],"p":145,"i":5,"sec":"alona-wainwright"},{"t":"threat","stars":"★★★★","name":"ALONA WAINWRIGHT","spectra":"VERLETZEN ODER UNSCHÄDLICH MACHEN 3 / AB- KEHR VOM KULT 6","items":["<b>Kadavergehorsam:</b> Wenn sie die Szene betritt, gib ihr <t>fanatisch 5</t>, erneuerbar als harte Aktion.","<b>Meisterin der arkanen Künste</b>: Wenn sie ein Relikt oder magischen Effekt sieht oder wahrnimmt, weiß sie sofort, worum es sich handelt und wie man sie kontern kann. Wenn jemand ein Relikt oder Magie gegen sie einsetzt, verleiht sie sich einen temporären <t>Gegenzauber 3</t>, der die Aktion behindert.","<b>Leibwächter:innen</b>: Wenn Alona Wainwright einen Zustand erhält, vor dem Leibwächter:innen schützen können, nehmen diese den Zustand stattdessen (verwende <b>Initiant:innen</b>, S. 121).","<b>Transmutation von Metallen und Edelsteinen</b>: Wenn Alona Wainwright einen Zustand erhält, der Metalle oder Edelsteine beinhaltet, kann sie bis zu 3 Stufen davon auf ein anderes Ziel umleiten.","Den Agent:innen des Kults den Befehl zum Angriff geben (Erzeuge eine der Bedrohungen unter <u>Schadensbegrenzung des Zirkels,</u> S. 117)","Eine magische Fähigkeit oder Relikt kontern (2 Relikt-Marker verbrennen)","Fehlzündungen bei Schusswaffen verursachen und Hieb-, Stich- und Schlagwaffen aus Metall angreifen lassen (<t>Schusswunde 3</t> oder <t>verwundet 3</t>, ein Ziel pro Waffe am Schauplatz der Szene)","Sich über jede Störung ihres Zeitplans beschweren","Mit den Fingern schnipsen und mit dem Daumen den Gürtel mit Juwelen berühren, um zu zaubern"],"box":[424.4,57.5,465.2,69.5],"desc":"Alona Wainwright beherrscht die Transmutation von Metallen und Edelsteinen, eingebrannt im Nacken unter ihrem wallenden Haar. Außerdem besitzt sie die Tinktur der Heiligen Drei Könige, die ihr magische und astrologische Fähigkeiten verleiht.","p":145,"i":6,"sec":"alona-wainwright"}],"size":[595.276,841.89]},"146":{"tab":"","blocks":[{"t":"h","x":"SCHICHT 4:","sz":14,"box":[53.9,61.9,122.1,75.9],"p":146,"i":0,"skip":true,"sec":"schicht-4-das-heilige-feuer"},{"t":"h","x":"DAS HEILIGE FEUER","sz":23,"box":[53.9,84.2,235.7,107.2],"p":146,"i":1,"skip":true},{"t":"h","x":"DIE KATAKOMBEN","sz":16,"box":[79.7,120.8,198,136.8],"p":146,"i":2,"skip":true,"sec":"die-katakomben"},{"t":"ro","x":"Zu den Klängen eines sich wiederholenden lateinischen Gesangs und einem gelegentlichen erstickten Wimmern bahnt ihr euch einen Weg durch die unterirdischen Gänge. Die leeren Augenhöhlen tausender in die Wände eingelassener menschlicher Schädel starren euch an. Ihr kommt an fackelbeleuchteten Nischen vorbei und seht in jeder den zitternden Körper von Initiant:innen, die an einen wuchtigen Altar, einen Felsen oder einen U-Bahn-Waggon gefesselt sind. Eine feierliche Prozession von Kultist:innen in Gewändern mit Kapuzen, die ein goldenes Becken tragen, geht von einem Opferlamm zum nächsten. Wenn sie neben den Opfern stehen, singen sie, und ein Knistern ertönt, während unheimliche grüne Lichtblitze die Wände erhellen und Schatten werfen. Gleich darauf setzt die Prozession den Weg fort, erschöpfter, aber mit größerem Eifer.","sz":9,"box":[62.4,139.2,283.8,364.2],"p":146,"i":3,"sec":"die-katakomben"},{"t":"p","x":"ihre verbotenen Experimente durchzuführen, sind die Katakomben heute eine Kaserne von der Größe eines Armeestützpunktes, die tief unter der Stadt liegt. Dank der Macht der Erdtransformation, über die die Jünger:innen des Kults verfügen, können sie den Komplex bei Bedarf an einen anderen Ort bewegen. Die Zugänge in Form verlassener U-Bahn-Tunnel sind aus Bausteinen gebildet und lassen sich abbauen.","sz":9.5,"box":[309,59.9,540.9,156.9],"p":146,"i":4,"sec":"die-katakomben"},{"t":"p","x":"Die mit Kerzen beleuchteten Tunnel, Korridore und Kammern der Katakomben sind mit den Originalschädeln und -knochen der hier Begrabenen gesäumt, eine Erinnerung an das tödliche Schicksal, das die Kultist:innen erwartet, wenn sie ihre mystische Berufung nicht erfüllen (oder den Gottkönig verraten). Der Komplex ist in drei Abschnitte unterteilt: den Hof der Initiant:innen, den Hof der Jünger:innen und das Allerheiligste.","sz":9.5,"box":[309,165.6,536.2,275.1],"p":146,"i":5,"sec":"die-katakomben"},{"t":"sh","x":"<b>DER HOF DER INITIANT:INNEN</b>","sz":10,"box":[309.4,288.7,478.9,298.7],"p":146,"i":6,"sec":"die-katakomben"},{"t":"p","x":"Wenn die Initiant:innen die Katakomben zum ersten Mal betreten, ziehen sie die goldfarbenen Gewänder an, die den Beginn der <b>Gilbungsphase</b> markieren, und schließen sich dem Leben in Knechtschaft an. Man zeigt ihnen ihre kargen Wohnräume, alles ist schlicht und spartanisch. Für Sozialkontakte und Untätigkeit ist keine Zeit. Alle wissen, dass sie eine Aufgabe zu erfüllen haben, und das Endziel des Magnum Opus ist allgegenwärtig. Initiant:innen dürfen den Hof der Jünger oder das Allerheiligste nicht alleine betreten.","sz":9.5,"box":[309,304.3,538.7,426.3],"p":146,"i":7,"sec":"die-katakomben"},{"t":"p","x":"Die Katakomben sind das geheime Hauptquartier des Kults des Gottkönigs. Ursprünglich ein Komplex von Grabkammern unter der Altstadt, in denen sich die Alchemist:innen von früher heimlich versammelten, um","sz":9.5,"box":[53.9,373.2,283.7,420.2],"p":146,"i":8,"sec":"die-katakomben"}],"size":[595.276,841.89]},"147":{"tab":"","blocks":[{"t":"p","x":"<b>Die Lämmer unter den Initiant:innen</b> sind in ihren Kammern eingeschlossen. Von ihnen erwartet man, dass sie die Texte und Geheimnisse der Alchemie studieren, um sich auf ihre Erweckung vorzubereiten. Tatsächlich hält der Kult sie nur fest, bis die Vorbereitung für das Salbungsritual abgeschlossen ist.","sz":9.5,"box":[53.9,62.5,280.7,134.5],"p":147,"i":0,"sec":"die-katakomben"},{"t":"p","x":"<b>Die Wölf:innen unter den Initiant:innen</b> unterstellt man einer Jünger:in. Sie nehmen an Aktivitäten in der Stadt teil, wie z. B. dem Angriff auf das <u>Chinatown-Festival</u> oder den Raubzug auf die <u>Ausgrabung.</u> In einer Reihe von Labors stellen sie ihre chemischen Formeln zusammen. Die Initiant:innen gehen davon aus, dass der Kult Feinde hat und sie alles tun müssen, um das Überleben zu sichern, damit er sein Werk vollenden kann.","sz":9.5,"box":[53.9,143.2,283.1,252.7],"p":147,"i":1,"sec":"die-katakomben"},{"t":"p","x":"SC, die sich in diesem Stadium befinden, haben vielleicht das Gefühl, dass etwas nicht stimmt. Nach den lebensverändernden Opfern, die sie bei der <b>Schwärzung</b> und <b>Weißung</b> gebracht haben, erscheinen Studium und Bot:innengänge nicht gerade als mystische Erfahrung. Die Jünger:innen versprechen, das nächste Ritual werde das alles wert sein.","sz":9.5,"box":[53.9,261.3,280.9,345.8],"p":147,"i":2,"sec":"die-katakomben"},{"t":"sh","x":"<b>DER HOF DER JÜNGER:INNEN</b>","sz":10,"box":[54.3,359.4,213.7,369.4],"p":147,"i":3,"sec":"die-katakomben"},{"t":"p","x":"Während die Jünger:innen überall in der Stadt Schlüsselpositionen besitzen (vor allem in <u>Canseliet Manor,</u> s. <i>Der Alchemist</i>, S. 155), sind die Katakomben ihr Quartier. Versiert in elementaren Transmutationen versuchen sie, ihre alchemistischen Kräfte durch den Dienst am Gottkönig zu erweitern, in der Hoffnung, vom Großen Lehrer (Armand oder der Zirkel, wenn du den Fall nicht als Kampagne spielst) zu lernen und die ultimative Macht zu erlangen, die man versprochen hat. Sie trainieren unermüdlich in speziellen Einrichtungen und bereiten sich auf den Moment vor, in dem sie über eine <b>ewige Flamme</b>, die in einem der Räume brennt, oder eine Bot:in Befehle erhalten.","sz":9.5,"box":[53.9,375,282.1,534.5],"p":147,"i":4,"sec":"die-katakomben"},{"t":"sh","x":"<b>DAS ALLERHEILIGSTE</b>","sz":10,"box":[54.3,548.1,173.7,558.1],"p":147,"i":5,"sec":"die-katakomben"},{"t":"p","x":"Im Zentrum der Katakomben befindet sich ein System von Gängen und Kammern, das für das <b>Salbungsritual</b>, das Riss-Erweckungsritual, dient. In seinem Zentrum steht ein goldenes Becken mit dem wichtigsten Relikt und Bestandteil des Magnum Opus: dem zweifach verdünnten Gralswasser, geläutertes Wasser, in dem ein Tropfen von Armand Kais Gralswassers gelöst ist. Der Zugang zum Allerheiligsten ist durch feste Erde versperrt. Hier stehen stets Jünger:innen Wache. Das Allerheiligste ist nur während des Salbungsrituals zugänglich.","sz":9.5,"box":[53.9,563.7,283.9,698.2],"p":147,"i":6,"sec":"die-katakomben"},{"t":"sh","x":"<b>DAS SALBUNGSRITUAL</b>","sz":10,"box":[54.3,711.8,179.7,721.8],"p":147,"i":7,"sec":"die-katakomben"},{"t":"p","x":"<b>Das Salbungsritual beendet die Gilbungsphase.</b> Man bringt die Initiant:innen in das Allerheiligste und kettet sie an einen Altar oder schweren Gegenstand.","sz":9.5,"box":[53.9,727.5,283.4,761.8],"p":147,"i":8,"sec":"die-katakomben"},{"t":"h","x":"SICHERHEITSMASSNAHMEN IN DEN KATAKOMBEN","sz":12,"box":[320.3,60.8,523.5,72.8],"p":147,"i":9,"sec":"die-katakomben"},{"t":"p","x":"Der Kult hat Sicherheitsvorkehrungen getroffen, um seine Festung zu schützen:","sz":9,"box":[320.3,85.9,523.9,106.9],"p":147,"i":10,"sec":"die-katakomben"},{"t":"p","x":"• <b>Zugang durch Erdtransmutation:</b> Die Katakomben, die tief unter der Erde liegen und nach Gutdünken des Zirkels mobil sind, können nur die betreten, die (a) wissen, wo sie sich gerade befinden und (b) durch feste Erde reisen können. Jünger:innen mit Erdtransmutation dienen als Wache, die alte U- Bahn- und Servicetunnel öffnen und schließen, um ihre Basis mit dem Tunnelnetz zu verbinden.","sz":9,"box":[323.1,118.4,529.5,211.4],"p":147,"i":11,"sec":"die-katakomben"},{"t":"p","x":"• <b>Astrologische Orakel:</b> Der Kult überwacht das Horoskop der Katakomben intensiver als jeden anderen Aspekt der Operation. Wenn du die <u>Schadensbegrenzung des Zirkels</u> noch nicht eingesetzt hast, um die SC in eine Sackgasse oder einen Hinterhalt zu locken, wäre jetzt ein guter Zeitpunkt.","sz":9,"box":[323.1,220.1,528.6,289.1],"p":147,"i":12,"sec":"die-katakomben"},{"t":"p","x":"• <b>Magische Wachen:</b> Der Zirkel besteht aus Ritualmagier:innen. Sie haben magische Schutzwälle errichtet, die Hellsicht oder magische Infiltrationsversuche (Teleportation, Gestaltwandel usw.) abwehren und den Zirkel alarmieren. Der Hof der Eingeweihten verfügt über ein <t>Schutzzeichen 1</t>, der Hof der Jünger über ein <t>Schutzzeichen 2</t> und das Allerheiligste über ein <t>Schutzzeichen 3</t>.","sz":9,"box":[323.1,297.7,530.1,390.7],"p":147,"i":13,"sec":"die-katakomben"},{"t":"p","x":"• <b>Das Rätsel der Initiant:innen:</b> Dieses Rätsel ist die magische Version eines Codeschlosses und dient als weitere Barriere für Eindringlinge (s. S. 143).","sz":9,"box":[323.1,399.4,528,432.4],"p":147,"i":14,"sec":"die-katakomben"},{"t":"p","x":"• <b>Mitglieder auf Wache</b> (<t>aufmerksam 1</t>) patrouillieren in den Gängen aller drei Abschnitte.","sz":9,"box":[323.1,441.1,524.2,462.1],"p":147,"i":15,"sec":"die-katakomben"},{"t":"p","x":"• <b>Andere Kultanhänger</b>: Wenn der Zirkel einen Angriff auf die Katakomben befürchtet, kann er Talia Al-Bahar oder die Yakuza Yōkai in das Allerheiligste beordern, mit der Anweisung, die Eindringlinge zu bekämpfen oder das Gralswasser zu sichern.","sz":9,"box":[323.1,470.8,527.4,527.8],"p":147,"i":16,"sec":"die-katakomben"},{"t":"p","x":"• <b>Ob Lämmer oder Wölf:innen: Identifizierte Risse werden nur angekettet.</b> Am Ende behandelt man sie sie wie gesalbte Lämmer (ihr Zustand <t>fanatisch</t>, falls vorhanden, erschwert den Widerstand).","sz":9.5,"box":[309,565.6,539.1,612.6],"p":147,"i":17,"sec":"die-katakomben"},{"t":"p","x":"• <b>Wölf:innen erhalten eine Transmutation</b>, indem man ihnen das alchemistische Symbol ihres Elements einbrennt. Das verursacht <t>höllische Schmerzen 3</t> und sie gelten als dauerhaft von Armands Mythos berührt. Sie werden zu <b>Jünger:innen</b>, aber anfangs sind ihre Kräfte <t>unkontrollierbar 2</t>, und sie müssen trainieren, um das aufzuheben. <b>Nach dem Ritual bringt man sie zur Genesung in den Hof der Jünger:innen. Die Lämmer sehen sie nie wieder.</b>","sz":9.5,"box":[309,621.3,536.3,743.4],"p":147,"i":18,"sec":"die-katakomben"}],"size":[595.276,841.89]},"148":{"tab":"","blocks":[{"t":"p","x":"• <b>Lämmer salbt man mit dem zweifach verdünnten Gralswasser, und sie verwandeln sich in Risse.</b> Die legendäre Macht ihres Mythos bricht sich Bahn und macht manche Kammer dem Erdboden gleich oder verletzt diejenigen, die das Ritual durchführen. <t>Überwältigt 3</t> kommen sie zu sich. Ihr Zustand <t>fanatisch</t> hilft, ihre Macht zu kontrollieren und zwingt sie, den Jünger:innen zu gehorchen. <b>Am Ende des Rituals versammelt man die Lämmer und vorherigen Risse und erklärt, sie ständen vor der Vereinigung mit dem Gottkönig, die totale Erleuchtung bringt. Dann schickt man sie zur Ernte.</b>","sz":9.5,"box":[53.9,62.5,286.2,222.1],"p":148,"i":0,"sec":"die-katakomben"},{"t":"card","x":"<b>Mit dem nötigen alchemistischen Wissen</b> kann man dieses Ritual mit der Stufe der Gilbung oder des Erwachens des alchemistischen Magnum Opus in Verbindung bringen. Der nächste Schritt ist die Rötung oder Transformation, die mit dem Gottkönig, der Quelle allen Lebens, vereint.","sz":null,"k":"yellow","box":[54.1,236.2,286.6,332.6],"p":148,"i":1,"sec":"die-katakomben"},{"t":"card","x":"Das Wasser im goldenen Becken hat die Macht, Schläfer:innen zu erwecken.","sz":null,"k":"yellow","box":[54.1,341.9,286.6,375.6],"p":148,"i":2,"sec":"die-katakomben"},{"t":"card","x":"Das Einbrennen der alchemistischen Symbole verleiht den Jüngern alchemistische Kräfte.","sz":null,"k":"yellow","box":[54.1,384.8,286.6,418.8],"p":148,"i":3,"sec":"die-katakomben"},{"t":"sh","x":"<b>DAS ERNTERITUAL</b>","sz":10,"box":[54.3,431.5,158,441.5],"p":148,"i":4,"sec":"die-katakomben"},{"t":"p","x":"<b>Der Kult wartet nicht lange, um die Risse zu ernten</b> und führt sie ins „heilige Feuer“: eine mythenschmelzende Flamme, die die Legende ablöst, woraufhin man sie als flüchtige, ätzende Substanz namens Ichor auffangen und zu einer Tinktur veredeln kann. Die genauen Regeln dieses Prozesses finden sich in <i>Athanor</i> (s. S. 109).","sz":9.5,"box":[53.9,447.2,284,531.6],"p":148,"i":5,"sec":"die-katakomben"},{"t":"p","x":"Wenn du die Kampagne spielst, kann die Ernte am Ofen (<i>Athanor</i>, S. 109) oder in der Ichor-Destillerie (<i>Der Alchemist</i>, S.163) sein. Wenn du ein Einzelabenteuer spielst oder es besser zu deinem Spiel passt, hat der Zirkel einen Raum im Allerheiligsten, wo das „heilige Feuer“ brennt und er die Ernte durchführt.","sz":9.5,"box":[53.9,540.3,282.8,612.3],"p":148,"i":6,"sec":"die-katakomben"},{"t":"p","x":"Unabhängig vom Ort der Ernte treiben die Jünger:innen die Risse zusammen und führen sie nacheinander in die Flammen, wobei sie ihre bevorstehende Vereinigung mit dem Gottkönig preisen, während die <t>fanatischen</t> Risse sich fügen. Sie glauben, dass sie lang ersehnte Antworten oder Kräfte erlangen werden. Stattdessen entsteigen die Lämmer dem „heiligen Feuer“ als seelenlose Schläfer:innen ohne ihre einzigartige Kraft – ihren Mythos – und ohne Hoffnung, je wieder zu erwachen.","sz":9.5,"box":[53.9,620.9,281.5,742.9],"p":148,"i":7,"sec":"die-katakomben"},{"t":"card","x":"<b>Mit alchemistischen Wissen</b> lässt sich das Ritual mit der Rötungsstufe des Magnum Opus in Verbindung bringen: der Vereinigung mit dem Gottkönig. <b>Doch irgendetwas stimmt nicht: Man hat nicht das <i>Gefühl</i>, dass jemand der Wahrheit näher gekommen ist.</b>","sz":null,"k":"yellow","box":[309.3,54.1,541.7,138],"p":148,"i":8,"sec":"die-katakomben"},{"t":"card","x":"Die Jünger:innen, die die Lämmer ins „heilige Feuer“ führen, haben dieses Ritual schon einmal gesehen. Sie glauben kein Wort von dem, was sie den Lämmern sagen.","sz":null,"k":"yellow","box":[309.3,147.2,541.7,205.9],"p":148,"i":9,"sec":"die-katakomben"},{"t":"card","x":"<b>Der Gang ins „heilige Feuer“ ist nicht das Tor zur Erleuchtung, sondern zum permanenten Schlaf.</b> Das „Feuer“ schmilzt den Mythos zu ätzenden Glibber. Risse kommen praktisch hirntot heraus und erinnern sich an nichts. Auf den ersten Blick mag dies wie Erleuchtung erscheinen, doch bald wird klar: Sie sind gewöhnliche Menschen ohne Macht und Verbindung zur Quelle. Tatsächlich scheint jedes Funkeln in ihren Augen erloschen zu sein.","sz":null,"k":"yellow","box":[309.3,215.1,541.7,349.1],"p":148,"i":10,"sec":"die-katakomben"},{"t":"card","x":"Das wirft ein Licht auf die Motive des Kultes des Gottkönigs: <b>„Magnum Opus“ ist eine von Machtbesessenheit getriebene Manufaktur, die Menschen mystischen Kräfte entzieht.</b>","sz":null,"k":"yellow","box":[309.3,358.3,541.7,417],"p":148,"i":11,"sec":"die-katakomben"},{"t":"sh","x":"<b>DANACH: SPUREN VERWISCHEN</b>","sz":10,"box":[309.4,434.1,484.3,444.1],"p":148,"i":12,"sec":"die-katakomben"},{"t":"p","x":"Sobald die Katze aus dem Sack ist (oder genügend Beweise vorliegen), kann das Team eine der folgenden Maßnahmen ergreifen:","sz":9.5,"box":[309,449.7,536.9,484.2],"p":148,"i":13,"sec":"die-katakomben"},{"t":"p","x":"• <b>Initiant:innen vor dem Erwachen oder der Ernte retten</b>: Das Team kann die Rituale sabotieren oder die Initiant:innen von der Wahrheit überzeugen: Zu sehen, wie andere betäubt und mit leerem Blick aus dem „heiligen Feuer“ auftauchen oder wie der Kult den Ichor erntet hat eine ernüchternde Wirkung. Gib den SC Geschichten-Marker für jeden Beweis, den sie den Anwärter:innen zeigen, um den <t>fanatischen</t> Zustand zu durchbrechen und ihre <i>Abkehr vom Kult</i> voranzutreiben(s. S. Bedrohungen des Magnum Opus, S. 120).","sz":9.5,"box":[309,495.7,539.8,630.2],"p":148,"i":14,"sec":"die-katakomben"},{"t":"p","x":"• <b>Die Katakomben zum Einsturz bringen</b>: Damit ist gemeint, alle Agent:innen vor Ort zu besiegen und die Anlage physisch zu zerstören. Das Team möchte vielleicht das Gralswasser retten.","sz":9.5,"box":[309,638.8,538.1,685.8],"p":148,"i":15,"sec":"die-katakomben"},{"t":"p","x":"• <b>Die gesamte Kultoperation lahmlegen</b>: Das Team könnte Schlüsselfiguren wie Prof. Clay, Whirler und Alona Wainwright festnehmen oder sabotieren. Dabei könnte es zu einem Kampf um politischen Einfluss kommen, wenn der Zirkel versucht, Fäden zu ziehen, um das Team loszuwerden.","sz":9.5,"box":[309,694.5,536.9,766.5],"p":148,"i":16,"sec":"die-katakomben"}],"size":[595.276,841.89]},"149":{"tab":"","blocks":[{"t":"p","x":"Wenn du die Kampagne spielst, <b>führt die Spur zu dem Mann hinter dem Kult: dem Großen Lehrer, dem Alchemisten Armand Kai, der in Canseliet Manor residiert</b> (beschrieben im letzten Fall der mystischen Ebene, <i>Der Alchemist</i>). Das Team kann das Herrenhaus finden, indem es einer Lieferung geernteten Ichors folgt, eine Nachricht der Zirkelmitglieder abhört, geflohene Jünger:innen verfolgt oder die Quelle des Gralswassers sucht.","sz":10,"box":[62.4,59.7,274.7,182.2],"p":149,"i":0,"sec":"die-katakomben"},{"t":"p","x":"Außerdem stellt das Gralswasser eine Verknüpfung zum Mythos des Fischerkönigs (Corbin Payne). <b>Nachforschungen</b> sollten Hinweise zum Metaplot und <i>Parzival</i> (s. S. 259) liefern.","sz":10,"box":[62.4,202.7,276.8,250.3],"p":149,"i":1,"sec":"die-katakomben"},{"t":"card","x":"<u>ABSPANN</u>","sz":null,"k":"yellow","box":[39.5,479.2,160.4,506.6],"p":149,"i":2,"sec":"die-katakomben"},{"t":"p","x":"Im Folgenden findest du einige Fragen, die du dir stellen solltest, und Punkte, die es beim Abschluss dieses Falles noch einmal zu überdenken gilt:","sz":9.5,"box":[53.9,513.2,282.3,546.7],"p":149,"i":3,"sec":"die-katakomben"},{"t":"p","x":"• Wie ist das Team aus dem Kontakt mit dem Magnum Opus hervorgegangen? Ist ein Mitglied dem angebotenen Weg gefolgt, und wenn ja, wie weit ist es gegangen? Wessen Leben hat sich für immer verändert, durch den Kult oder ein freiwilliges Opfer?","sz":9.5,"box":[53.9,557.7,285.7,615.2],"p":149,"i":4,"sec":"die-katakomben"},{"t":"p","x":"• In welchem Zustand befindet sich Magnum Opus am Ende des Falles? Ist es aufgelöst, oder könnte jemand es aufbauen? Wo sind Schlüsselfiguren wie der Zirkel, Alona Wainwright, Prof. Clay und Whirler? Würde Prof. Clay weiter für den Kult rekrutieren oder einen neuen Weg suchen, um das alchemistische Magnum Opus zu schaffen?","sz":9.5,"box":[53.9,623.3,286.3,704.8],"p":149,"i":5,"sec":"die-katakomben"},{"t":"p","x":"• Was ist aus den Kultmitgliedern geworden? Haben sie alles für Wissen und Macht geopfert? Konnten sich einige vom Kult befreien und ihr Leben neu aufbauen? Wenn Armand noch Macht hat, haben sie sich auf Canseliet Manor zurückgezogen? Oder set-","sz":9.5,"box":[53.9,713,282.1,770.5],"p":149,"i":6,"sec":"die-katakomben"},{"t":"h","x":"DAS ZWEIFACH VERDÜNNTE GRALSWASSER","sz":14,"box":[323.9,61,525.9,75],"p":149,"i":7,"sec":"die-katakomben"},{"t":"p","x":"Die Substanz, die das Magnum Opus zur Erweckung von Rissen verwendet, ist eine verdünnte Lösung aus destilliertem Wasser und einem Tropfen Gralswasser. Letzteres hat Armand von Corbin Payne bekommen, in der Hoffnung, dass der Alchemist ein Heilmittel für sein legendäres Leiden finden könnte. Armand bewahrt es in seinem Labor auf (s. S. <i>Der Alchemist,</i> S. 170), und gibt dem Kult eine verdünnte Version, was die ursprüngliche Kraft verwässert.","sz":9,"box":[323.9,87.5,530.9,192.5],"p":149,"i":8,"sec":"die-katakomben"},{"t":"p","x":"In dieser Kampagne repräsentiert der Gral die Macht der Wahrheit, der Transformation und Heilung. Armand und sein Kult benutzen ihn, um einen Mythos in Menschen zu erwecken, ehe sie auf grausame Weise diese Essenz entreißen und die Opfer in hoffnungslose Schatten verwandeln.","sz":9,"box":[323.9,201.2,533.6,270.2],"p":149,"i":9,"sec":"die-katakomben"},{"t":"p","x":"Behandle diese Substanz wie einen Joker. Wenn man einen Riss damit salbt, kann er weiter erwachen, ein Logos-Thema durch ein Mythos-Thema ersetzt, oder vorübergehend <b>durch den Nebel sehen</b> (wie bei einem Entwicklungssprung, <i>Spieler:innen- Handbuch</i>, S. 269). In der verdünnten Version könnte sie Wunder wirken, die einem bedeutenden Opfer bei <b>Jetzt reicht’s!</b> entsprechen. Erzählerisch könnte sie jemanden dazu bringen, eine Wahrheit zu sehen, oder schwere Wunden heilen.","sz":9,"box":[323.9,278.8,532.3,395.8],"p":149,"i":10,"sec":"die-katakomben"},{"t":"p","x":"zen manche die Suche auf eigene Faust fort? Was ist mit den Anhänger:innen, die das Team retten sollte? Sind sie zurück bei ihren Familien?","sz":9.5,"box":[317.5,513.2,539.4,546.7],"p":149,"i":11,"sec":"die-katakomben"},{"t":"p","x":"• Was ist mit den Tinkturen und dem zweifach verdünnten Gralswasser? Wenn der Kult oder Armand fallen, verlieren diese ihre Macht? Die mächtigen Artefakte können in den falschen Händen verheerenden Wirkung haben. Wie gedenkt das Team, sie zu entsorgen? Kann es die Mythos-Essenzen den Menschen zurückzugeben, denen sie gehören, und wenn ja, sollte es das?","sz":9.5,"box":[309,554.9,531.1,648.4],"p":149,"i":12,"sec":"die-katakomben"},{"t":"p","x":"• Haben der Magnum Opus und seine Möglichkeiten, einen bleibenden Eindruck auf das Team oder Nebendarsteller:innen hinterlassen? Werden sie versuchen zu verstehen, was jenseits dieser Welt liegt? Vielleicht wäre Ariadne bereit, sie zu führen.","sz":9.5,"box":[309,656.5,539.9,714],"p":149,"i":13,"sec":"die-katakomben"},{"t":"p","x":"• Was ist aus den Menschen auf der Ausgrabung passiert? Silvio Yadao und seine Tochter Helena, Mondgeist und das Team von Helix Labs? Wer hat die Tafel für das Lebenselixier, und wird es genutzt?","sz":9.5,"box":[309,722.2,541.1,767.7],"p":149,"i":14,"sec":"die-katakomben"}],"size":[595.276,841.89]}},"figures":[{"id":"eisberg","page":117,"kind":"eisberg","title":"Der Eisberg","file":"img/case05/eisberg.webp","box":[0,0,595,500],"after":null},{"id":"titelbild","page":113,"kind":"art","title":"Titelbild: Der Kult des Gottkönigs","file":"img/case05/titelbild.webp","box":[0,0,595,820],"after":null},{"id":"kult-illustration","page":123,"kind":"art","title":"Illustration: Yakuza-Yōkai und Kultisten","file":"img/case05/kult-illustration.webp","box":[45,0,595,795],"after":null},{"id":"ariadne-art","page":125,"kind":"art","title":"Ariadne","file":"img/case05/ariadne-art.webp","box":[305,0,595,795],"after":null},{"id":"ariadne-wollknaeuel","page":126,"kind":"art","title":"Themenkarte: Ariadnes Wollknäuel","file":"img/case05/ariadne-wollknaeuel.webp","box":[308,414,544,707],"after":null},{"id":"chinatown-drache","page":132,"kind":"art","title":"Chinatown-Festival: Der Feuerdrache","file":"img/case05/chinatown-drache.webp","box":[0,0,595,342],"after":null},{"id":"mondgeist-karte","page":133,"kind":"art","title":"Themenkarte: Mondgeist","file":"img/case05/mondgeist-karte.webp","box":[335,526,590,789],"after":null},{"id":"silo-plan","page":137,"kind":"plan","title":"Plan: Das Silo der Silo-Prüfung","file":"img/case05/silo-plan.webp","box":[320,44,595,787],"after":null},{"id":"anhaenger-karte","page":137,"kind":"art","title":"Themenkarte: Anhänger:in des Gottkönigs","file":"img/case05/anhaenger-karte.webp","box":[55,271,295,582],"after":null},{"id":"raetsel-symbole","page":143,"kind":"handout","title":"Rätsel der Initiant:innen: Symbole der Phasen","file":"img/case05/raetsel-symbole.webp","box":[55,664,539,776],"after":null},{"id":"katakomben-art","page":146,"kind":"art","title":"Illustration: Das Salbungsritual in den Katakomben","file":"img/case05/katakomben-art.webp","box":[0,437,595,795],"after":null},{"id":"szene-p26","page":119,"kind":"art","title":"Szene","file":"img/case05/szene-p26.webp","box":[0,0,0,0],"after":null},{"id":"szene-p27","page":126,"kind":"art","title":"Szene","file":"img/case05/szene-p27.webp","box":[0,0,0,0],"after":null},{"id":"szene-p29","page":141,"kind":"art","title":"Szene","file":"img/case05/szene-p29.webp","box":[0,0,0,0],"after":null}],"eisberg":{"page":117,"fig":"eisberg","nodes":[{"label":"Suchende","layer":0,"x":27.8,"y":14.5,"w":11,"h":9.5,"target":"schicht-0-aufhaenger"},{"label":"Ariadne","layer":0,"x":42.8,"y":14.1,"w":11,"h":9.5,"target":"ariadne-und-magnum-opus"},{"label":"Sich um Suchende sorgen","layer":0,"x":57.2,"y":13.7,"w":11,"h":9.5,"target":"schicht-0-aufhaenger"},{"label":"Athanor","layer":0,"x":70.3,"y":13.4,"w":11,"h":9.5,"target":"schicht-0-aufhaenger"},{"label":"Silvio Yadao","layer":0,"x":84.1,"y":13.4,"w":11,"h":9.5,"target":"schicht-0-aufhaenger"},{"label":"Prof. Clay","layer":1,"x":40,"y":22.4,"w":11,"h":9.5,"target":"schicht-1-eine-kerze-in-der-dunkelheit"},{"label":"1x1 der Alchemie","layer":1,"x":56.4,"y":22.8,"w":11,"h":9.5,"target":"1x1-der-alchemie"},{"label":"Chinatown-Festival","layer":1,"x":71.7,"y":22,"w":11,"h":9.5,"target":"chinatown-festival"},{"label":"Die Silo-Prüfung","layer":2,"x":40.6,"y":29.5,"w":11,"h":9.5,"target":"schicht-2-gefaehrliche-ausgrabungen"},{"label":"Valériens Kuriosa","layer":2,"x":55.2,"y":30.6,"w":11,"h":9.5,"target":"val-riens-kuriosa"},{"label":"Die Ausgrabungsstätte","layer":2,"x":69.4,"y":30.6,"w":11,"h":9.5,"target":"schicht-2-gefaehrliche-ausgrabungen"},{"label":"Whirlers Kommune","layer":3,"x":38.6,"y":37.7,"w":11,"h":9.5,"target":"whirlers-kommune"},{"label":"Das Narrenfest","layer":3,"x":53.1,"y":38.5,"w":11,"h":9.5,"target":"schicht-3-schatten-der-wahrheit"},{"label":"Alona Wainwright","layer":3,"x":66.1,"y":38.1,"w":11,"h":9.5,"target":"alona-wainwright"},{"label":"Die Katakomben","layer":4,"x":53.9,"y":47.1,"w":11,"h":9.5,"target":"die-katakomben"},{"label":"Schadensbegrenzung des Zirkels","layer":0,"x":85.6,"y":34.6,"w":7,"h":26,"target":"schicht-0-aufhaenger"}]}};
